update public.stage_fields f set translations = '{"de":{"question":"Beschreibe die Person oder Organisation, die das Problem betrifft.","help":"Rolle, Situation, Branche — was für deine Idee wichtig ist. Statt „Unternehmer“ schreib „Inhaber kleiner Onlineshops“."},"uk":{"question":"Опиши людину чи організацію, якої стосується проблема.","help":"Роль, ситуація, галузь — те, що важливо для твоєї ідеї. Замість «підприємці» напиши «власники невеликих інтернет-магазинів»."},"es":{"question":"Describe a la persona u organización a la que afecta el problema.","help":"Rol, situación, sector: lo que importa para tu idea. En lugar de «emprendedores», escribe «dueños de pequeñas tiendas online»."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
