update public.stage_fields f set translations = '{"de":{"question":"Wie ernst ist dieses Problem für die betroffene Person?","help":"1 ist eine kleine Unannehmlichkeit, 3 eine deutliche Erschwernis, 5 ernste Folgen.","config":{"min_label":"Kleine Unannehmlichkeit","max_label":"Ernste Folgen"}},"uk":{"question":"Наскільки серйозна ця проблема для людини, якої вона стосується?","help":"1 — дрібна незручність, 3 — відчутна перешкода, 5 — серйозні наслідки.","config":{"min_label":"Дрібна незручність","max_label":"Серйозні наслідки"}},"es":{"question":"¿Qué gravedad tiene este problema para la persona afectada?","help":"1 es una pequeña molestia, 3 una dificultad clara, 5 consecuencias graves.","config":{"min_label":"Pequeña molestia","max_label":"Consecuencias graves"}}}'::jsonb
