update public.stage_fields f set translations = '{"de":{"question":"Wie dringend muss das gelöst werden?","help":"Das ist eine andere Frage als die Schwere. Ein Problem kann schmerzhaft sein, aber erst in einigen Monaten auftreten.","config":{"min_label":"Kann warten","max_label":"Muss sofort gelöst werden"}},"uk":{"question":"Наскільки терміново це треба розв’язати?","help":"Це інше запитання, ніж серйозність. Проблема може бути болючою, але з’являтися лише за кілька місяців.","config":{"min_label":"Можна почекати","max_label":"Треба розв’язати негайно"}},"es":{"question":"¿Con qué urgencia hay que resolverlo?","help":"Es otra pregunta distinta de la gravedad. Un problema puede ser doloroso, pero aparecer solo dentro de unos meses.","config":{"min_label":"Puede esperar","max_label":"Hay que resolverlo ya"}}}'::jsonb
