update public.stage_fields f set translations = '{"de":{"question":"Welche weiteren Annahmen gibt es?"},"uk":{"question":"Які ще є припущення?"},"es":{"question":"¿Qué otras suposiciones hay?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'hipoteza-rozwiazania'
    and s.key = 'zalozenie-do-testow' and f.key = 'pozostale';
update public.stage_points p set translations = '{"de":{"title":"Prüfe, wie andere dieses Problem lösen","guide_body":"Hier prüfst du, welche Möglichkeiten deine künftigen Kunden heute haben. Hilfreich sind eine Suchmaschine, Seiten bestehender Produkte und Nutzerbewertungen. Du brauchst keinen umfangreichen Bericht. Sammle Informationen, die dir helfen, konkrete Wege zu vergleichen, mit dem Problem umzugehen.\nFinde Produkte und andere Vorgehensweisen\nSuche nach der Tätigkeit oder Schwierigkeit, z. B. „wie Warenbestellungen planen“, „Programm zum Lagerauffüllen“ oder „zu viel Zeit für die Lagerkontrolle“. Prüfe auch Namen von Werkzeugen, die du aus früherer Arbeit kennst. Wenn es hilft, wiederhole die Suche auf Englisch.\nListe drei ähnliche Produkte oder Dienste auf und füge Links hinzu. Notiere getrennt andere Vorgehensweisen: eine eigene Tabelle, einen Zettel, die Arbeit einer zusätzlichen Person oder Bestellen nach Gefühl. Wenn weniger als drei Produkte herauskommen, notiere die Ergebnisse und die Orte, an denen du gesucht hast. Ergänze keine unähnlichen Firmen, nur um die Zahl voll zu machen.\nSammle vergleichbare Informationen\nBeantworte bei jeder Lösung die Fragen aus dem Formular. Prüfe zuerst die Produktseite, die Funktionsbeschreibung und die Preisliste. Notiere Zielgruppe, gelöstes Problem, versprochenes Ergebnis und einige der wichtigsten Funktionen.\nNotiere den Preis mit den Bedingungen: pro Monat oder Jahr, pro Person oder für die ganze Firma, für welchen Umfang. „Preis ab 10 €“ sagt ohne diese Angaben wenig. Wenn der Betrag erst nach einem Verkaufsgespräch genannt wird, schreib „individuelles Angebot“. Berücksichtige bei manuellen Wegen Zeit oder Aufwand, auch wenn kein Programm bezahlt wird. Bewahre den Link und das Prüfdatum auf.\nLies Lob und Beschwerden\nSieh dir Bewertungen, themenbezogene Gruppen und Diskussionen über das Produkt an. Notiere, was die Leute schätzen und womit sie Schwierigkeiten haben. Suche nach konkreten Situationen: „ich tippe jede Woche Daten ab“, „ich schaffe es nicht, das selbst einzustellen“, „diese Funktion spart mir eine Stunde“.\nEine einzelne Meinung ist ein Hinweis. Eine wiederkehrende Bemerkung verdient eine weitere Prüfung, sagt aber immer noch nicht, wie häufig das Problem unter allen Nutzern ist. Achte auf das Datum und die Produktversion. Wähle nicht nur Kommentare aus, die zu deiner Idee passen.\nWenn du eine übersehene Gruppe bemerkst, beschreibe sie konkret: „Inhaber von Ein-Personen-Shops ohne IT-Unterstützung“. Eine fehlende Funktion im Produkt bedeutet nicht automatisch, dass jemandem an ihr liegt. Du kannst in späteren Gesprächen danach fragen.\nVergleiche die Idee und die Kosten eines Wechsels\nNenne, was du anders machen willst, wem es helfen soll und wie der geplante Preis im Vergleich abschneidet. Trenne, was ein Wettbewerber schon anbietet, von dem, was du erst zu bauen versprichst. Vermeide Allgemeinplätze wie „bessere Qualität“. Präzisiere z. B. „Die Person bekommt die Liste, ohne Daten von Hand abzutippen.“\nNotiere auch die Vorteile der heutigen Lösung: vertraute Bedienung, Zuverlässigkeit, vorhandene Daten oder technischer Support. Ein Mensch kann bei einem weniger bequemen Weg bleiben, wenn der Wechsel viel Arbeit erfordert. Frag, was das für ihn ausgleichen müsste. Im Beispiel reichen ein paar gesparte Minuten womöglich nicht, wenn das Vorbereiten der Dateien für das neue Werkzeug eine Stunde dauert.\nWenn du keine Konkurrenz findest\nPrüfe andere Bezeichnungen für das Problem und frag Menschen aus der gewählten Gruppe, wie sie zurechtkommen. Notiere mögliche Erklärungen, warum es keine Produkte gibt: Das Bedürfnis ist gering, die Leute nutzen einen Umweg, die Lösung ist schwer zu bauen, oder niemand hat die Idee bisher entwickelt. Schreib zur gewählten Erklärung, wie du sie prüfst, z. B. durch ein Gespräch mit einer Zielperson oder mit jemandem, der die Technologie kennt.\nNach diesem Punkt hast du einen kurzen Vergleich, Links zu den Informationen und eine Idee, was Kunden zum Wechsel bewegen könnte. Ob es Wettbewerber gibt oder nicht, entscheidet allein noch nicht, ob es sich lohnt weiterzumachen.","guide_sources":["Paul Graham, How to Get Startup Ideas, Abschnitt Competition. Grundlage: nach Bedürfnissen suchen, die bestehende Lösungen übersehen.","Eric Migicovsky, How to Talk to Users. Grundlage: genutzte Vorgehensweisen und ihre Grenzen kennenlernen. Der Link führt zu einer Zusammenfassung und Aufzeichnung des Vortrags."]},"uk":{"title":"Перевір, як інші розв’язують цю проблему","guide_body":"Тут ти перевіриш, які можливості сьогодні має твій майбутній клієнт. Знадобляться пошуковик, сторінки наявних продуктів і відгуки користувачів. Великий звіт не потрібен. Збирай інформацію, яка допоможе порівняти конкретні способи впоратися з проблемою.\nЗнайди продукти та інші способи дій\nШукай за дією чи труднощами, наприклад «як планувати замовлення товару», «програма для поповнення запасів» або «забагато часу на контроль складу». Перевір також назви інструментів, які знаєш із попередньої роботи. Якщо це допоможе, повтори пошук англійською.\nВипиши три схожі продукти чи послуги й додай посилання. Окремо занотуй інші способи дій: власну таблицю, папірець, роботу додаткової людини або замовлення навмання. Якщо знайшлося менше трьох продуктів, запиши результати й місця пошуку. Не додавай несхожих компаній лише для того, щоб добрати кількість.\nЗбери порівнянну інформацію\nДля кожного рішення дай відповіді на запитання з форми. Спершу перевір сторінку продукту, опис роботи та прайс. Занотуй адресатів, проблему, яку розв’язують, обіцяний результат і кілька найважливіших функцій.\nЗаписуй ціну разом з умовами: за місяць чи рік, за людину чи всю компанію, за які можливості. «Ціна від 300 грн» без цих даних мало що каже. Якщо суму можна дізнатися лише після розмови з продавцем, напиши «індивідуальна пропозиція». Для ручних способів враховуй час чи зусилля, навіть коли за програму не платять. Збережи посилання й дату перевірки.\nПрочитай похвали й скарги\nЗазирни у відгуки, тематичні групи й обговорення продукту. Запиши, що люди цінують і з чим мають труднощі. Шукай конкретні ситуації: «щотижня переписую дані», «не можу налаштувати це сам», «ця функція економить мені годину».\nОдна думка — це слід. Повторюване зауваження варте подальшої перевірки, але все одно не каже, наскільки поширена проблема серед усіх користувачів. Зважай на дату й версію продукту. Не обирай лише коментарі, які пасують до твоєї ідеї.\nЯкщо помітиш групу, яку оминають, опиши її конкретно: «власники магазинів, що працюють самостійно, без допомоги айтівця». Відсутність функції в продукті не означає автоматично, що комусь потрібно її додати. Про це можна запитати в пізніших розмовах.\nПорівняй ідею і вартість переходу\nВкажи, що ти плануєш робити інакше, кому це має допомогти і як виглядає запропонована ціна на тлі інших. Відокрем те, що конкурент уже пропонує, від того, що ти лише обіцяєш створити. Уникай загальників на кшталт «краща якість». Уточни, наприклад: «користувач отримає список без ручного переписування даних».\nЗапиши також переваги теперішнього рішення: знайоме керування, надійність, наявні дані чи техпідтримку. Людина може залишитися при менш зручному способі, якщо перехід вимагає багато роботи. Запитай, що мало б їй це компенсувати. У прикладі економії кількох хвилин може не вистачити, якщо підготовка файлів для нового інструмента забирає годину.\nЯкщо не знаходиш конкурентів\nПеревір інші назви проблеми й запитай людей з обраної групи, як вони дають собі раду. Запиши можливі пояснення, чому продуктів немає: потреба мала, люди користуються обхідним шляхом, рішення важко створити або ніхто ще не розвинув цієї ідеї. Біля обраного пояснення допиши спосіб перевірки, наприклад розмову з адресатом або з людиною, яка знає цю технологію.\nПісля цього пункту в тебе є коротке порівняння, посилання на інформацію і думка про те, що могло б спонукати клієнта до переходу. Сама наявність чи відсутність конкурентів не вирішує, чи варто продовжувати.","guide_sources":["Paul Graham, How to Get Startup Ideas, розділ Competition. Основа: пошук потреб, які оминають наявні рішення.","Eric Migicovsky, How to Talk to Users. Основа: вивчення способів дій, якими користуються, та їхніх обмежень. Посилання веде до огляду й запису лекції."]},"es":{"title":"Comprueba cómo resuelven otros este problema","guide_body":"Aquí comprobarás qué opciones tiene hoy tu futuro cliente. Te servirán un buscador, las webs de productos existentes y las opiniones de usuarios. No necesitas un informe extenso. Reúne información que te ayude a comparar formas concretas de lidiar con el problema.\nEncuentra productos y otras formas de actuar\nBusca por la actividad o la dificultad, por ejemplo «cómo planificar pedidos de mercancía», «programa para reponer existencias» o «demasiado tiempo para controlar el almacén». Comprueba también nombres de herramientas que conozcas de trabajos anteriores. Si te ayuda, repite la búsqueda en inglés.\nEnumera tres productos o servicios parecidos y añade enlaces. Anota aparte otras formas de actuar: una hoja de cálculo propia, papel, el trabajo de una persona más o pedir a ojo. Si salen menos de tres productos, anota los resultados y dónde buscaste. No añadas empresas que no se parecen solo para completar el número.\nReúne información comparable\nEn cada solución responde a las preguntas del formulario. Primero revisa la web del producto, la descripción de su funcionamiento y la lista de precios. Anota destinatarios, problema que resuelve, resultado que promete y algunas de sus funciones principales.\nAnota el precio con sus condiciones: al mes o al año, por persona o para toda la empresa, por qué funciones. «Precio desde 10 €» dice poco sin esos datos. Si la cifra solo se conoce tras hablar con ventas, escribe «presupuesto personalizado». En las formas manuales, ten en cuenta el tiempo o el esfuerzo, aunque no se pague ningún programa. Guarda el enlace y la fecha de consulta.\nLee elogios y quejas\nMira reseñas, grupos sobre el tema y debates sobre el producto. Anota qué valora la gente y con qué tiene dificultades. Busca situaciones concretas: «cada semana copio datos a mano», «no consigo configurarlo yo solo», «esta función me ahorra una hora».\nUna opinión aislada es una pista. Un comentario que se repite merece más comprobación, pero sigue sin decir lo frecuente que es el problema entre todos los usuarios. Fíjate en la fecha y la versión del producto. No escojas solo los comentarios que encajan con tu idea.\nSi detectas un grupo olvidado, descríbelo de forma concreta: «dueños de tiendas unipersonales sin ayuda informática». Que a un producto le falte una función no significa automáticamente que a alguien le importe añadirla. Puedes preguntarlo en conversaciones posteriores.\nCompara la idea y el coste de cambiar\nIndica qué piensas hacer de otra manera, a quién debe ayudar y cómo queda el precio propuesto frente a los demás. Separa lo que el competidor ya ofrece de lo que tú solo prometes construir. Evita generalidades como «mejor calidad». Precisa, por ejemplo: «el usuario recibirá la lista sin copiar datos a mano».\nAnota también las ventajas de la solución actual: manejo conocido, fiabilidad, datos existentes o soporte técnico. Una persona puede quedarse con una forma menos cómoda si cambiar exige mucho trabajo. Pregunta qué tendría que compensárselo. En el ejemplo, ahorrar unos minutos puede no bastar si preparar los archivos para la nueva herramienta lleva una hora.\nSi no encuentras competencia\nPrueba otros nombres del problema y pregunta a personas del grupo elegido cómo se las arreglan. Anota posibles explicaciones de que no haya productos: la necesidad es pequeña, la gente usa un atajo, la solución es difícil de crear o nadie ha desarrollado aún la idea. Junto a la explicación elegida, añade cómo comprobarla, por ejemplo con una conversación con un destinatario o con alguien que conozca la tecnología.\nTras este punto tienes una comparación breve, enlaces a la información y una idea de qué podría llevar al cliente a cambiar. Que haya o no competidores no decide por sí solo si merece la pena seguir.","guide_sources":["Paul Graham, How to Get Startup Ideas, apartado Competition. Base: buscar necesidades que las soluciones existentes pasan por alto.","Eric Migicovsky, How to Talk to Users. Base: conocer las formas de actuar que se usan y sus límites. El enlace lleva a un resumen y la grabación de la charla."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'konkurencja';
update public.stage_subpoints s set translations = '{"de":{"title":"Finde ähnliche Lösungen"},"uk":{"title":"Знайди схожі рішення"},"es":{"title":"Encuentra soluciones parecidas"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'konkurencja' and s.key = 'znajdz-rozwiazania';
update public.stage_fields f set translations = '{"de":{"question":"Nenne drei Produkte oder Dienste, die ein ähnliches Problem lösen.","help":"Sie müssen nicht identisch sein. Es geht darum, wozu deine Zielperson heute greift."},"uk":{"question":"Випиши три продукти чи послуги, що розв’язують схожу проблему.","help":"Вони не мусять бути ідентичними. Ідеться про те, до чого сьогодні вдається твій адресат."},"es":{"question":"Enumera tres productos o servicios que resuelvan un problema parecido.","help":"No tienen que ser idénticos. Se trata de a qué recurre hoy tu destinatario."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'konkurencja'
    and s.key = 'znajdz-rozwiazania' and f.key = 'produkty';
update public.stage_fields f set translations = '{"de":{"question":"Wie gehen Menschen sonst noch mit diesem Problem um?","help":"Sie machen etwas von Hand, bitten jemanden um Hilfe, nutzen Excel oder finden sich einfach mit der Unannehmlichkeit ab. Auch das ist Konkurrenz."},"uk":{"question":"Якими ще способами люди дають раду з цією проблемою?","help":"Роблять щось вручну, просять когось про допомогу, користуються Excel або просто миряться з незручністю. Це теж конкуренція."},"es":{"question":"¿De qué otras formas lidia la gente con este problema?","help":"Hacen algo a mano, piden ayuda a alguien, usan Excel o simplemente se resignan a la incomodidad. Eso también es competencia."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'konkurencja'
    and s.key = 'znajdz-rozwiazania' and f.key = 'obejscia';
update public.stage_subpoints s set translations = '{"de":{"title":"Beschreibe die gefundenen Lösungen"},"uk":{"title":"Опиши знайдені рішення"},"es":{"title":"Describe las soluciones encontradas"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'konkurencja' and s.key = 'opisz-rozwiazania';
update public.stage_fields f set translations = '{"de":{"question":"Für wen sind sie gedacht?"},"uk":{"question":"Для кого вони призначені?"},"es":{"question":"¿Para quién están pensadas?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'konkurencja'
    and s.key = 'opisz-rozwiazania' and f.key = 'dla-kogo';
update public.stage_fields f set translations = '{"de":{"question":"Wie lösen sie das Problem und was gewinnt die Nutzerin oder der Nutzer dadurch?"},"uk":{"question":"Як вони розв’язують проблему і що завдяки цьому отримує користувач?"},"es":{"question":"¿Cómo resuelven el problema y qué gana con ello el usuario?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'konkurencja'
    and s.key = 'opisz-rozwiazania' and f.key = 'jak-rozwiazuja';
update public.stage_fields f set translations = '{"de":{"question":"Was kosten sie und wofür wird bezahlt?","help":"Wenn du den Preis nicht kennst, schreib „Preis nicht öffentlich“ — auch das ist eine Information."},"uk":{"question":"Скільки вони коштують і за що платять?","help":"Якщо не знаєш ціни, напиши «ціну публічно не вказують» — це теж інформація."},"es":{"question":"¿Cuánto cuestan y por qué se paga?","help":"Si no conoces el precio, escribe «no publican el precio»: eso también es información."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'konkurencja'
