update public.stage_fields f set translations = '{"de":{"question":"Warum könnte es solche Lösungen nicht geben?","help":"Überlege, ob das Problem unwichtig ist, die Lösung schwer zu bauen oder schwer damit Geld zu verdienen. Möglich ist auch, dass noch niemand diese Chance genutzt hat."},"uk":{"question":"Чому таких рішень може не існувати?","help":"Подумай, чи проблема неважлива, рішення важко створити або на ньому важко заробити. Можливо також, що ніхто ще не скористався цим шансом."},"es":{"question":"¿Por qué podrían no existir esas soluciones?","help":"Piensa si el problema es poco importante, si la solución es difícil de construir o si es difícil ganar dinero con ella. También puede que nadie haya aprovechado aún la oportunidad."}}'::jsonb
