update public.stage_fields f set translations = '{"de":{"question":"Was bietest du an und wie hilft es deinem Gegenüber?","help":"Über dem Feld stehen die Problemdefinition, deine Hypothese und die minimale Version. Fasse daraus zusammen, was du anbietest — höchstens zwei Sätze."},"uk":{"question":"Що ти пропонуєш і як це допоможе співрозмовнику?","help":"Над полем є визначення проблеми, твоя гіпотеза і мінімальна версія. Стисни з них, що ти пропонуєш, — щонайбільше два речення."},"es":{"question":"¿Qué ofreces y cómo ayudará a tu interlocutor?","help":"Encima del campo tienes la definición del problema, tu hipótesis y la versión mínima. Resume a partir de ellas qué ofreces: dos frases como mucho."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zainteresowanie-i-cena'
    and s.key = 'propozycja' and f.key = 'oferta';
update public.stage_fields f set translations = '{"de":{"question":"Wer würde zahlen, wie viel und wofür?","example":"8 € pro Monat für die Nutzung der App, es zahlt der Shopinhaber."},"uk":{"question":"Хто мав би платити, скільки і за що?","example":"300 грн на місяць за користування застосунком, платить власник магазину."},"es":{"question":"¿Quién pagaría, cuánto y por qué?","example":"8 € al mes por usar la aplicación; paga el dueño de la tienda."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zainteresowanie-i-cena'
    and s.key = 'propozycja' and f.key = 'cena';
update public.stage_subpoints s set translations = '{"de":{"title":"Lege fest, woran du Interesse erkennst","description":"Lege es fest, bevor du mit Gesprächen beginnst — sonst findest du immer einen Grund, das Ergebnis für gut zu halten."},"uk":{"title":"Визнач, за чим упізнаєш зацікавлення","description":"Визнач це до початку розмов — інакше завжди знайдеш причину вважати результат добрим."},"es":{"title":"Decide cómo reconocerás el interés","description":"Decídelo antes de empezar a hablar; si no, siempre encontrarás un motivo para dar el resultado por bueno."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'general' and p.key = 'zainteresowanie-i-cena' and s.key = 'miara-zainteresowania';
update public.stage_fields f set translations = '{"de":{"question":"Um welche Handlung bittest du?","help":"Etwas, das Aufwand erfordert: Anmeldung zum Test, Vereinbarung eines weiteren Gesprächs, Angabe der E-Mail, Anzahlung."},"uk":{"question":"Про яку дію ти попросиш?","help":"Щось, що вимагає зусиль: запис на тест, домовленість про наступну розмову, надання e-mail, внесення завдатку."},"es":{"question":"¿Qué acción vas a pedir?","help":"Algo que requiera esfuerzo: apuntarse a la prueba, concertar otra conversación, dar el correo, pagar un anticipo."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zainteresowanie-i-cena'
    and s.key = 'miara-zainteresowania' and f.key = 'dzialanie';
update public.stage_fields f set translations = '{"de":{"question":"Wie vielen Personen stellst du das Angebot vor und wie viele davon müssen diese Handlung ausführen, damit du weitermachst?","example":"Ich stelle es 15 Personen vor und mache weiter, wenn sich mindestens 4 zum Test anmelden."},"uk":{"question":"Скільком людям ти представиш пропозицію і скільки з них мають виконати цю дію, щоб ти продовжував(-ла)?","example":"Представлю 15 людям, продовжу, якщо щонайменше 4 запишуться на тест."},"es":{"question":"¿A cuántas personas presentarás la propuesta y cuántas tienen que hacer esa acción para que sigas adelante?","example":"Lo presentaré a 15 personas y seguiré si al menos 4 se apuntan a la prueba."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'general' and p.key = 'zainteresowanie-i-cena'
