    and s.key = 'sposob-naliczania' and f.key = 'w-cenie';
update public.stage_subpoints s set translations = '{"de":{"title":"Prüfe die Reaktion auf die Abrechnungsart","description":"Wenn es schon Gespräche mit Menschen über dieses Problem gab, geh zu denselben Personen zurück — du musst keine neuen suchen."},"uk":{"title":"Перевір реакцію на спосіб розрахунку","description":"Якщо вже були розмови з людьми про цю проблему, повернися до тих самих людей — нових шукати не треба."},"es":{"title":"Comprueba la reacción a la forma de cobro","description":"Si ya hubo conversaciones con personas sobre este problema, vuelve a las mismas: no hace falta buscar otras."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'saas' and p.key = 'za-co-placi' and s.key = 'reakcja-na-rozliczenie';
update public.stage_fields f set translations = '{"de":{"question":"Was passt den Befragten an dieser Abrechnung und was stört sie?"},"uk":{"question":"Що опитаним підходить, а що заважає в такому нарахуванні оплат?"},"es":{"question":"¿Qué les encaja a las personas consultadas de esta forma de cobrar y qué les molesta?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'saas' and p.key = 'za-co-placi'
