update public.stage_fields f set translations = '{"de":{"question":"In welchem Fall könnten sie keinen kostenpflichtigen Zugang mehr brauchen oder die Nutzung einschränken?","help":"Das sind künftige Kündigungsgründe. Besser, du kennst sie jetzt als in einem Jahr."},"uk":{"question":"За яких обставин їм міг би стати непотрібним платний доступ або вони обмежили б користування?","help":"Це майбутні причини відмови. Краще знати їх зараз, ніж за рік."},"es":{"question":"¿En qué caso podrían dejar de necesitar el acceso de pago o reducir el uso?","help":"Son futuros motivos de baja. Mejor conocerlos ahora que dentro de un año."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'saas' and p.key = 'za-co-placi'
    and s.key = 'reakcja-na-rozliczenie' and f.key = 'kiedy-zrezygnuja';
update public.stage_points p set translations = '{"de":{"title":"Prüfe, ob Kunden mit der Nutzung beginnen können","description":"Kläre, was verfügbar sein muss, damit das Programm überhaupt jemandem hilft. In dieser Phase reicht es, Hindernisse und Unbekannte zu erkennen.","guide_body":"Was das Programm für den Anfang braucht\nStell dir eine Person vor, die zum ersten Mal den versprochenen Nutzen bekommen will. Überlege, was sie vorher vorbereiten muss: Dateien, Daten, Zugänge zu anderen Werkzeugen oder Einstellungen.\nListe nur Dinge auf, die für die Hauptfunktion nötig sind. Ein Programm zur Bestellplanung braucht vielleicht eine Produktliste, Verkaufsdaten und aktuelle Lagerbestände. Ein Buchungsprogramm braucht vielleicht Verfügbarkeitszeiten und die Art der angebotenen Leistungen.\nKläre bei jedem Punkt, woher die Nutzerin oder der Nutzer ihn bekommt. Ist er schon in einem anderen Programm? Muss er von Hand vorbereitet werden? Braucht es Hilfe oder die Erlaubnis einer anderen Person?\nNimm nicht an, dass man Informationen, die man ansehen kann, auch herunterladen und weitergeben kann. Frag, wie die Person das bei ihrer heutigen Arbeitsweise tun würde.\nBehandle die Frage nach der Rechtmäßigkeit der Datenweitergabe als Platz für Erkenntnisse und offene Punkte. Notiere:\nWelche Art von Informationen ins Programm gelangen soll.\nVon wem sie stammen und ob sie andere Personen betreffen.\nIn welchen Ländern du den Dienst anbieten willst.\nWelche Einschränkungen Kunden oder der Anbieter des genutzten Werkzeugs genannt haben.\nWenn du die Lage nicht beurteilen kannst, trag eine konkrete Unbekannte und eine Person ein, die bei der Klärung hilft. Beispiel: „Mit der für Datenschutz zuständigen Person zu klären: Darf der Shop eine Datei mit Informationen über seine Kunden weitergeben?“\nDie YC-Materialien klären keine Rechtsfragen. Kläre Zweifel zur rechtmäßigen Nutzung von Daten mit einer passenden Fachperson, bevor du diese Daten in einem Test verwendest. Für die Besprechung der Idee kannst du eine ausgedachte Beispieldatei vorbereiten.\nPrüfe die nötigen Verbindungen zu anderen Programmen\n„Integration“ ist eine Verbindung, die Programme zusammenarbeiten lässt. Eine neue Buchung kann zum Beispiel automatisch im Kalender der Nutzerin erscheinen.\nListe die nötigen Verbindungen auf und erkläre bei jeder, welche Informationen übertragen werden sollen und wozu. Statt nur „Verbindung zum Kalender“ schreib: „Belegte Termine abrufen, um keinen Termin zu einer nicht verfügbaren Zeit vorzuschlagen.“\nKonzentriere dich auf Verbindungen, die für das Hauptversprechen nötig sind. Schreib nicht alle beliebten Programme dazu, die jemand nutzen könnte.\nPrüfe dann, ob anfangs ein einfacherer Weg der Datenübergabe reicht. Eine automatische Verbindung lässt sich manchmal durch das Senden einer Datei ersetzen. CSV ist ein einfaches Format für Tabellendaten. Wichtig ist, ob das heutige Programm erlaubt, die nötigen Informationen in diesem oder einem anderen nützlichen Format herunterzuladen.\nSieh in die Anleitung des Programms oder frag dessen Support. Wenn du Hilfe einer Programmiererin brauchst, zeig ihr konkret: welche Daten, woher, wohin und wie oft sie fließen sollen.\nFrag die Nutzer, wie das manuelle Senden einer Datei in ihrer Arbeit aussähe. Eine einmalige Datenvorbereitung kann akzeptabel sein. Diese Tätigkeit ein Dutzend Mal am Tag zu wiederholen, kann der Lösung den Sinn nehmen.\nWenn das Hauptversprechen sofort aktualisierte Informationen verlangt, reicht das manuelle Senden von Dateien womöglich nicht. Notiere eine solche Einschränkung als offenen Punkt.\nNotiere die Bedingungen für den Nutzungsbeginn\nSammle Hindernisse, die Nutzer vor der ersten Nutzung aufhalten könnten. Sie können die Datenvorbereitung betreffen, schwierige Einstellungen, fehlenden Zugang zu einem nötigen Programm oder Bedenken, Informationen an einem neuen Ort zu speichern.\nFormuliere sie konkret. „Fehlendes Vertrauen“ erklärt wenig. „Die Person will keine Dokumente senden, solange sie nicht weiß, wer Zugriff darauf hat“ zeigt eine Frage, die beantwortet werden muss.\nVermerke bei jedem Hindernis, ob es dein Gegenüber genannt hat oder ob es deine Vermutung ist. Ergänze, wie du es prüfst: ein weiteres Gespräch, ein Blick in die Anleitung, eine Frage an den Programmanbieter oder eine technische Beratung.\nDu musst nicht sofort jedes Hindernis beseitigen. Kläre in dieser Phase vor allem, welche davon das Hauptversprechen verhindern können und vor der weiteren Arbeit geklärt werden müssen.\nNach diesem Punkt hast du eine Liste der Dinge, die für den Nutzungsbeginn nötig sind, der unverzichtbaren Verbindungen und der Hindernisse. Du weißt, was geprüft ist und was unbekannt bleibt.","guide_sources":["Paul Graham, Do Things that Don’t Scale. Persönliche Hilfe für die ersten Nutzer und anfangs einen Teil der Arbeit von Hand erledigen. Quelltext.","Geoff Ralston, YC’s Essential Startup Advice. Einen einfachen Weg suchen, den Grundnutzen zu liefern, ohne das Produkt verfrüht auszubauen. Quelltext.","Die Anleitungen zu Daten und Verbindungen zwischen Programmen sind eine Erweiterung der Vairo-Übung. Die Bewertung einer konkreten Verbindung erfordert die Dokumentation des jeweiligen Werkzeugs, und die rechtliche Bewertung von Daten erfordert eine gesonderte Prüfung."]},"uk":{"title":"Перевір, чи зможе клієнт почати користуватися","description":"З’ясуй, що має бути доступним, щоб програма комусь допомогла. На цьому етапі досить розпізнати перешкоди й невідомі.","guide_body":"Що програмі потрібно на початок\nУяви людину, яка вперше хоче отримати обіцяну користь. Подумай, що вона має заздалегідь підготувати: файли, дані, доступи до інших інструментів або налаштування.\nВипиши лише те, що потрібно для головної дії. Програмі для планування замовлень можуть знадобитися список товарів, дані про продажі й поточні запаси. Програма бронювань може вимагати годин доступності та видів послуг.\nДля кожної позиції з’ясуй, звідки користувач її візьме. Чи вона вже є в іншій програмі? Чи треба підготувати її вручну? Чи потрібні допомога або дозвіл іншої людини?\nНе вважай, що можливість переглядати інформацію означає можливість її завантажити й передати. Запитай, як користувач зробив би це за теперішнього способу роботи.\nПитання про законність передачі даних сприймай як місце для домовленостей і справ, які треба з’ясувати. Запиши:\nЯкі види інформації мають потрапити до програми.\nВід кого вони походять і чи стосуються інших людей.\nУ яких країнах ти плануєш пропонувати послугу.\nЯкі обмеження назвав клієнт або постачальник використовуваного інструмента.\nЯкщо не можеш оцінити ситуацію, впиши конкретну невідому й людину, яка допоможе її з’ясувати. Приклад: «Перевірити з людиною, відповідальною за захист даних: чи може магазин передати файл з інформацією про своїх клієнтів».\nМатеріали YC не вирішують правових питань. Сумніви щодо законності використання даних з’ясуй із відповідним фахівцем, перш ніж використати ці дані в тесті. Для обговорення ідеї можна підготувати вигаданий приклад файла.\nПеревір потрібні зв’язки з іншими програмами\n«Інтеграція» — це зв’язок, що дає змогу програмам співпрацювати. Наприклад, нове бронювання може автоматично з’явитися в календарі користувача.\nВипиши потрібні зв’язки й біля кожного поясни, які дані мають передаватися і навіщо. Замість самого «зв’язок із календарем» запиши: «отримання зайнятих термінів, щоб не пропонувати візит у недоступну годину».\nЗосередься на зв’язках, потрібних для виконання головної обіцянки. Не дописуй усіх популярних програм, якими хтось міг би користуватися.\nДалі перевір, чи на початок не вистачить простішого способу передачі інформації. Автоматичний зв’язок іноді можна замінити надсиланням файла. CSV — простий формат табличних даних. Важливо, чи теперішня програма дає змогу завантажити потрібну інформацію в такому чи іншому корисному форматі.\nЗазирни в інструкцію програми або запитай її підтримку. Якщо потрібна допомога програміста, покажи йому конкретно: які дані, звідки, куди і як часто мають надходити.\nЗапитай користувача, як ручне надсилання файла виглядало б у його роботі. Одноразова підготовка даних може бути прийнятною. Повторення цієї дії кільканадцять разів на день може позбавити рішення сенсу.\nЯкщо головна обіцянка вимагає миттєвого оновлення інформації, ручного надсилання файлів може не вистачити. Запиши таке обмеження як справу, яку треба розв’язати.\nЗапиши умови початку користування\nЗбери перешкоди, які могли б зупинити користувача перед першим використанням. Вони можуть стосуватися підготовки даних, складних налаштувань, відсутності доступу до потрібної програми або побоювань зберігати інформацію в новому місці.\nФормулюй їх конкретно. «Брак довіри» мало що пояснює. «Співрозмовник не хоче надсилати документи, доки не знає, хто матиме до них доступ» вказує на питання, на яке треба відповісти.\nБіля кожної перешкоди познач, чи назвав її співрозмовник, чи це твоє припущення. Допиши спосіб перевірки: наступну розмову, перегляд інструкції, запитання до постачальника програми або технічну консультацію.\nНе треба одразу усувати кожну перешкоду. На цьому етапі передусім з’ясуй, які з них можуть унеможливити виконання головної обіцянки й потребують пояснення перед подальшою роботою.\nПісля цього пункту в тебе є список того, що потрібно для початку користування, необхідних зв’язків і перешкод. Ти знаєш, що перевірено, а що залишається невідомим.","guide_sources":["Paul Graham, Do Things that Don’t Scale. Особиста допомога першим користувачам і виконання частини роботи вручну на початку. Першоджерело.","Geoff Ralston, YC’s Essential Startup Advice. Пошук простого способу дати базову користь без передчасного розширення продукту. Першоджерело.","Вказівки щодо даних і зв’язків між програмами — це розширення вправи Vairo. Оцінка конкретного зв’язку потребує документації відповідного інструмента, а правова оцінка даних — окремої перевірки."]},"es":{"title":"Comprueba si el cliente podrá empezar a usarlo","description":"Determina qué tiene que estar disponible para que el programa ayude a alguien. En esta fase basta con identificar obstáculos e incógnitas.","guide_body":"Qué necesita el programa para empezar\nImagina a una persona que quiere obtener por primera vez el beneficio prometido. Piensa qué tiene que preparar antes: archivos, datos, accesos a otras herramientas o ajustes.\nEnumera solo lo necesario para la acción principal. Un programa para planificar pedidos puede necesitar una lista de productos, datos de ventas y existencias actuales. Un programa de reservas puede requerir horarios de disponibilidad y el tipo de servicios ofrecidos.\nEn cada elemento, averigua de dónde lo sacará el usuario. ¿Ya lo tiene en otro programa? ¿Tiene que prepararlo a mano? ¿Necesita ayuda o permiso de otra persona?\nNo supongas que poder ver la información significa poder descargarla y entregarla. Pregunta cómo lo haría el usuario con su forma de trabajar actual.\nTrata la pregunta sobre la legalidad de compartir los datos como un espacio para lo averiguado y lo que queda por aclarar. Anota:\nQué tipo de información debe llegar al programa.\nDe quién procede y si afecta a otras personas.\nEn qué países piensas ofrecer el servicio.\nQué limitaciones han señalado el cliente o el proveedor de la herramienta que usa.\nSi no puedes valorar la situación, escribe una incógnita concreta y la persona que ayudará a aclararla. Ejemplo: «Consultar con la persona responsable de protección de datos: ¿puede la tienda entregar un archivo con información sobre sus clientes?».\nLos materiales de YC no resuelven cuestiones legales. Aclara las dudas sobre la legalidad de usar los datos con un especialista adecuado antes de utilizarlos en una prueba. Para comentar la idea puedes preparar un archivo de ejemplo inventado.\nComprueba las conexiones necesarias con otros programas\nUna «integración» es una conexión que permite a los programas trabajar juntos. Por ejemplo, una nueva reserva puede aparecer automáticamente en el calendario del usuario.\nEnumera las conexiones necesarias y explica en cada una qué información debe pasar y para qué. En lugar de solo «conexión con el calendario», escribe: «obtener las horas ocupadas para no proponer una cita a una hora no disponible».\nCéntrate en las conexiones necesarias para cumplir la promesa principal. No añadas todos los programas populares que alguien podría usar.\nDespués comprueba si al principio basta una forma más sencilla de pasar la información. A veces una conexión automática se puede sustituir enviando un archivo. CSV es un formato sencillo para datos en tabla. Lo importante es si el programa actual permite descargar la información necesaria en ese u otro formato útil.\nConsulta las instrucciones del programa o pregunta a su soporte. Si necesitas ayuda de un programador, muéstrale en concreto qué datos, de dónde, a dónde y con qué frecuencia deben ir.\nPregunta al usuario cómo sería en su trabajo enviar el archivo a mano. Preparar los datos una vez puede ser aceptable. Repetirlo una docena de veces al día puede quitarle el sentido a la solución.\nSi la promesa principal exige información actualizada al instante, enviar archivos a mano puede no bastar. Anota esa limitación como algo por resolver.\nAnota las condiciones para empezar a usarlo\nReúne los obstáculos que podrían frenar al usuario antes del primer uso. Pueden tener que ver con preparar los datos, ajustes difíciles, no tener acceso a un programa necesario o el temor a guardar información en un sitio nuevo.\nFormúlalos de forma concreta. «Falta de confianza» explica poco. «La persona no quiere enviar documentos hasta saber quién tendrá acceso a ellos» señala una pregunta que hay que responder.\nEn cada obstáculo indica si lo mencionó tu interlocutor o si es una suposición tuya. Añade cómo comprobarlo: otra conversación, consultar las instrucciones, preguntar al proveedor del programa o una consulta técnica.\nNo tienes que eliminar enseguida cada obstáculo. En esta fase averigua sobre todo cuáles pueden impedir cumplir la promesa principal y deben aclararse antes de seguir.\nTras este punto tienes una lista de lo necesario para empezar a usarlo, de las conexiones imprescindibles y de los obstáculos. Sabes qué está comprobado y qué sigue siendo una incógnita.","guide_sources":["Paul Graham, Do Things that Don’t Scale. Ayuda personal a los primeros usuarios y hacer parte del trabajo a mano al principio. Texto original.","Geoff Ralston, YC’s Essential Startup Advice. Buscar una forma sencilla de dar el beneficio básico sin ampliar el producto antes de tiempo. Texto original.","Las indicaciones sobre datos y conexiones entre programas amplían el ejercicio de Vairo. Valorar una conexión concreta requiere la documentación de esa herramienta, y la valoración legal de los datos requiere una comprobación aparte."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'saas' and p.key = 'start-korzystania';
update public.stage_subpoints s set translations = '{"de":{"title":"Was das Programm für den Anfang braucht"},"uk":{"title":"Що програмі потрібно на початок"},"es":{"title":"Qué necesita el programa para empezar"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'saas' and p.key = 'start-korzystania' and s.key = 'czego-potrzebuje';
update public.stage_fields f set translations = '{"de":{"question":"Welche Daten, Dateien, Zugänge oder Einstellungen sind vor der ersten Nutzung nötig?","help":"Wenn keine — trag „nichts nötig“ ein. Das ist eine sehr gute Nachricht für dein Produkt."},"uk":{"question":"Які дані, файли, доступи чи налаштування потрібні перед першим використанням?","help":"Якщо жодних — впиши «нічого не потрібно». Це дуже добра новина для твого продукту."},"es":{"question":"¿Qué datos, archivos, accesos o ajustes hacen falta antes del primer uso?","help":"Si ninguno, escribe «no hace falta nada». Es una muy buena noticia para tu producto."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
