update public.stage_fields f set translations = '{"de":{"question":"Ist die Weitergabe dieser Daten rechtmäßig? Wenn ja, auf welcher Grundlage?","help":"Personenbezogene Daten, Kundendaten, Finanzdaten — hier beginnen echte Hindernisse, die man leicht vergisst."},"uk":{"question":"Чи законна передача цих даних? Якщо так, на якій підставі?","help":"Персональні дані, дані клієнтів, фінансові дані — тут починаються реальні перешкоди, про які легко забути."},"es":{"question":"¿Es legal compartir estos datos? Si es así, ¿con qué base?","help":"Datos personales, de clientes, financieros: aquí empiezan obstáculos reales que es fácil olvidar."}}'::jsonb
