update public.stage_fields f set translations = '{"de":{"question":"Mit welchen Programmen muss deine Lösung Daten austauschen, um das Hauptversprechen zu erfüllen?","help":"Wenn mit keinen — trag „mit keinen“ ein. Jede Integration bedeutet Wochen Arbeit, also weißt du es besser sicher."},"uk":{"question":"З якими програмами твоє рішення має обмінюватися даними, щоб виконати головну обіцянку?","help":"Якщо з жодними — впиши «з жодними». Кожна інтеграція — це тижні роботи, тож краще знати напевно."},"es":{"question":"¿Con qué programas tiene que intercambiar datos tu solución para cumplir la promesa principal?","help":"Si con ninguno, escribe «con ninguno». Cada integración son semanas de trabajo, así que mejor saberlo con certeza."}}'::jsonb
