update public.stage_fields f set translations = '{"de":{"question":"Welche dieser Hindernisse haben Gesprächspartner genannt und welche müssen erst geprüft werden?","help":"Ergänze bei jedem: „vom Gegenüber gesagt“ oder „meine Vermutung“. Vermutungen sind zum Prüfen da, nicht zum Planen."},"uk":{"question":"Які з цих перешкод назвали співрозмовники, а які ще треба перевірити?","help":"Біля кожної допиши: «сказав співрозмовник» або «моє припущення». Припущення — для перевірки, а не для планування."},"es":{"question":"¿Cuáles de estos obstáculos señalaron tus interlocutores y cuáles quedan por comprobar?","help":"Añade en cada uno: «lo dijo mi interlocutor» o «suposición mía». Las suposiciones son para comprobar, no para planificar."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
