update public.stage_fields f set translations = '{"de":{"question":"Wer hat das Problem, wer verfügt über das Budget, wer unterschreibt den Vertrag und wer kann den Kauf blockieren?","help":"Trag eine Rolle pro Zeile ein. Oft sind es vier verschiedene Personen — und jede braucht ein anderes Argument."},"uk":{"question":"Хто має проблему, хто розпоряджається бюджетом, хто підписує договір, а хто може заблокувати покупку?","help":"Одна роль на позицію. Часто це чотири різні людини — і кожній потрібен інший аргумент."},"es":{"question":"¿Quién tiene el problema, quién maneja el presupuesto, quién firma el contrato y quién puede bloquear la compra?","help":"Una función por línea. A menudo son cuatro personas distintas, y cada una necesita un argumento diferente."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
