    and s.key = 'jak-decyduje' and f.key = 'ile-osob';
update public.stage_fields f set translations = '{"de":{"question":"Kann die Firma eine solche Lösung jederzeit kaufen oder muss sie vorher Geld dafür einplanen?","help":"Ein eingeplantes Budget bedeutet, dass der Verkauf bis zum nächsten Jahr warten kann."},"uk":{"question":"Чи може компанія купити таке рішення будь-коли, чи мусить заздалегідь запланувати на нього гроші?","help":"Запланований бюджет означає, що продаж може чекати до наступного року."},"es":{"question":"¿Puede la empresa comprar esa solución en cualquier momento o tiene que planificar antes el dinero?","help":"Un presupuesto planificado significa que la venta puede esperar al año siguiente."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2b' and p.key = 'czas-sprzedazy'
    and s.key = 'jak-decyduje' and f.key = 'budzet';
update public.stage_subpoints s set translations = '{"de":{"title":"Finde die größten Verzögerungen"},"uk":{"title":"Визнач найбільші затримки"},"es":{"title":"Identifica los mayores retrasos"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2b' and p.key = 'czas-sprzedazy' and s.key = 'opoznienia';
update public.stage_fields f set translations = '{"de":{"question":"Was kann den Prozess verzögern?","help":"Urlaub, Sicherheitsaudit, Rechtsabteilung, Ende des Geschäftsjahres, personeller Wechsel auf der Position."},"uk":{"question":"Що може затримати процес?","help":"Відпустки, аудит безпеки, юридичний відділ, кінець фінансового року, зміна людини на посаді."},"es":{"question":"¿Qué puede retrasar el proceso?","help":"Vacaciones, auditoría de seguridad, departamento legal, cierre del ejercicio fiscal, cambio de persona en el puesto."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2b' and p.key = 'czas-sprzedazy'
    and s.key = 'opoznienia' and f.key = 'co-opozni';
update public.stage_points p set translations = '{"de":{"title":"Prüfe, ob sich der Kauf für die Firma lohnt","description":"ROI (Return On Investment) ist die einfache Antwort auf die Frage: Lohnt sich das für die Firma? Du brauchst keine Tabelle — eine ehrliche Schätzung reicht.","guide_body":"Was das Problem die Kunden kostet\nNutze die Informationen aus dem allgemeinen Teil. Ergänze sie so, dass sich die heutige Lage mit der erwarteten Verbesserung vergleichen lässt.\nWähle einen Zeitraum, z. B. einen Monat. Notiere, wie viel Zeit die Firma für das Problem aufwendet, welche Ausgaben sie hat und wie viele Fehler auftreten. Erkläre bei Fehlern auch deren Folgen: zusätzliche Lieferung, Korrektur der Bestellung, verschwendetes Material.\nBeispiel: „Im Monat verschickt die Firma etwa 20 Pakete mit einem Fehler. Ein erneuter Versand kostet im Schnitt 6 € pro Paket, also insgesamt etwa 120 €.“\nWenn du nur Schätzungen deines Gegenübers hast, vermerke das. Wenn Beträge fehlen, behalte die Zahl der Stunden oder Fehler und ergänze, was du noch brauchst, um die Kosten zu berechnen.\nMigicovsky empfiehlt, nach den heutigen Kosten des Problems und dem verfügbaren Budget zu fragen. Hale nennt ein teures oder dringendes Problem als einen der Gründe, warum eine Lösung gebraucht werden kann.\nRechne den Nutzen in Geld um und vergleiche ihn mit dem Preis\nNimm den Preis aus dem allgemeinen Teil. Schätze dann, welchen Teil der heutigen Kosten deine Lösung verringern kann. Nimm nicht automatisch an, dass sie alle Verluste beseitigt.\nIm Paket-Beispiel kannst du zur Prüfung annehmen, dass die Zahl der Fehler um die Hälfte sinkt. Das bedeutete eine Ersparnis von etwa 60 € im Monat beim erneuten Versand. Wenn die Lösung 40 € im Monat kostet, beträgt die Differenz 20 € — vor allen übrigen Kosten.\nVergleiche denselben Zeitraum. Bei einem einmaligen Kauf kannst du prüfen, nach wie vielen Monaten die erwarteten Einsparungen die Ausgabe decken. Berücksichtige bekannte Kosten für den Nutzungsbeginn, z. B. Einrichtung des Arbeitsplatzes oder Schulung.\nAchte auf zwei häufige Fehler:\nGesparte Zeit bedeutet nicht immer geringere Ausgaben. Die Mitarbeiterin kann sie für andere Aufgaben nutzen und erhält dasselbe Gehalt.\nZähle denselben Nutzen nicht doppelt. Wenn die Kosten für die Fehlerkorrektur die Arbeit der Mitarbeiterin schon enthalten, füge sie nicht noch einmal als eigene Ersparnis hinzu.\nFrag die Person, die über den Kauf entscheidet, welches Ergebnis die Ausgabe rechtfertigen würde und wie lange die Firma darauf warten kann. Notiere das als Erwartung, die in einem späteren Test geprüft wird.\nBerücksichtige weiche Vorteile\n„Weiche Vorteile“ sind Vorzüge, denen sich schwer ein konkreter Betrag zuordnen lässt. Beschreibe, wie sie die tägliche Arbeit verändern.\nStatt „mehr Komfort“ kannst du schreiben: „Die Beschäftigten prüfen den Bestellstatus an einem Ort und müssen nicht im Lager anrufen.“ Statt „weniger Stress“: „Die für Lieferungen zuständige Person sieht fehlende Produkte früher.“\nErfinde keinen Geldwert, nur damit das Rechenergebnis besser aussieht. Vermerke, wer den jeweiligen Vorteil genannt hat und ob er für die Person, die den Kauf genehmigt, eine Rolle spielt.","guide_sources":["Eric Migicovsky, How to Talk to Users, und Kevin Hale, How to Evaluate Startup Ideas, Materialien und Transkript von Y Combinator.","Brecht und Mitautoren, Discovery and Validation of Business Models: How B2B Startups can use Business Experiments, Untersuchung der Aufgaben von Kunden, des Zeitaufwands und der Kosten. Das Rechenbeispiel ist eine für diesen Leitfaden erstellte Illustration."]},"uk":{"title":"Перевір, чи покупка окупиться для компанії","description":"ROI (Return On Investment) — це проста відповідь на запитання: чи окупиться це для компанії. Таблиця не потрібна — досить чесної оцінки.","guide_body":"Скільки коштує клієнтові проблема\nСкористайся інформацією із загальної частини. Доповни її так, щоб можна було порівняти теперішню ситуацію з очікуваним поліпшенням.\nОбери один період, наприклад місяць. Запиши, скільки часу компанія витрачає на проблему, які несе витрати і скільки з’являється помилок. Біля помилок поясни також їхні наслідки: додаткова доставка, виправлення замовлення, змарновані матеріали.\nПриклад: «За місяць компанія надсилає близько 20 посилок із помилкою. Повторне надсилання коштує в середньому 250 грн за посилку, тобто разом близько 5000 грн».\nЯкщо маєш лише оцінки співрозмовника, познач це. Коли бракує сум, залиш кількість годин чи помилок і допиши, чого ще потребуєш для розрахунку вартості.\nMigicovsky радить питати про теперішню вартість проблеми і доступний бюджет. Hale називає дорогу або нагальну проблему однією з причин, чому рішення може бути потрібне.\nПерерахуй користь у гроші й порівняй із ціною\nВізьми ціну із загальної частини. Далі оціни, яку частину теперішньої вартості твоє рішення може зменшити. Не вважай автоматично, що воно усуне всі втрати.\nУ прикладі з посилками можна прийняти для перевірки, що кількість помилок зменшиться вдвічі. Це означало б економію близько 2500 грн на місяць на повторних відправленнях. Якщо рішення коштує 1500 грн на місяць, різниця становить 1000 грн до врахування інших витрат.\nПорівнюй той самий період. За одноразової покупки можна перевірити, за скільки місяців очікувана економія покриє витрату. Врахуй відомі витрати на початок користування, наприклад підготовку робочого місця чи навчання.\nСтережися двох частих помилок:\nЗекономлений час не завжди означає менші витрати. Працівник може використати його на інші завдання, отримуючи ту саму зарплату.\nНе рахуй ту саму користь двічі. Якщо вартість виправлення помилок уже містить роботу працівника, не додавай її ще раз як окрему економію.\nЗапитай людину, яка вирішує про покупку, який результат виправдав би витрату і скільки компанія може на нього чекати. Запиши це як очікування для перевірки в пізнішому тесті.\nВрахуй м’які переваги\n«М’які переваги» — це плюси, яким важко приписати конкретну суму. Опиши, як вони змінять щоденну роботу.\nЗамість «більша зручність» можна записати: «Працівники перевіряють статус замовлення в одному місці й не мусять дзвонити на склад». Замість «менше стресу»: «Людина, відповідальна за поставки, раніше бачить відсутні товари».\nНе вигадуй грошової вартості лише для того, щоб результат розрахунків виглядав краще. Познач, хто вказав цю перевагу і чи має вона значення для людини, яка затверджує покупку.","guide_sources":["Eric Migicovsky, How to Talk to Users, і Kevin Hale, How to Evaluate Startup Ideas, матеріали й транскрипція Y Combinator.","Brecht і співавтори, Discovery and Validation of Business Models: How B2B Startups can use Business Experiments, дослідження завдань клієнтів, витраченого часу й вартості. Приклад розрахунків — ілюстрація, підготовлена для цього посібника."]},"es":{"title":"Comprueba si la compra le compensa a la empresa","description":"El ROI (Return On Investment) es la respuesta sencilla a la pregunta: ¿le compensa a la empresa? No necesitas una hoja de cálculo: basta una estimación honesta.","guide_body":"Cuánto le cuesta el problema al cliente\nUsa la información de la parte general. Complétala para poder comparar la situación actual con la mejora prevista.\nElige un periodo, por ejemplo un mes. Anota cuánto tiempo dedica la empresa al problema, qué gastos tiene y cuántos errores aparecen. En los errores, explica también sus consecuencias: un envío adicional, corregir el pedido, material desperdiciado.\nEjemplo: «Al mes, la empresa envía unos 20 paquetes con algún error. Reenviarlos cuesta de media 6 € por paquete, unos 120 € en total».\nSi solo tienes estimaciones de tu interlocutor, indícalo. Si faltan cifras, deja el número de horas o de errores y añade qué te falta para calcular el coste.\nMigicovsky propone preguntar por el coste actual del problema y por el presupuesto disponible. Hale señala un problema caro o urgente como uno de los motivos por los que una solución puede ser necesaria.\nConvierte los beneficios en dinero y compáralos con el precio\nToma el precio de la parte general. Después estima qué parte del coste actual puede reducir tu solución. No supongas automáticamente que eliminará todas las pérdidas.\nEn el ejemplo de los paquetes, puedes suponer para comprobarlo que los errores se reducirán a la mitad. Eso supondría un ahorro de unos 60 € al mes en reenvíos. Si la solución cuesta 40 € al mes, la diferencia es de 20 € antes de contar los demás costes.\nCompara el mismo periodo. En una compra única, puedes comprobar en cuántos meses el ahorro previsto cubrirá el gasto. Ten en cuenta los costes conocidos de empezar a usarla, como preparar el puesto o la formación.\nCuidado con dos errores frecuentes:\nAhorrar tiempo no siempre significa gastar menos. El empleado puede dedicarlo a otras tareas y cobrar el mismo sueldo.\nNo cuentes dos veces el mismo beneficio. Si el coste de corregir errores ya incluye el trabajo del empleado, no lo sumes otra vez como ahorro aparte.\nPregunta a quien decide la compra qué resultado justificaría el gasto y cuánto tiempo puede esperar la empresa para verlo. Anótalo como una expectativa por comprobar en una prueba posterior.\nTen en cuenta los beneficios intangibles\nLos «beneficios intangibles» son ventajas a las que es difícil asignar una cifra concreta. Describe cómo cambiarán el trabajo diario.\nEn lugar de «más comodidad» puedes escribir: «Los empleados consultan el estado del pedido en un solo sitio y no tienen que llamar al almacén». En lugar de «menos estrés»: «La persona responsable de las entregas ve antes los productos que faltan».\nNo inventes un valor en dinero solo para que el cálculo quede mejor. Indica quién señaló cada beneficio y si importa a la persona que aprueba la compra.","guide_sources":["Eric Migicovsky, How to Talk to Users, y Kevin Hale, How to Evaluate Startup Ideas, materiales y transcripción de Y Combinator.","Brecht y coautores, Discovery and Validation of Business Models: How B2B Startups can use Business Experiments, estudio de las tareas de los clientes, el tiempo dedicado y los costes. El ejemplo de cálculo es una ilustración preparada para esta guía."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2b' and p.key = 'roi';
