update public.stage_fields f set translations = '{"de":{"question":"Welches Mindestergebnis in welcher Zeit überzeugt sie zum Kauf?","help":"„Muss sich in einem halben Jahr amortisieren“ ist eine typische Antwort. Kenne sie vor dem Preisgespräch."},"uk":{"question":"Який мінімальний результат і за який час переконає його купити?","help":"«Має окупитися за пів року» — типова відповідь. Дізнайся її до розмови про ціну."},"es":{"question":"¿Qué resultado mínimo y en qué plazo lo convencerá para comprar?","help":"«Tiene que recuperarse en medio año» es una respuesta típica. Conócela antes de hablar del precio."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
