update public.stage_fields f set translations = '{"de":{"question":"Was kann dazu führen, dass die Beschäftigten trotz Kauf bei der alten Arbeitsweise bleiben?","help":"Keine Zeit zum Lernen, dieselbe Sache doppelt machen müssen, Gewohnheit, fehlende Unterstützung der Chefin."},"uk":{"question":"Що може спричинити, що працівники залишаться при старому способі роботи попри покупку?","help":"Брак часу на навчання, потреба робити те саме двічі, звичка, брак підтримки шефа."},"es":{"question":"¿Qué puede hacer que los empleados sigan con la forma de trabajar de siempre pese a la compra?","help":"Falta de tiempo para aprender, tener que hacer lo mismo dos veces, la costumbre, falta de apoyo del jefe."}}'::jsonb
