update public.stage_fields f set translations = '{"de":{"question":"Hat die Firma früher etwas Ähnliches gekauft, das dann nicht genutzt wurde? Wenn ja, warum?","help":"Das ist die wertvollste Frage im ganzen Punkt. Die Antwort sagt, was du vermeiden solltest."},"uk":{"question":"Чи компанія раніше купувала щось схоже, чим потім не користувалися? Якщо так, чому?","help":"Це найцінніше запитання в усьому пункті. Відповідь підкаже, чого уникати."},"es":{"question":"¿Compró antes la empresa algo parecido que luego no se usó? Si es así, ¿por qué?","help":"Es la pregunta más valiosa de todo el punto. La respuesta dice qué evitar."}}'::jsonb
