update public.stage_subpoints s set translations = '{"de":{"title":"Nenne den Anlass für den Kauf","description":"Eine Situation aus dem Privatleben, in der Verbraucher einen Kauf erwägen — z. B. Beginn eines Hobbys, Prüfungsvorbereitung oder die Wahl eines Geschenks."},"uk":{"title":"Вкажи нагоду для покупки","description":"Одна ситуація з приватного життя, коли споживач розгляне покупку, — напр. початок хобі, підготовка до іспиту чи вибір подарунка."},"es":{"title":"Señala la ocasión de compra","description":"Una situación de la vida privada en la que el consumidor se planteará la compra: p. ej. empezar un hobby, prepararse un examen o elegir un regalo."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
