update public.stage_fields f set translations = '{"de":{"question":"Wie passt der Kauf ins Budget der Verbraucher?","config":{"options":[{"value":"zastepuje","label":"Ersetzt eine bisherige Ausgabe"},{"value":"dodatkowy","label":"Das sind zusätzliche Kosten"},{"value":"bez-oplaty","label":"Ohne Gebühr für Verbraucher"}]}},"uk":{"question":"Як покупка вписується в бюджет споживача?","config":{"options":[{"value":"zastepuje","label":"Замінює дотеперішню витрату"},{"value":"dodatkowy","label":"Це додаткова витрата"},{"value":"bez-oplaty","label":"Без оплати від споживача"}]}},"es":{"question":"¿Cómo encaja la compra en el presupuesto del consumidor?","config":{"options":[{"value":"zastepuje","label":"Sustituye un gasto actual"},{"value":"dodatkowy","label":"Es un coste adicional"},{"value":"bez-oplaty","label":"Sin pago del consumidor"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
