update public.stage_fields f set translations = '{"de":{"question":"Welche Ausgabe ersetzt er oder zu welcher Kategorie gehört er?","help":"z. B. Bildung des Kindes; der Kurs ersetzt einen Teil der Ausgaben für Nachhilfe. Bei kostenlosem Zugang leer lassen."},"uk":{"question":"Яку витрату він замінює або до якої категорії належить?","help":"напр. освіта дитини; курс замінює частину витрат на репетиторів. За безплатного доступу залиш порожнім."},"es":{"question":"¿Qué gasto sustituye o a qué categoría pertenece?","help":"p. ej. educación de los hijos; el curso sustituye parte del gasto en clases particulares. Si el acceso es gratuito, déjalo vacío."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'zakup-konsumencki'
    and s.key = 'prywatny-budzet' and f.key = 'kategoria';
update public.stage_points p set translations = '{"de":{"title":"Wie du Kunden findest und was das kostet","guide_body":"Lege fest, für wen das Produkt ist\nLege zuerst genau fest, an wen sich dein Produkt richtet. Versuche, die Merkmale deiner Kunden sehr detailliert zu beschreiben. Wenn deine Idee zum Beispiel ein innovativer Abiturkurs wäre, schreib nicht „Meine Kunden sind Oberstufenschüler“. Schreib „Meine Kunden sind Oberstufenschüler, die sich auf das Abitur in Englisch auf erhöhtem Niveau vorbereiten. Ich richte das Produkt an Schüler, die ihren Bildungsweg gewechselt haben, Rückstände oder Lernschwierigkeiten haben und in Rekordzeit aufholen müssen.“ Es ist wichtig, genau zu wissen, wer deine Lösung nutzen wird. So findest du leichter Kunden und direkte Konkurrenz.\nFinde heraus, wo deine Kunden sind\nÜberlege, wie du Kunden am leichtesten erreichst und wo du sie gewinnst. Heute sind das meist Gruppen in sozialen Netzwerken, Messen, Fachveranstaltungen oder Werbung. Denk darüber nach, wo deine Zielgruppe Informationen bekommt, Gedanken teilt und nach Lösungen sucht. Diesen Ort genau zu bestimmen ist entscheidend, um Kunden zu gewinnen und mit ihnen in Kontakt zu kommen.\nTeste eine einfache Anzeige:\nErstelle eine Anzeige zu deinem Produkt. Teile sie in einem gewählten sozialen Kanal, den potenzielle Kunden nutzen. Sieh nach, wen deine Idee interessiert und wie viele Nutzer du gewinnen kannst. Es muss keine Anzeige für das fertige Produkt sein. Die Kunden sagen dir selbst, was sie brauchen und wodurch sich dein Produkt abheben würde. Nutze ihr Wissen und ihr Feedback.\nBerechne die Kosten für die Gewinnung eines Kunden:\nTeile das für Werbung oder Bewerbung der Anzeige ausgegebene Geld durch die Zahl der Kunden, die angegeben haben, das Produkt nutzen zu wollen. In diesem Unterpunkt berücksichtigst du auch die Vergütung des Marketingteams, Kosten für E-Mail-Werkzeuge usw. So erfährst du, was dich die Gewinnung eines Kunden kostet. Wenn deine Werbung keine zusätzlichen Mittel erforderte, schreib das in das Feld. Je günstiger du Kunden gewinnst, desto besser. Denk aber daran, dass sich bezahlte Anzeigen und Werbung manchmal lohnen, weil du damit mehr Menschen erreichst.\nWähle die Art der Werbung:\nAnfangs lohnt es sich nicht, sich auf eine Werbeform festzulegen. Teste verschiedene Quellen. So siehst du, wo sich Kunden am günstigsten gewinnen lassen. Wähle nach der Testphase die Quelle mit den besten Ergebnissen. Behalte ein oder zwei weitere für die Zukunft."},"uk":{"title":"Як знайти клієнтів і скільки це коштує","guide_body":"Визнач, для кого продукт\nСпершу точно визнач, до кого спрямовуєш свій продукт. Спробуй дуже детально описати характеристики свого клієнта. Наприклад, якщо твоєю ідеєю був би інноваційний курс підготовки до ЗНО, не пиши «мій клієнт — учень старшої школи». Напиши: «Мій клієнт — учень старшої школи, який готується до ЗНО з англійської мови на поглибленому рівні. Я спрямовую продукт на учнів, які змінили напрям навчання, мають прогалини чи труднощі в навчанні й мусять надолужити за рекордний час». Важливо точно знати, хто користуватиметься твоїм рішенням. Так тобі буде легше знайти клієнтів і прямих конкурентів.\nЗнайди, де перебувають твої клієнти\nПодумай, як найлегше дістатися до клієнта і де його здобути. Сьогодні це найчастіше групи в соцмережах, ярмарки, тематичні події чи реклама. Подумай, де твоя цільова група отримує інформацію, ділиться думками, шукає рішення. Точне визначення цього місця — ключ до здобуття клієнта й контакту з ним.\nПротестуй просте оголошення:\nСтвори оголошення про свій продукт. Поширь його в обраному соціальному каналі, яким користуються потенційні клієнти. Подивися, кого зацікавить твоя ідея і скільки користувачів ти можеш здобути. Це не мусить бути оголошення готового продукту. Клієнти самі підкажуть, чого потребують і що вирізнить твій продукт. Скористайся їхніми знаннями й відгуками.\nПорахуй вартість здобуття одного клієнта:\nПоділи суму, витрачену на рекламу чи просування оголошення, на кількість клієнтів, які заявили бажання користуватися продуктом. У цьому підпункті враховуєш також оплату маркетингової команди, вартість інструментів для розсилок тощо. Так ти дізнаєшся, скільки коштує тобі здобуття одного клієнта. Якщо твій спосіб просування не вимагав додаткових коштів, напиши це в полі. Що дешевше здобуваєш клієнтів, то краще. Але пам’ятай, що іноді варто скористатися платними оголошеннями й рекламою — так ти охопиш більше людей.\nОбери спосіб реклами:\nНа початку не варто замикатися на одному способі реклами. Протестуй різні джерела. Так побачиш, де найвигідніше здобувати клієнтів. Після фази тестів обери джерело, яке дало найкращі результати. Не забудь зберегти одне чи два додаткових на майбутнє."},"es":{"title":"Cómo encontrar clientes y cuánto cuesta","guide_body":"Define para quién es el producto\nPrimero, define con precisión a quién diriges tu producto. Intenta describir con mucho detalle las características de tu cliente. Por ejemplo, si tu idea fuera un curso innovador de preparación para la selectividad, no escribas «mi cliente es un estudiante de bachillerato». Escribe: «Mi cliente es un estudiante de bachillerato que se prepara el examen de inglés de nivel avanzado. Dirijo el producto a alumnos que han cambiado de itinerario, van retrasados o tienen dificultades y necesitan ponerse al día en tiempo récord». Es importante saber exactamente quién usará tu solución. Así te será más fácil encontrar clientes y competencia directa.\nEncuentra dónde están tus clientes\nPiensa cuál es la forma más fácil de llegar al cliente y dónde captarlo. Hoy suelen ser grupos en redes sociales, ferias, eventos temáticos o anuncios. Piensa dónde se informa tu público objetivo, dónde comparte opiniones y busca soluciones. Definir con precisión ese lugar es clave para captar clientes y contactar con ellos.\nPrueba un anuncio sencillo:\nCrea un anuncio sobre tu producto. Publícalo en el canal social elegido que usen tus posibles clientes. Mira a quién le interesa tu idea y cuántos usuarios puedes conseguir. No tiene que ser el anuncio del producto final. Los propios clientes te dirán qué necesitan y qué haría destacar tu producto. Aprovecha su conocimiento y sus comentarios.\nCalcula el coste de conseguir un cliente:\nDivide el dinero gastado en anuncios o en promocionar el anuncio entre el número de clientes que dijeron querer usar el producto. En este subpunto incluyes también el sueldo del equipo de marketing, el coste de las herramientas de email, etc. Así sabrás cuánto te cuesta conseguir un cliente. Si tu forma de promoción no requirió financiación adicional, escríbelo en el campo. Cuanto más barato consigas clientes, mejor. Recuerda, eso sí, que a veces compensa usar anuncios de pago: así llegas a más personas.\nElige la forma de anunciarte:\nAl principio no conviene limitarse a una sola forma de anunciarse. Prueba distintas fuentes. Así verás dónde sale más rentable conseguir clientes. Tras la fase de pruebas, elige la fuente que dio mejores resultados. Recuerda guardar una o dos más para el futuro."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2c' and p.key = 'pozyskanie-klientow';
update public.stage_subpoints s set translations = '{"de":{"title":"Finde die Orte, an denen deine Kunden sind"},"uk":{"title":"Знайди місця, де є твої клієнти"},"es":{"title":"Encuentra los lugares donde están tus clientes"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'b2c' and p.key = 'pozyskanie-klientow' and s.key = 'gdzie-sa-klienci';
update public.stage_fields f set translations = '{"de":{"question":"An wen genau richtet sich dein Produkt?","help":"Je enger, desto günstiger findest du sie. „Alle“ ist die teuerste Zielgruppe der Welt."},"uk":{"question":"До кого саме ти спрямовуєш продукт?","help":"Що вужче, то дешевше їх знайдеш. «Усі» — найдорожча цільова група у світі."},"es":{"question":"¿A quién exactamente diriges el producto?","help":"Cuanto más concreto, más barato encontrarlos. «Todo el mundo» es el público objetivo más caro del mundo."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'pozyskanie-klientow'
    and s.key = 'gdzie-sa-klienci' and f.key = 'do-kogo';
update public.stage_fields f set translations = '{"de":{"question":"Wähle 3–5 Orte, an denen du sie am leichtesten erreichst.","help":"Z. B. Facebook-Gruppen, Anzeigen, Messen, Fachforen, Branchen-Newsletter."},"uk":{"question":"Обери 3–5 місць, де найлегше до них дістатися.","help":"Напр. групи у Facebook, реклама, ярмарки, тематичні форуми, галузеві розсилки."},"es":{"question":"Elige 3–5 lugares donde sea más fácil llegar a ellos.","help":"P. ej. grupos de Facebook, anuncios, ferias, foros temáticos, newsletters del sector."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'pozyskanie-klientow'
    and s.key = 'gdzie-sa-klienci' and f.key = 'miejsca';
