    and t.key = 'idea' and t.version = 1 and c.key = 'b2c' and p.key = 'pozyskanie-klientow'
    and s.key = 'koszt-klienta' and f.key = 'cac';
update public.stage_fields f set translations = '{"de":{"question":"Lohnt sich das bei diesen Kosten überhaupt?","help":"Vergleiche es mit dem geplanten Preis. Wenn die Gewinnung eines Kunden mehr kostet, als er zahlt, hast du ein Problem, das jetzt gelöst werden muss — nicht später."},"uk":{"question":"Чи за такої вартості це взагалі вигідно?","help":"Порівняй із ціною, яку плануєш. Якщо здобуття клієнта коштує більше, ніж він заплатить, — у тебе проблема, яку треба розв’язати зараз, а не пізніше."},"es":{"question":"¿Compensa siquiera con este coste?","help":"Compáralo con el precio que planeas. Si conseguir un cliente cuesta más de lo que pagará, tienes un problema que resolver ahora, no más tarde."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
