  where p.category_id = c.id and c.template_id = t.id and t.key = 'idea' and t.version = 1
    and c.key = 'hardware' and p.key = 'koszty-jednostkowe';
update public.stage_subpoints s set translations = '{"de":{"title":"Erstelle eine erste Stückliste"},"uk":{"title":"Склади попередній список деталей"},"es":{"title":"Elabora una lista inicial de piezas"}}'::jsonb
