update public.stage_fields f set translations = '{"de":{"question":"Ermöglicht die angenommene Marge eine rentable Weiterentwicklung des Projekts?","help":"Bei Hardware müssen davon Produktion, Lager, Versand, Rücksendungen, Service und Vertrieb gedeckt werden."},"uk":{"question":"Чи дає закладена маржа змогу вигідно розвивати проєкт?","help":"У залізі з неї треба покрити виробництво, склад, доставку, повернення, сервіс і дистрибуцію."},"es":{"question":"¿Permite el margen previsto desarrollar el proyecto de forma rentable?","help":"En hardware, con él hay que cubrir fabricación, almacén, envío, devoluciones, servicio técnico y distribución."}}'::jsonb
