update public.stage_fields f set translations = '{"de":{"question":"Wer spürt das Problem am stärksten und wem reicht die erste Version des Geräts?","help":"Eine kleine Gruppe, die Unvollkommenheiten verzeiht, weil sie die Lösung dringend braucht."},"uk":{"question":"Хто відчуває проблему найсильніше і кому вистачить першої версії пристрою?","help":"Вузька група, яка пробачить недосконалості, бо дуже потребує рішення."},"es":{"question":"¿Quién sufre más el problema y a quién le basta la primera versión del dispositivo?","help":"Un grupo reducido que perdona imperfecciones porque necesita mucho la solución."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'idea' and t.version = 1 and c.key = 'hardware' and p.key = 'zamiar-zakupu'
