update public.stage_fields f set translations = '{"de":{"question":"Zu welcher Gruppe gehört das Gerät?","help":"Davon hängt ab, wie viele Zertifizierungen du brauchst und wie lange das dauert.","config":{"options":[{"value":"consumer","label":"Gewöhnliche Unterhaltungselektronik"},{"value":"medical","label":"Medizinprodukt"},{"value":"food","label":"Kontakt mit Lebensmitteln"},{"value":"high-voltage","label":"Betrieb unter Hochspannung"},{"value":"other","label":"Andere Kategorie"}]}},"uk":{"question":"До якої групи належить пристрій?","help":"Від цього залежить, скільки сертифікацій тобі знадобиться і скільки це триватиме.","config":{"options":[{"value":"consumer","label":"Звичайна побутова електроніка"},{"value":"medical","label":"Медичний виріб"},{"value":"food","label":"Контакт із харчами"},{"value":"high-voltage","label":"Робота під високою напругою"},{"value":"other","label":"Інша категорія"}]}},"es":{"question":"¿A qué grupo pertenece el dispositivo?","help":"De esto depende cuántas certificaciones necesitarás y cuánto tardarán.","config":{"options":[{"value":"consumer","label":"Electrónica de consumo corriente"},{"value":"medical","label":"Producto sanitario"},{"value":"food","label":"Contacto con alimentos"},{"value":"high-voltage","label":"Funcionamiento con alta tensión"},{"value":"other","label":"Otra categoría"}]}}}'::jsonb
