    and s.key = 'decyzja' and f.key = 'podsumowanie';

-- ═══ preparation v1 ═══
update public.stage_templates t set translations = '{"de":{"title":"Preparation","subtitle":"Bereite dich auf den Bau vor","intro":"Du hast eine Idee und erste Erkenntnisse aus Gesprächen. Plane jetzt, was bis zur ersten Version zu tun ist, hol dir Hilfe, wenn du sie brauchst, und sammle Dateien und Dinge für den Start. Wer allein arbeitet, kann diese Etappe auch ohne Team durchlaufen.","finish_label":"Ich beginne mit dem Bau"},"uk":{"title":"Preparation","subtitle":"Підготуйся до створення","intro":"У тебе є ідея й перші висновки з розмов. Тепер розпиши, що треба зробити до першої версії, знайди допомогу, якщо вона потрібна, збери файли й речі на старт. Людина, що працює сама, може пройти цей етап без команди.","finish_label":"Починаю створення"},"es":{"title":"Preparation","subtitle":"Prepárate para construir","intro":"Tienes una idea y las primeras conclusiones de las conversaciones. Ahora detalla qué hay que hacer hasta la primera versión, consigue ayuda si la necesitas y reúne archivos y lo necesario para empezar. Quien trabaja en solitario puede hacer esta etapa sin equipo.","finish_label":"Empiezo a construir"}}'::jsonb
  where t.key = 'preparation' and t.version = 1;
update public.stage_categories c set translations = '{"de":{"title":"Allgemein","intro":"Dieser Teil betrifft jedes Startup. SaaS, Hardware, B2B und B2C fügen eigene Punkte nur hinzu, wenn das Startup diese Kategorie hat."},"uk":{"title":"Загальне","intro":"Ця частина стосується кожного стартапу. SaaS, Hardware, B2B і B2C додають власні пункти лише тоді, коли стартап має цю категорію."},"es":{"title":"General","intro":"Esta parte se aplica a todas las startups. SaaS, Hardware, B2B y B2C añaden sus propios puntos solo si la startup tiene esa categoría."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'preparation' and t.version = 1 and c.key = 'general';
update public.stage_points p set translations = '{"de":{"title":"Sprich mit den Menschen, denen du helfen willst","guide_body":"Jetzt prüfst du deine bisherigen Vermutungen in Gesprächen. Du suchst nach konkreten Ereignissen, die zeigen, ob das Problem auftritt, wie es stört und was Menschen dagegen tun. Bereite einen Platz für Notizen und ein paar Hilfsfragen vor.\nFinde mindestens fünf Gesprächspartner\nGeh zur Beschreibung der Zielperson aus Punkt 1 zurück. Suche Personen, die die genannte Tätigkeit ausüben. Lade für das Shop-Beispiel jemanden ein, der für Warenbestellungen zuständig ist. Allein im Laden zu arbeiten reicht womöglich nicht.\nBeginne mit Bekannten, Empfehlungen, Themengruppen, lokalen Firmen oder Veranstaltungen. Du kannst schreiben: „Ich versuche zu verstehen, wie Inhaber kleiner Shops Warenbestellungen planen. Hast du 15 Minuten, um mir zu erzählen, wie das bei dir läuft?“ Die genannte Zeit ist ein Beispiel für ein kurzes Treffen.\nEin Bekannter ist ein passender Gesprächspartner, wenn er zur Gruppe passt. Es lohnt sich, auch über das eigene Umfeld hinauszugehen. Fünf Gespräche sind der Anfang, den diese Übung vorsieht. Betrachte diese Zahl nicht als Garantie, dass die Bedürfnisse der ganzen Gruppe schon bekannt sind.\nFrag nach Ereignissen und hör auf die Antworten\nErkläre am Anfang, welches Thema du verstehen willst. Die Beschreibung der Lösung kommt später, damit du nicht vorgibst, was du hören willst. Hilfreiche Fragen sind:\nWie lief das letzte Auffüllen des Lagers in deinem Shop ab?\nAn welcher Stelle trat eine Schwierigkeit auf? Was ist dann passiert?\nWie oft kommt eine ähnliche Situation vor?\nWas hast du damals getan, um zurechtzukommen, und mit welchem Ergebnis?\nWie viel Zeit hat es gekostet oder wie viel Geld? Woher stammt diese Einschätzung?\nDu musst die Fragen nicht der Reihe nach vorlesen. Frag bei unklaren Antworten nach: „Was meinst du damit?“ oder „Kannst du ein Beispiel nennen?“ Wenn jemand sagt, die heutige Art reiche aus, lass es ihn erklären. Vermeide die Frage „Verschwendest du auch Zeit mit diesen furchtbaren Dateien?“, die eine Bewertung nahelegt.\nWenn die Idee für eine neue Funktion fällt, frag, in welcher Situation sie gebraucht würde. So erfährst du den Grund der Bitte. Wenn dein Gegenüber deine Idee sehen will, beende zuerst den Teil über Erfahrungen und trenne die spätere Vorstellung deutlich davon.\nHalte jedes Gespräch getrennt fest\nNotiere Datum, eine kurze Beschreibung der Rolle deines Gegenübers, den konkreten Fall, die Häufigkeit, die heutige Vorgehensweise und die Folgen. Notiere auch Situationen, in denen das Problem nicht auftrat oder keine große Rolle spielte. Kennzeichne ein Zitat nur dann als Zitat, wenn du dich an den genauen Wortlaut erinnerst. Nimm nur mit Zustimmung deines Gegenübers auf.\nTrenne die Antwort von deiner eigenen Schlussfolgerung. „Er sagte, er habe eine Stunde lang Dateien verglichen“ ist eine Information aus dem Gespräch. „Er wird für Zeitersparnis zahlen wollen“ ist deine Vermutung. Wenn es keine Antwort gibt, trag „keine Information“ ein.\nVergleiche die Gespräche und überarbeite die Annahmen\nStelle die Antworten zu denselben Fragen nebeneinander: Wer hat die Schwierigkeit, wie oft, was tut er dagegen und wie sehr stört sie ihn. Bei einer kleinen Gruppe ist „3 von 5 Personen haben einen solchen Fall beschrieben“ übersichtlicher als ein einsames „60 %“. Übertrage dieses Ergebnis nicht auf alle potenziellen Kunden.\nListe wiederkehrende Beobachtungen auf und getrennt davon, was der Idee widerspricht. Wenn nur ein Teil der Gesprächspartner das Problem hat, prüfe, was sie verbindet. Vielleicht lohnt es sich, die Gruppe einzugrenzen. Wenn die Berichte unklar oder widersprüchlich sind, notiere eine konkrete Unbekannte und plane weitere Gespräche, um sie zu klären.\nNach diesem Punkt hast du Gesprächsnotizen, gemeinsame Beobachtungen und eine überarbeitete Problembeschreibung. Geh auch zu Punkt 2 zurück, wenn die vorgeschlagene Lösung nicht mehr zu dem passt, was die Gespräche ergeben haben.","guide_sources":["Eric Migicovsky, How to Talk to Users. Grundlage: Gespräche über konkrete Erfahrungen, heutige Vorgehensweisen und Schwierigkeiten. Der Link führt zu einer Zusammenfassung und Aufzeichnung des Vortrags.","Paul Graham, Do Things that Don''t Scale. Grundlage: die ersten Zielpersonen persönlich erreichen.","Paul Graham, Before the Startup. Grundlage: Wissen über Nutzer aufbauen."]},"uk":{"title":"Поговори з людьми, яким хочеш допомогти","guide_body":"Тепер ти перевіриш попередні припущення в розмовах. Шукатимеш конкретні події, які показують, чи проблема виникає, як заважає і що люди з нею роблять. Підготуй місце для нотаток і кілька допоміжних запитань.\nЗнайди щонайменше п’ятьох співрозмовників\nПовернися до опису адресата з пункту 1. Шукай людей, які виконують зазначену дію. Для прикладу з магазином запроси когось, хто відповідає за замовлення товару. Самого факту роботи в магазині може бути замало.\nПочни зі знайомих, рекомендацій, тематичних груп, місцевих компаній чи подій. Можна написати: «Я намагаюся зрозуміти, як власники невеликих магазинів планують замовлення товару. Знайдеш 15 хвилин, щоб розповісти, як це виглядає в тебе?». Указаний час — приклад пропозиції короткої зустрічі.\nЗнайомий — відповідний співрозмовник, якщо пасує до групи. Варто вийти й за межі власного оточення. П’ять розмов — це початок, передбачений цією вправою. Не сприймай це число як гарантію, що потреби всієї групи вже відомі.\nПитай про події і слухай відповіді\nНа початку поясни, яку тему хочеш зрозуміти. Опис рішення залиш на потім, щоб не підказувати співрозмовникові, що хочеш почути. Корисні запитання:\nЯк виглядало останнє поповнення запасів у твоєму магазині?\nУ який момент виникла трудність? Що тоді сталося?\nЯк часто трапляється схожа ситуація?\nЩо вдалося тоді зробити, щоб дати собі раду, і який був результат?\nСкільки часу це забрало або скільки коштувало? Звідки така оцінка?\nНе обов’язково читати запитання по черзі. Уточнюй незрозумілі відповіді: «Що ти маєш на увазі?» або «Можеш навести приклад?». Якщо хтось каже, що теперішнього способу досить, дай йому це пояснити. Уникай запитання «Ти теж марнуєш час на ці жахливі файли?», яке підказує оцінку.\nКоли звучить ідея нової функції, запитай, у якій ситуації вона була б потрібна. Так пізнаєш причину прохання. Якщо співрозмовник хоче подивитися на твою ідею, спершу заверши частину про досвід і чітко відокрем пізнішу презентацію.\nЗаписуй кожну розмову окремо\nУ нотатці вкажи дату, короткий опис ролі співрозмовника, конкретний випадок, частоту, теперішній спосіб дій і наслідки. Запиши також ситуації, коли проблема не виникала або не мала великого значення. Позначай цитату як цитату лише тоді, коли пам’ятаєш точні слова. Записуй розмову лише за згоди співрозмовника.\nВідокремлюй відповідь від власного висновку. «Сказав, що порівнював файли годину» — це інформація з розмови. «Захоче платити за економію часу» — твоє припущення. Якщо відповіді немає, впиши «немає інформації».\nПорівняй розмови і виправ припущення\nЗістав відповіді на ті самі запитання: хто має труднощі, як часто, що з ними робить і наскільки вони йому заважають. За малої групи запис «3 з 5 людей описали такий випадок» прозоріший, ніж самотнє «60%». Не переноси цей результат на всіх потенційних клієнтів.\nВипиши повторювані спостереження і окремо те, що суперечить ідеї. Якщо проблему має лише частина співрозмовників, перевір, що їх об’єднує. Можливо, варто звузити групу. Якщо розповіді неясні чи суперечливі, запиши конкретну невідому й добери наступні розмови для її з’ясування.\nПісля цього пункту в тебе є нотатки з розмов, спільні спостереження й виправлений опис проблеми. Повернися також до пункту 2, якщо запропоноване рішення перестало пасувати до того, що показали розмови.","guide_sources":["Eric Migicovsky, How to Talk to Users. Основа: розмови про конкретний досвід, теперішні способи дій і труднощі. Посилання веде до огляду й запису лекції.","Paul Graham, Do Things that Don''t Scale. Основа: особисте охоплення перших адресатів.","Paul Graham, Before the Startup. Основа: накопичення знань про користувачів."]},"es":{"title":"Habla con las personas a las que quieres ayudar","guide_body":"Ahora comprobarás tus suposiciones anteriores en conversaciones. Buscarás hechos concretos que muestren si el problema existe, cómo molesta y qué hace la gente con él. Prepara un sitio para notas y unas cuantas preguntas de apoyo.\nEncuentra al menos cinco interlocutores\nVuelve a la descripción del destinatario del punto 1. Busca personas que hagan la actividad indicada. Para el ejemplo de la tienda, invita a alguien responsable de pedir la mercancía. Trabajar en una tienda puede no bastar.\nEmpieza por conocidos, recomendaciones, grupos temáticos, empresas locales o eventos. Puedes escribir: «Intento entender cómo planifican los pedidos de mercancía los dueños de tiendas pequeñas. ¿Tienes 15 minutos para contarme cómo lo haces tú?». El tiempo indicado es un ejemplo de reunión breve.\nUn conocido es un buen interlocutor si encaja en el grupo. Conviene llegar también más allá de tu entorno. Cinco conversaciones son el inicio previsto en este ejercicio. No tomes esa cifra como garantía de que ya conoces las necesidades de todo el grupo.\nPregunta por hechos y escucha las respuestas\nAl principio explica qué tema quieres entender. Deja la descripción de la solución para después, para no sugerir lo que quieres oír. Preguntas útiles:\n¿Cómo fue la última vez que repusiste existencias en tu tienda?\n¿En qué momento apareció la dificultad? ¿Qué pasó entonces?\n¿Con qué frecuencia ocurre algo parecido?\n¿Qué hiciste entonces para arreglártelas y qué resultado tuvo?\n¿Cuánto tiempo o dinero te llevó? ¿De dónde sale esa estimación?\nNo tienes que leer las preguntas en orden. Pide aclaraciones ante respuestas confusas: «¿Qué quieres decir?» o «¿Puedes darme un ejemplo?». Si alguien dice que su forma actual le basta, deja que lo explique. Evita preguntas como «¿Tú también pierdes el tiempo con esos archivos horribles?», que sugieren una valoración.\nCuando surja la idea de una función nueva, pregunta en qué situación haría falta. Así conocerás el motivo de la petición. Si tu interlocutor quiere ver tu idea, termina primero la parte sobre experiencias y separa claramente la presentación posterior.\nAnota cada conversación por separado\nEn la nota pon la fecha, una breve descripción del papel del interlocutor, el caso concreto, la frecuencia, la forma actual de actuar y las consecuencias. Anota también las situaciones en las que el problema no apareció o no tuvo mucha importancia. Marca algo como cita solo si recuerdas las palabras exactas. Graba únicamente con el consentimiento de tu interlocutor.\nSepara la respuesta de tu propia conclusión. «Dijo que estuvo una hora comparando archivos» es información de la conversación. «Querrá pagar por ahorrar tiempo» es tu suposición. Si no hay respuesta, escribe «sin información».\nCompara las conversaciones y corrige las suposiciones\nPon juntas las respuestas a las mismas preguntas: quién tiene la dificultad, con qué frecuencia, qué hace con ella y cuánto le molesta. Con un grupo pequeño, «3 de 5 personas describieron un caso así» es más claro que un «60 %» aislado. No traslades ese resultado a todos los posibles clientes.\nEnumera las observaciones que se repiten y, aparte, lo que contradice la idea. Si solo parte de los interlocutores tiene el problema, comprueba qué los une. Quizá convenga acotar el grupo. Si los relatos son confusos o contradictorios, anota una incógnita concreta y busca más conversaciones para aclararla.\nTras este punto tienes notas de las conversaciones, observaciones comunes y una descripción del problema corregida. Vuelve también al punto 2 si la solución propuesta ha dejado de encajar con lo que salió en las conversaciones.","guide_sources":["Eric Migicovsky, How to Talk to Users. Base: conversaciones sobre experiencias concretas, formas actuales de actuar y dificultades. El enlace lleva a un resumen y la grabación de la charla.","Paul Graham, Do Things that Don''t Scale. Base: llegar personalmente a los primeros destinatarios.","Paul Graham, Before the Startup. Base: construir conocimiento sobre los usuarios."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'rozmowy';
update public.stage_subpoints s set translations = '{"de":{"title":"Finde Gesprächspartner"},"uk":{"title":"Знайди співрозмовників"},"es":{"title":"Encuentra interlocutores"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'rozmowy' and s.key = 'znajdz-rozmowcow';
update public.stage_fields f set translations = '{"de":{"question":"Finde mindestens 5 Personen, die das gewählte Problem betreffen kann.","help":"Trag einen Namen oder eine Beschreibung ein, damit du weißt, mit wem das Gespräch war. Es müssen keine Fremden sein — beginne mit Bekannten aus der Branche."},"uk":{"question":"Знайди щонайменше 5 людей, яких може стосуватися обрана проблема.","help":"Впиши ім’я або опис, щоб знати, з ким була розмова. Це не мусять бути незнайомці — почни зі знайомих із галузі."},"es":{"question":"Encuentra al menos 5 personas a las que pueda afectar el problema elegido.","help":"Escribe un nombre o una descripción para saber con quién hablaste. No tienen que ser desconocidos: empieza por conocidos del sector."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'rozmowy'
    and s.key = 'znajdz-rozmowcow' and f.key = 'osoby';
update public.stage_subpoints s set translations = '{"de":{"title":"Frag nach ihren Erfahrungen","description":"Stelle deine Idee am Anfang nicht vor. Frag, was sie getan haben, nicht, was sie tun würden."},"uk":{"title":"Запитай про їхній досвід","description":"На початку не представляй своєї ідеї. Питай про те, що вони робили, а не що зробили б."},"es":{"title":"Pregunta por sus experiencias","description":"Al principio no presentes tu idea. Pregunta qué hicieron, no qué harían."}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'rozmowy' and s.key = 'zapytaj-o-doswiadczenia';
update public.stage_fields f set translations = '{"de":{"question":"Notiere nach jedem Gespräch, was du daraus erfährst.","help":"Wann trat das Problem zuletzt auf und wie oft kommt es vor? Wie kommt die Person damit zurecht? Was ist daran am lästigsten und wie viel Zeit, Geld oder Mühe kostet es sie?"},"uk":{"question":"Після кожної розмови запиши, що з неї дізнаєшся.","help":"Коли востаннє виникла ця проблема і як часто трапляється? Як ця людина з нею дає раду? Що в цьому найнеприємніше і скільки часу, грошей чи зусиль це їй коштує?"},"es":{"question":"Después de cada conversación, anota lo que has aprendido.","help":"¿Cuándo apareció el problema por última vez y con qué frecuencia ocurre? ¿Cómo se las arregla esa persona? ¿Qué es lo más molesto y cuánto tiempo, dinero o esfuerzo le cuesta?"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'rozmowy'
    and s.key = 'zapytaj-o-doswiadczenia' and f.key = 'zapisy';
update public.stage_fields f set translations = '{"de":{"question":"Aufnahmen oder Notizen der Gespräche"},"uk":{"question":"Записи або нотатки з розмов"},"es":{"question":"Grabaciones o notas de las conversaciones"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'rozmowy'
    and s.key = 'zapytaj-o-doswiadczenia' and f.key = 'materialy';
update public.stage_subpoints s set translations = '{"de":{"title":"Fasse die Gespräche zusammen"},"uk":{"title":"Підсумуй розмови"},"es":{"title":"Resume las conversaciones"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'rozmowy' and s.key = 'podsumuj-rozmowy';
update public.stage_fields f set translations = '{"de":{"question":"Was wiederholte sich in den Antworten?","help":"Etwas, das drei von fünf Personen gesagt haben, ist wichtiger als die interessanteste Bemerkung einer einzelnen."},"uk":{"question":"Що повторювалося у відповідях?","help":"Те, що сказали троє з п’яти, важливіше за найцікавіше зауваження одного."},"es":{"question":"¿Qué se repetía en las respuestas?","help":"Lo que dijeron tres personas de cinco importa más que el comentario más interesante de una sola."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'rozmowy'
    and s.key = 'podsumuj-rozmowy' and f.key = 'powtarzalo';
update public.stage_fields f set translations = '{"de":{"question":"Was spricht dafür, dieses Problem zu lösen, und was stellt deine Annahmen infrage?","help":"Notiere auch, was dir nicht gefallen hat. Ein widersprechender Beleg ist mehr wert als zehn Bestätigungen."},"uk":{"question":"Що вказує, що варто розв’язувати цю проблему, а що підважує твої припущення?","help":"Запиши й те, що тобі не сподобалося. Суперечливий доказ вартий більше, ніж десять підтверджень."},"es":{"question":"¿Qué indica que merece la pena resolver este problema y qué pone en duda tus suposiciones?","help":"Anota también lo que no te gustó. Una prueba en contra vale más que diez confirmaciones."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'rozmowy'
    and s.key = 'podsumuj-rozmowy' and f.key = 'za-i-przeciw';
update public.stage_points p set translations = '{"de":{"title":"Was können wir selbst machen? Und was nicht?","duration_hint":"Etwa 15 Minuten","guide_body":"Schreib die zu erledigenden Aufgaben auf\nGeh zur Idee aus der Idea Stage zurück und liste die Arbeiten auf, die nötig sind, um die erste einfache Version vorzubereiten, die jemand nutzen kann. Wähle Aufgaben, die zum Hauptnutzen für die Nutzer führen. Extras kannst du später erwägen.\nNotiere konkrete Arbeitsergebnisse. „Ein Anmeldeformular vorbereiten“ lässt beurteilen, wer das machen kann. Das allgemeine Stichwort „Technik“ sagt wenig über die nötige Hilfe.\nVermerke bei jeder Aufgabe, ob du sie erledigen kannst, etwas lernen musst oder jemanden dafür suchst. Beispieleinträge: Bedienungsanleitung vorbereiten — mache ich selbst; ein einfaches Formular einrichten — ich lerne das gewählte Werkzeug; ein Gehäusemodell anfertigen — ich brauche jemanden, der es entwerfen kann.\nWähle zum Lernen Fähigkeiten, die zu einer konkreten Aufgabe gehören. „Ich lerne, ein Formular zu bauen“ hilft, die passende Anleitung zu finden. „Ich lerne programmieren“ umfasst deutlich mehr Arbeit. Wenn das Lernen den Start stark verzögern würde, überlege, eine andere Person um Hilfe zu bitten.\n§\nBrauchst du eine Mitgründerin oder einen Mitgründer\nEin Co-Founder ist eine Mitgründerin oder ein Mitgründer: eine Person, mit der du die Firma gemeinsam entwickelst und Verantwortung für ihre Zukunft trägst. Suche sie, wenn du einen langfristigen Beitrag in einem wichtigen Bereich brauchst. Die Größe einer einzelnen Aufgabe entscheidet allein nicht über den Bedarf an einer Partnerin.\nBeschreibe im Profil, wofür diese Person verantwortlich sein soll. Beispiel: „Erste Version des Programms vorbereiten und nach den Tests weiterentwickeln.“ Passe dann die Anforderungen an: Was Ähnliches sollte sie schon vorweisen können, welche Zusammenarbeit erwartest du und wie viel Zeit kann sie regelmäßig investieren.\nAnteile sind ein Teil des Eigentums an der Firma. Betrachte die eingetragene Spanne als ersten Vorschlag für das Gespräch. Berücksichtige Verantwortung und Beitrag zur weiteren Entwicklung. Die Erledigung einer einzelnen Aufgabe ist keine Grundlage für einen Prozentsatz. Es ist ratsam, die Aufteilung früh zu besprechen, aber es gibt keinen Umrechnungskurs „Aufgabe gegen Prozent“.\nWenn Hilfe bei einer bestimmten Arbeit genügt, geh zu den Personen über, die für eine konkrete Aufgabe gebraucht werden.\n§\nPersonen für eine konkrete Arbeit\nNimm die Aufgaben, die Hilfe brauchen, aber ein festes Ende haben. Das kann eine Grafik sein, ein Modell, eine technische Beratung oder die Prüfung einer konkreten Lösung.\nBeschreibe die Fähigkeit, mit der sich diese Aufgabe erledigen lässt. Beispiel: „Ich brauche einen druckfertigen Verpackungsentwurf. Ich suche jemanden, der solche Dateien schon vorbereitet hat.“\nNenne den Betrag, den du für diese Arbeit ausgeben kannst. Wenn du kein Budget hast, vermerke das. So ist bei der Suche nach Hilfe sofort klar, welche Bedingungen du anbieten kannst.","guide_sources":["Michael Seibel, How to Plan an MVP (Startup School, 2019): die erste Version auf den Grundnutzen begrenzen.","Michael Seibel, One Order of Operations for Starting a Startup (2018): Fähigkeiten, die für die erste Lösung nötig sind.","Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): Verantwortung, Zeit, Erwartungen und Anteile."]},"uk":{"title":"Що ми можемо зробити самі? А що ні?","duration_hint":"Близько 15 хвилин","guide_body":"Розпиши завдання до виконання\nПовернися до ідеї з Idea Stage і випиши роботи, потрібні для підготовки першої простої версії, якою хтось може скористатися. Обери завдання, що ведуть до головної користі для користувача. Доповнення можна розглянути пізніше.\nЗаписуй конкретні результати роботи. «Підготувати форму заявок» дає змогу оцінити, хто може це зробити. Загальне гасло «технології» мало що каже про потрібну допомогу.\nБіля кожного завдання вкажи, чи вмієш його виконати, чи треба чогось навчитися, чи шукаєш виконавця. Приклади записів: підготувати інструкцію користування — зроблю сам; запустити просту форму — навчуся користуватися обраним інструментом; виготовити модель корпусу — потрібна людина, яка вміє її спроєктувати.\nДля навчання обирай уміння, пов’язані з конкретним завданням. «Навчуся робити форму» допомагає знайти потрібну інструкцію. «Навчуся програмувати» охоплює значно більше роботи. Якщо здобуття вміння сильно відсунуло б старт, подумай про допомогу іншої людини.\n§\nЧи потрібен тобі co-founder\nCo-founder — це співзасновник: людина, з якою ти разом розвиваєш компанію й береш відповідальність за її майбутнє. Шукай її, коли потрібен тривалий внесок у важливу ділянку. Сам розмір окремого завдання не вирішує, чи потрібен партнер.\nУ профілі опиши, за що ця людина має відповідати. Приклад: «Підготовка першої версії програми та її подальший розвиток після тестів». Потім добери вимоги: що схоже вона вже має вміти показати, якої співпраці ти очікуєш і скільки часу вона може регулярно приділяти.\nЧастки — це частина власності компанії. Вписаний діапазон сприймай як попередню пропозицію для розмови. Врахуй відповідальність і внесок у подальший розвиток. Саме виконання одного завдання не дає підстав визначати відсоток. Обговорити розподіл рано — добра ідея, але курсу «завдання за відсоток» немає.\nЯкщо досить допомоги з певною роботою, переходь до людей, потрібних для конкретного завдання.\n§\nЛюди, потрібні для конкретної роботи\nВізьми завдання, які потребують допомоги, але мають чіткий кінець. Це може бути графіка, виготовлення моделі, технічна консультація або перевірка конкретного рішення.\nОпиши вміння, яке дасть змогу виконати це завдання. Приклад: «Потрібен проєкт упаковки, готовий до відправлення в друкарню. Шукаю людину, яка вже готувала такі файли».\nВкажи суму, яку можеш виділити на цю роботу. Якщо бюджету немає, познач це. Під час пошуку допомоги одразу буде зрозуміло, які умови ти можеш запропонувати.","guide_sources":["Michael Seibel, How to Plan an MVP (Startup School, 2019): обмеження першої версії базовою користю.","Michael Seibel, One Order of Operations for Starting a Startup (2018): уміння, потрібні для першого рішення.","Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): відповідальність, час, очікування й частки."]},"es":{"title":"¿Qué podemos hacer nosotros mismos? ¿Y qué no?","duration_hint":"Unos 15 minutos","guide_body":"Detalla las tareas por hacer\nVuelve a la idea de la Idea Stage y enumera los trabajos necesarios para preparar la primera versión sencilla que alguien pueda usar. Elige las tareas que llevan al beneficio principal para el usuario. Los extras puedes plantearlos después.\nAnota resultados de trabajo concretos. «Preparar un formulario de inscripción» permite valorar quién puede hacerlo. Un genérico «tecnología» dice poco de la ayuda necesaria.\nEn cada tarea indica si sabes hacerla, si necesitas aprender algo o si buscas a alguien que la haga. Ejemplos: preparar las instrucciones de uso — lo hago yo; montar un formulario sencillo — aprenderé a usar la herramienta elegida; hacer un modelo de la carcasa — necesito a alguien que sepa diseñarlo.\nPara aprender, elige habilidades ligadas a una tarea concreta. «Aprenderé a hacer un formulario» ayuda a encontrar las instrucciones adecuadas. «Aprenderé a programar» supone mucho más trabajo. Si adquirir la habilidad retrasaría mucho el inicio, plantéate la ayuda de otra persona.\n§\n¿Necesitas un cofundador?\nUn co-founder es un cofundador: alguien con quien desarrollas la empresa y compartes la responsabilidad de su futuro. Búscalo cuando necesites una aportación duradera en un área importante. El tamaño de una tarea concreta no decide por sí solo si necesitas un socio.\nEn el perfil, describe de qué será responsable esa persona. Ejemplo: «Preparar la primera versión del programa y seguir desarrollándola tras las pruebas». Después ajusta los requisitos: qué trabajo parecido debería poder mostrar, qué colaboración esperas y cuánto tiempo puede dedicar con regularidad.\nLas participaciones son una parte de la propiedad de la empresa. Toma el rango que escribas como una propuesta inicial para hablar. Ten en cuenta la responsabilidad y la aportación al desarrollo futuro. Hacer una sola tarea no basta para fijar un porcentaje. Conviene hablar pronto del reparto, pero no existe una equivalencia «tarea por porcentaje».\nSi basta con ayuda en un trabajo concreto, pasa a las personas necesarias para una tarea determinada.\n§\nPersonas para un trabajo concreto\nUsa las tareas que necesitan ayuda pero tienen un final definido. Puede ser preparar gráficos, hacer un modelo, una consulta técnica o revisar una solución concreta.\nDescribe la habilidad que permitirá hacer esa tarea. Ejemplo: «Necesito un diseño de envase listo para enviar a imprenta. Busco a alguien que ya haya preparado archivos así».\nIndica la cantidad que puedes destinar a este trabajo. Si no tienes presupuesto, indícalo. Así, al buscar ayuda, queda claro desde el principio qué condiciones puedes ofrecer.","guide_sources":["Michael Seibel, How to Plan an MVP (Startup School, 2019): limitar la primera versión al beneficio básico.","Michael Seibel, One Order of Operations for Starting a Startup (2018): habilidades necesarias para la primera solución.","Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): responsabilidad, tiempo, expectativas y participaciones."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'scope';
update public.stage_subpoints s set translations = '{"de":{"title":"Schreib die Aufgaben für die erste Version auf"},"uk":{"title":"Розпиши завдання до першої версії"},"es":{"title":"Detalla las tareas para la primera versión"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
