update public.stage_fields f set translations = '{"de":{"question":"Liste der Dinge, die für die erste Version erledigt werden müssen.","help":"Wähle Aufgaben, die zum Hauptnutzen führen. Extras kannst du später ergänzen.","example":"Bedienungsanleitung vorbereiten.\nEin einfaches Formular einrichten.\nEin Gehäusemodell anfertigen."},"uk":{"question":"Список того, що треба зробити до першої версії.","help":"Обери завдання, що ведуть до головної користі. Доповнення можна дописати пізніше.","example":"Підготувати інструкцію користування.\nЗапустити просту форму.\nВиготовити модель корпусу."},"es":{"question":"Lista de lo que hay que hacer para la primera versión.","help":"Elige las tareas que llevan al beneficio principal. Los extras puedes añadirlos después.","example":"Preparar las instrucciones de uso.\nMontar un formulario sencillo.\nHacer un modelo de la carcasa."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'scope'
    and s.key = 'tasks' and f.key = 'mvp_tasks';
update public.stage_subpoints s set translations = '{"de":{"title":"Teile diese Aufgaben auf"},"uk":{"title":"Розподіли ці завдання"},"es":{"title":"Reparte estas tareas"}}'::jsonb
