  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'scope'
    and s.key = 'split' and f.key = 'alone';
update public.stage_fields f set translations = '{"de":{"question":"Welche davon kannst du lernen?","help":"Wähle die Fähigkeit bei einer konkreten Aufgabe. Wenn das Lernen den Start stark verzögern würde, verschiebe die Aufgabe zur Hilfe anderer.","example":"Ein einfaches Formular im gewählten Werkzeug einrichten."},"uk":{"question":"Яких із них ти можеш навчитися?","help":"Обирай уміння під конкретне завдання. Якщо навчання сильно відсунуло б старт, перенеси завдання до допомоги інших людей.","example":"Запустити просту форму в обраному інструменті."},"es":{"question":"¿Cuáles puedes aprender?","help":"Elige la habilidad pensando en una tarea concreta. Si aprenderla retrasaría mucho el inicio, pasa la tarea a la ayuda de otras personas.","example":"Montar un formulario sencillo con la herramienta elegida."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
