update public.stage_fields f set translations = '{"de":{"question":"Für welche brauchst du andere Menschen?","help":"Wenn du es allein schaffst, trag „keine“ ein.","example":"Ein Gehäusemodell anfertigen."},"uk":{"question":"Для яких тобі потрібні інші люди?","help":"Якщо впораєшся сам, впиши «немає».","example":"Виготовити модель корпусу."},"es":{"question":"¿Para cuáles necesitas a otras personas?","help":"Si puedes hacerlo solo, escribe «ninguna».","example":"Hacer un modelo de la carcasa."}}'::jsonb
