update public.stage_fields f set translations = '{"de":{"question":"Wie willst du diese Etappe angehen?","help":"Die Wahl „Ich schaffe es allein“ überspringt die Suche nach Leuten, den gemeinsamen Test und die Regeln der Zusammenarbeit. Dateien und Fehlliste bleiben.","config":{"options":[{"value":"alone","label":"Ich schaffe es allein"},{"value":"cofounder","label":"Ich suche einen Co-Founder"},{"value":"helpers","label":"Ich suche Leute für Aufgaben, keinen Co-Founder"},{"value":"both","label":"Ich suche einen Co-Founder und Leute für Aufgaben"}]}},"uk":{"question":"Як ти хочеш пройти цей етап?","help":"Вибір «Впораюся сам» пропускає пошук людей, спільну спробу й правила співпраці. Файли та список прогалин залишаються.","config":{"options":[{"value":"alone","label":"Впораюся сам"},{"value":"cofounder","label":"Шукаю co-founder"},{"value":"helpers","label":"Шукаю виконавців, а не co-founder"},{"value":"both","label":"Шукаю co-founder і виконавців"}]}},"es":{"question":"¿Cómo quieres hacer esta etapa?","help":"Elegir «Puedo hacerlo solo» omite buscar gente, la prueba conjunta y las normas de colaboración. Los archivos y la lista de pendientes se mantienen.","config":{"options":[{"value":"alone","label":"Puedo hacerlo solo"},{"value":"cofounder","label":"Busco cofundador"},{"value":"helpers","label":"Busco colaboradores, no cofundador"},{"value":"both","label":"Busco cofundador y colaboradores"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
