    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'scope'
    and s.key = 'mode' and f.key = 'choice';
update public.stage_subpoints s set translations = '{"de":{"title":"Co-Founder-Profil"},"uk":{"title":"Профіль co-founder"},"es":{"title":"Perfil del cofundador"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'scope' and s.key = 'cofounder';
update public.stage_fields f set translations = '{"de":{"question":"Beschreibe, wen du als Co-Founder suchst.","help":"Eine Zeile ist eine Rolle. Du kannst ein eigenes Feld ergänzen, wenn im Profil etwas fehlt.","example":"Verantwortung: erste Version des Programms und Weiterentwicklung nach den Tests. Anteile: 15–25 % zur Verhandlung.","config":{"add_label":"Weitere Rolle hinzufügen","columns":[{"key":"responsibility","label":"Verantwortung","placeholder":"Wofür diese Person verantwortlich ist"},{"key":"equity","label":"Anteilsspanne zur Verhandlung","placeholder":"Z. B. 10–20 %"},{"key":"experience","label":"Erforderliche Erfahrung","placeholder":"Was sie vorweisen können sollte"},{"key":"approach","label":"Arbeitsweise","placeholder":"Welche Zusammenarbeit du erwartest"},{"key":"hours","label":"Freie Stunden und Engagement","placeholder":"Wie viel Zeit sie investieren kann"}]}},"uk":{"question":"Опиши, кого шукаєш як co-founder.","help":"Одна позиція — одна роль. Можеш дописати власне поле, якщо чогось бракує в профілі.","example":"Відповідальність: перша версія програми та її розвиток після тестів. Частки: 15–25% для обговорення.","config":{"add_label":"Додати ще одну роль","columns":[{"key":"responsibility","label":"Відповідальність","placeholder":"За що відповідає ця людина"},{"key":"equity","label":"Діапазон часток для обговорення","placeholder":"Напр. 10–20%"},{"key":"experience","label":"Потрібний досвід","placeholder":"Що вона має вміти показати"},{"key":"approach","label":"Підхід","placeholder":"Якої співпраці ти очікуєш"},{"key":"hours","label":"Вільні години й залученість","placeholder":"Скільки часу вона може приділити"}]}},"es":{"question":"Describe a quién buscas como cofundador.","help":"Una línea es un rol. Puedes añadir un campo propio si falta algo en el perfil.","example":"Responsabilidad: primera versión del programa y su desarrollo tras las pruebas. Participaciones: 15–25 % a negociar.","config":{"add_label":"Añadir otro rol","columns":[{"key":"responsibility","label":"Responsabilidad","placeholder":"De qué es responsable esta persona"},{"key":"equity","label":"Rango de participaciones a negociar","placeholder":"P. ej. 10–20 %"},{"key":"experience","label":"Experiencia requerida","placeholder":"Qué debería poder mostrar"},{"key":"approach","label":"Forma de trabajar","placeholder":"Qué colaboración esperas"},{"key":"hours","label":"Horas disponibles y compromiso","placeholder":"Cuánto tiempo puede dedicar"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'scope'
    and s.key = 'cofounder' and f.key = 'profile';
update public.stage_subpoints s set translations = '{"de":{"title":"Personen für eine konkrete Arbeit"},"uk":{"title":"Люди, потрібні для конкретної роботи"},"es":{"title":"Personas para un trabajo concreto"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'scope' and s.key = 'helpers';
update public.stage_fields f set translations = '{"de":{"question":"Aufgaben, die zu klein für einen Co-Founder sind, die du aber nicht allein erledigst.","help":"Schreib bei jeder Zeile die Fähigkeit dazu und ob du für die Arbeit zahlen kannst.","example":"Druckfertiger Verpackungsentwurf. Ich suche jemanden, der solche Dateien schon vorbereitet hat. Budget: 200 €.","config":{"add_label":"Person hinzufügen","columns":[{"key":"task","label":"Aufgabe","placeholder":"Was entstehen soll"},{"key":"skill","label":"Fähigkeit und Erfahrung","placeholder":"Was du suchst"},{"key":"pay","label":"Kannst du zahlen und wie viel","placeholder":"Z. B. 200 € oder kein Budget"}]}},"uk":{"question":"Завдання, замалі для co-founder, але яких ти не зробиш сам.","help":"Біля кожної позиції напиши вміння і чи можеш заплатити за цю роботу.","example":"Проєкт упаковки, готовий до друкарні. Шукаю когось, хто готував такі файли. Бюджет: 8000 грн.","config":{"add_label":"Додати людину","columns":[{"key":"task","label":"Завдання","placeholder":"Що має з’явитися"},{"key":"skill","label":"Уміння й досвід","placeholder":"Кого шукаєш"},{"key":"pay","label":"Чи можеш заплатити і скільки","placeholder":"Напр. 8000 грн або без бюджету"}]}},"es":{"question":"Tareas demasiado pequeñas para un cofundador que no harás tú solo.","help":"En cada línea indica la habilidad y si puedes pagar por el trabajo.","example":"Diseño de envase listo para imprenta. Busco a alguien que haya preparado archivos así. Presupuesto: 200 €.","config":{"add_label":"Añadir persona","columns":[{"key":"task","label":"Tarea","placeholder":"Qué hay que hacer"},{"key":"skill","label":"Habilidad y experiencia","placeholder":"Qué buscas"},{"key":"pay","label":"¿Puedes pagar y cuánto?","placeholder":"P. ej. 200 € o sin presupuesto"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'scope'
    and s.key = 'helpers' and f.key = 'roles';
update public.stage_points p set translations = '{"de":{"title":"Hol dir Hilfe und erste Kontakte","duration_hint":"Etwa 20 Minuten","guide_body":"Profil und Einladung\nNutze die Informationen aus Punkt 1, um dein Profil und das Projektprofil zu ergänzen. Wer das Profil ansieht, sollte schnell verstehen, was du baust, in welcher Phase du bist und wobei er helfen kann. Wenn du schon eine passende Beschreibung hast, verwende sie wieder.\nZeig, was du selbst einbringst: Kenntnis des Problems, Zugang zu Zielpersonen, eine fertige Skizze oder eine für den Bau nötige Fähigkeit. Ergänze, ob du eine Mitgründerin, jemanden für eine konkrete Aufgabe oder eine kurze Beratung suchst.\nBeispiel: „Ich baue eine Halterung, um Einkäufe mit dem Fahrrad zu transportieren. Ich habe eine Skizze und Erkenntnisse aus Gesprächen mit Radfahrern. Ich suche jemanden, der ein Modell der Befestigung vorbereitet.“\nWenn du schon mit passenden Personen arbeitest, lade sie ins Projekt ein. Weitere zu suchen ergibt Sinn, wenn ein konkreter Bedarf bleibt.\n§\nWen du fragst\nWähle Personen, deren Fähigkeiten zu den notierten Aufgaben passen. Sieh dir ein Beispiel ähnlicher Arbeit an oder bitte um eine kurze Beschreibung dessen, was die Person schon gemacht hat. Du kannst in Vairo, im Bekanntenkreis oder über Empfehlungen suchen.\nSchreib kurz, was du brauchst und welche Bedingungen du anbieten kannst. Beispiel: „Ich suche Hilfe beim Modell einer Fahrradhalterung. Ich habe dein Befestigungsprojekt gesehen. Darf ich dir die Skizze zeigen und nach einer möglichen Zusammenarbeit fragen?“\nErgänze nach der Antwort die Tabellenzeile. Etwas Konkretes reicht: „Hat geantwortet, hat Modelle ähnlicher Teile gemacht, wir haben einen gemeinsamen Test vereinbart.“ Wenn jemand noch nicht geantwortet hat, lass den Kontakt als wartend stehen.\nVergleiche Passung zur Aufgabe, Verfügbarkeit und vereinbarte Bedingungen. Füge Personen zur Zusammenarbeit hinzu, die ihre Teilnahme bestätigt haben. Im nächsten Punkt prüft ihr, wie gut ihr zusammenarbeitet.","guide_sources":["Michael Seibel, One Order of Operations for Starting a Startup (2018): mit Menschen mit ergänzenden Fähigkeiten bauen."]},"uk":{"title":"Здобудь допомогу й перші контакти","duration_hint":"Близько 20 хвилин","guide_body":"Профіль і запрошення\nСкористайся інформацією з пункту 1, щоб доповнити свій профіль і профіль проєкту. Людина, яка переглядає профіль, має швидко зрозуміти, що ти створюєш, на якому ти етапі і чим вона може допомогти. Якщо вже маєш відповідний опис, використай його знову.\nПокажи, що вносиш від себе: знання проблеми, доступ до адресатів, готовий ескіз або вміння, потрібне для створення. Допиши, чи шукаєш співзасновника, виконавця конкретного завдання чи коротку консультацію.\nПриклад: «Я створюю тримач для перевезення покупок велосипедом. Маю ескіз і висновки з розмов із велосипедистами. Шукаю людину, яка допоможе підготувати модель кріплення».\nЯкщо вже працюєш із відповідними людьми, запроси їх до проєкту. Шукати наступних має сенс тоді, коли залишається конкретна потреба.\n§\nКого питати\nОбирай людей, чиї вміння пасують до записаних завдань. Подивися на приклад схожої роботи або попроси короткий опис того, що людина робила раніше. Можеш шукати у Vairo, серед знайомих чи за рекомендацією.\nКоротко напиши, чого потребуєш і які умови можеш запропонувати. Приклад: «Шукаю допомоги з моделлю велосипедного тримача. Бачив(-ла) твій проєкт кріплення. Чи можу показати тобі ескіз і запитати про можливість співпраці?».\nПісля відповіді заповни рядок таблиці. Досить конкретики: «Відповіла, готувала моделі схожих деталей, домовилися про спільну спробу». Коли хтось ще не відповів, залиш контакт як очікуваний.\nПорівняй відповідність завданню, доступність і погоджені умови. До співпраці додавай людей, які підтвердили бажання взяти участь. У наступному пункті ви перевірите, як вам ідеться спільна робота.","guide_sources":["Michael Seibel, One Order of Operations for Starting a Startup (2018): створення разом із людьми з доповнювальними вміннями."]},"es":{"title":"Consigue ayuda y los primeros contactos","duration_hint":"Unos 20 minutos","guide_body":"Perfil e invitación\nUsa la información del punto 1 para completar tu perfil y el del proyecto. Quien vea el perfil debe entender rápido qué estás creando, en qué fase estás y en qué puede ayudar. Si ya tienes una descripción adecuada, reutilízala.\nMuestra lo que aportas: conocimiento del problema, acceso a los destinatarios, un boceto hecho o una habilidad necesaria para construir. Añade si buscas un cofundador, a alguien para una tarea concreta o una consulta breve.\nEjemplo: «Estoy creando un soporte para llevar la compra en bicicleta. Tengo un boceto y conclusiones de conversaciones con ciclistas. Busco a alguien que me ayude a preparar un modelo del anclaje».\nSi ya trabajas con las personas adecuadas, invítalas al proyecto. Buscar a más tiene sentido cuando queda una necesidad concreta.\n§\nA quién preguntar\nElige personas cuyas habilidades encajen con las tareas anotadas. Mira un ejemplo de trabajo parecido o pide una breve descripción de lo que ha hecho antes. Puedes buscar en Vairo, entre conocidos o por recomendación.\nEscribe brevemente qué necesitas y qué condiciones puedes ofrecer. Ejemplo: «Busco ayuda con el modelo de un soporte para bicicleta. He visto tu proyecto de anclaje. ¿Puedo enseñarte el boceto y preguntarte si te interesaría colaborar?».\nCuando te respondan, completa la fila de la tabla. Basta con algo concreto: «Respondió, ha hecho modelos de piezas parecidas, acordamos una prueba conjunta». Si alguien aún no ha respondido, deja el contacto como pendiente.\nCompara el encaje con la tarea, la disponibilidad y las condiciones acordadas. Añade a la colaboración a las personas que hayan confirmado que quieren participar. En el siguiente punto comprobaréis cómo os va trabajando juntos.","guide_sources":["Michael Seibel, One Order of Operations for Starting a Startup (2018): construir con personas de habilidades complementarias."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'find-help';
update public.stage_subpoints s set translations = '{"de":{"title":"Nutze den Social-Bereich"},"uk":{"title":"Скористайся шаром Social"},"es":{"title":"Usa la parte Social"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'find-help' and s.key = 'social';
update public.stage_fields f set translations = '{"de":{"question":"Vervollständige dein Profil und das deines Startups und suche dann Leute im Vairo-Netzwerk.","help":"Dieser Schritt öffnet Social. Hake ihn ab, wenn das Profil fertig ist und du weißt, wen du suchst.","config":{"confirm_label":"Profil ist fertig","label":"Social öffnen"}},"uk":{"question":"Доповни свій профіль і профіль стартапу, а потім шукай людей у мережі Vairo.","help":"Цей крок відкриває Social. Познач його, коли профіль готовий і ти знаєш, кого шукаєш.","config":{"confirm_label":"Профіль готовий","label":"Відкрити Social"}},"es":{"question":"Completa tu perfil y el de tu startup, y después busca gente en la red de Vairo.","help":"Este paso abre Social. Márcalo cuando el perfil esté listo y sepas a quién buscas.","config":{"confirm_label":"El perfil está listo","label":"Abrir Social"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'find-help'
    and s.key = 'social' and f.key = 'opened';
update public.stage_subpoints s set translations = '{"de":{"title":"Notiere, wen du um Hilfe bittest"},"uk":{"title":"Запиши, кого просиш про допомогу"},"es":{"title":"Anota a quién pides ayuda"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'find-help' and s.key = 'outreach';
update public.stage_fields f set translations = '{"de":{"question":"Kontakte: Person oder Firma, ob geantwortet wurde, welche Fähigkeiten sie hat und ob ihr zusammenarbeitet.","help":"Eine Zeile ist ein Gespräch. Wenn jemand noch nicht geantwortet hat, trag „wartet“ ein.","example":"Anna Schmidt. Hat geantwortet. Hat Modelle ähnlicher Teile gemacht. Wir vereinbaren einen gemeinsamen Test.","config":{"add_label":"Kontakt hinzufügen","columns":[{"key":"who","label":"Vor- und Nachname oder Firma"},{"key":"reply","label":"Hat geantwortet?"},{"key":"skills","label":"Fähigkeiten"},{"key":"together","label":"Arbeitet ihr zusammen?"}]}},"uk":{"question":"Контакти: людина чи компанія, чи відповіла, які має вміння і чи співпрацюватимете.","help":"Одна позиція — одна розмова. Коли хтось ще не відписав, впиши «чекає».","example":"Оля Коваленко. Відповіла. Робила моделі схожих деталей. Домовляємося про спільну спробу.","config":{"add_label":"Додати контакт","columns":[{"key":"who","label":"Ім’я та прізвище або компанія"},{"key":"reply","label":"Чи відповіла"},{"key":"skills","label":"Уміння"},{"key":"together","label":"Чи будете співпрацювати"}]}},"es":{"question":"Contactos: persona o empresa, si respondió, qué habilidades tiene y si vais a colaborar.","help":"Una línea es una conversación. Si alguien aún no ha respondido, escribe «pendiente».","example":"Lucía García. Respondió. Ha hecho modelos de piezas parecidas. Estamos acordando una prueba conjunta.","config":{"add_label":"Añadir contacto","columns":[{"key":"who","label":"Nombre y apellidos o empresa"},{"key":"reply","label":"¿Ha respondido?"},{"key":"skills","label":"Habilidades"},{"key":"together","label":"¿Vais a colaborar?"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'find-help'
    and s.key = 'outreach' and f.key = 'contacts';
update public.stage_subpoints s set translations = '{"de":{"title":"Wähle Personen von der Plattform"},"uk":{"title":"Обери людей із платформи"},"es":{"title":"Elige personas de la plataforma"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'find-help' and s.key = 'pick';
update public.stage_fields f set translations = '{"de":{"question":"Markiere die Personen, mit denen du weitermachen willst.","help":"Das sind echte Profile aus Vairo. Die Einladung ins Startup schickst du von der Karte der Person in Social. Das Markieren allein erzeugt keine Mitgliedschaft. Wenn du niemanden wählst, speichere eine leere Liste."},"uk":{"question":"Познач людей, з якими хочеш іти далі.","help":"Це справжні профілі з Vairo. Запрошення до стартапу надсилаєш із картки людини в Social. Сама позначка не створює членства. Якщо нікого не обираєш, збережи порожній список."},"es":{"question":"Marca a las personas con las que quieres seguir.","help":"Son perfiles reales de Vairo. La invitación a la startup la envías desde la tarjeta de la persona en Social. Marcarla no crea la membresía. Si no eliges a nadie, guarda una lista vacía."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'find-help'
    and s.key = 'pick' and f.key = 'people';
update public.stage_points p set translations = '{"de":{"title":"Prüft, ob ihr zusammenarbeiten könnt","duration_hint":"Ein paar Tage","guide_body":"Gemeinsame Aufgabe\nWählt aus Punkt 1 eine Arbeit, deren Ergebnis im Projekt nützlich ist und die sich in ein paar Tagen abschließen lässt. Das kann die Skizze eines Teils sein, ein einfaches Formular oder die Vorbereitung eines Teils des Dienstes, um ihn einer Zielperson zu zeigen.\nLegt vor dem Start fest, was fertig sein soll, wer welche Teile vorbereitet und wann ihr sie zusammenführt. Passt die Arbeit an die Fähigkeiten der Beteiligten an.\nBeispiel: „Anna bereitet das Modell der Befestigung vor, ich liefere die Maße und prüfe die Passung zum Korb. Am Freitag sehen wir uns das Ergebnis gemeinsam an.“\nNotiert nach der Aufgabe das Ergebnis. Beispiel: „Ein Modell der Befestigung ist entstanden. Es passt zum gewählten Korb, aber der Haken muss verbessert werden.“ So eine Notiz zeigt auch, was sich weiter nutzen lässt.\n§\nWie es mit diesem Team weitergeht\nBesprecht, ob das vereinbarte Ergebnis entstanden ist und ob jede Person ihren Teil erledigen konnte. Wenn etwas hängen geblieben ist, klärt den Grund: fehlende Fähigkeiten, Zeit oder nötige Informationen.\nBestätigt, ob ihr weitermachen wollt. Notiert nur die Änderung, die umgesetzt werden muss, zum Beispiel: „Wir machen weiter. Vor dem nächsten Modell übergebe ich zuerst alle Maße.“ Wenn alles passt, reicht „Wir machen in dieser Besetzung weiter“.\nTeambereitschaft bedeutet hier, dass ihr eine vereinbarte Besetzung habt und die weitere Arbeit aufnehmen könnt. Ein gelungener Test gibt erste Informationen über die Zusammenarbeit. Bei einer schwierigeren Aufgabe können weitere Themen auftauchen.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): gemeinsames Probeprojekt.","Michael Seibel, The Scientific Method for Startups (2016): eine Annahme prüfen und aus dem Ergebnis schließen. Die Anwendung auf einen Zusammenarbeitstest ist eine Anpassung."]},"uk":{"title":"Перевірте, чи вмієте працювати разом","duration_hint":"Кілька днів","guide_body":"Спільне завдання\nОберіть із пункту 1 роботу, результат якої знадобиться в проєкті і яку можна завершити за кілька днів. Це може бути ескіз одного елемента, проста форма або підготовка частини послуги для показу адресатові.\nПеред початком домовтеся, що має бути готове, хто підготує окремі частини і коли ви їх поєднаєте. Підберіть роботу до вмінь людей, які беруть у ній участь.\nПриклад: «Оля підготує модель кріплення, а я надам розміри й перевірю сумісність із кошиком. У п’ятницю подивимося на результат разом».\nПісля завдання запишіть результат. Приклад: «Готова модель кріплення. Пасує до обраного кошика, але гачок треба виправити». Такий запис показує також, що можна використати далі.\n§\nЩо далі з цим складом\nОбговоріть, чи з’явився домовлений результат і чи кожна людина змогла виконати свою частину. Якщо щось застрягло, з’ясуйте причину: брак умінь, часу чи потрібної інформації.\nПідтвердьте, чи хочете продовжувати. Запишіть лише зміну, яку треба запровадити, наприклад: «Продовжуємо. Перед наступною моделлю спершу передаю повний набір розмірів». Якщо все пасує, досить «Продовжуємо в цьому складі».\nГотовність команди означає тут, що у вас є погоджений склад і ви можете взятися за подальшу роботу. Одна вдала спроба дає першу інформацію про співпрацю. За складнішого завдання можуть виникнути інші питання.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): спільний пробний проєкт.","Michael Seibel, The Scientific Method for Startups (2016): перевірка припущення й висновок із результату. Застосування до спроби співпраці — адаптація."]},"es":{"title":"Comprobad si sabéis trabajar juntos","duration_hint":"Unos días","guide_body":"Tarea conjunta\nElegid del punto 1 un trabajo cuyo resultado sirva al proyecto y que pueda terminarse en unos días. Puede ser el boceto de una pieza, un formulario sencillo o preparar una parte del servicio para enseñársela a un destinatario.\nAntes de empezar, acordad qué tiene que estar listo, quién preparará cada parte y cuándo las juntaréis. Ajustad el trabajo a las habilidades de quienes participan.\nEjemplo: «Lucía preparará el modelo del anclaje y yo aportaré las medidas y comprobaré que encaja en la cesta. El viernes vemos juntos el resultado».\nTras la tarea, anotad el resultado. Ejemplo: «Tenemos el modelo del anclaje. Encaja en la cesta elegida, pero hay que mejorar el enganche». Una nota así muestra también qué se puede aprovechar después.\n§\nQué hacer con este equipo\nHablad de si se consiguió el resultado acordado y de si cada persona pudo hacer su parte. Si algo se atascó, averiguad el motivo: falta de habilidades, de tiempo o de información necesaria.\nConfirmad si queréis seguir. Anotad solo el cambio que hay que aplicar, por ejemplo: «Seguimos. Antes del próximo modelo, primero paso todas las medidas». Si todo encaja, basta con «Seguimos con este equipo».\nQue el equipo esté listo significa aquí que tenéis una composición acordada y podéis seguir trabajando. Una prueba que sale bien da la primera información sobre la colaboración. Con una tarea más difícil pueden surgir otras cuestiones.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): proyecto conjunto de prueba.","Michael Seibel, The Scientific Method for Startups (2016): comprobar una suposición y sacar una conclusión del resultado. Aplicarlo a una prueba de colaboración es una adaptación."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'trial';
update public.stage_subpoints s set translations = '{"de":{"title":"Wählt eine gemeinsame Aufgabe"},"uk":{"title":"Оберіть спільне завдання"},"es":{"title":"Elegid una tarea conjunta"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'trial' and s.key = 'task';
update public.stage_fields f set translations = '{"de":{"question":"Welche kleine Aufgabe aus der Liste nehmt ihr als Test?","help":"Sie soll verschiedene Fähigkeiten nutzen und höchstens ein paar Tage dauern.","example":"Modell der Befestigung für eine Fahrradhalterung."},"uk":{"question":"Яке невелике завдання зі списку берете на спробу?","help":"Воно має задіяти різні вміння й зайняти щонайбільше кілька днів.","example":"Модель кріплення велосипедного тримача."},"es":{"question":"¿Qué tarea pequeña de la lista tomáis como prueba?","help":"Debe aprovechar habilidades distintas y llevar como mucho unos días.","example":"Modelo del anclaje del soporte para bicicleta."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'task' and f.key = 'which';
update public.stage_fields f set translations = '{"de":{"question":"Was soll entstehen, wer macht welchen Teil und wann seid ihr fertig?","help":"Ein Satz pro Person reicht.","example":"Anna bereitet das Modell vor, ich liefere die Maße. Am Freitag sehen wir uns das Ergebnis an."},"uk":{"question":"Що має з’явитися, хто робить яку частину і коли завершуєте?","help":"Досить одного речення на людину.","example":"Оля підготує модель, я надам розміри. У п’ятницю дивимося результат."},"es":{"question":"¿Qué hay que hacer, quién hace cada parte y cuándo terminais?","help":"Basta una frase por persona.","example":"Lucía prepara el modelo y yo aporto las medidas. El viernes vemos el resultado."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'task' and f.key = 'plan';
update public.stage_subpoints s set translations = '{"de":{"title":"Notiert das Ergebnis des Tests"},"uk":{"title":"Запишіть результат спроби"},"es":{"title":"Anotad el resultado de la prueba"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'trial' and s.key = 'result';
update public.stage_fields f set translations = '{"de":{"question":"Was ist entstanden und wofür könnt ihr es nutzen?","help":"Kurze Beschreibung oder Link. Das Ergebnis bleibt eine normale Antwort in dieser Etappe.","example":"Ein Modell der Befestigung ist entstanden. Es passt zum Korb, aber der Haken muss verbessert werden. Link: …"},"uk":{"question":"Що з’явилося і для чого можете це використати?","help":"Короткий опис або посилання. Результат залишається звичайною відповіддю в цьому етапі.","example":"Готова модель кріплення. Пасує до кошика, але гачок потребує виправлення. Посилання: …"},"es":{"question":"¿Qué ha salido y para qué podéis usarlo?","help":"Una breve descripción o un enlace. El resultado queda como una respuesta normal de esta etapa.","example":"Tenemos el modelo del anclaje. Encaja en la cesta, pero hay que mejorar el enganche. Enlace: …"}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'result' and f.key = 'outcome';
update public.stage_fields f set translations = '{"de":{"question":"Wie geht es mit diesem Team weiter?","help":"Wenn ihr nichts ändert, reicht „Wir machen in dieser Besetzung weiter“. Sonst notiert nur die nötige Änderung.","example":"Wir machen weiter. Vor dem nächsten Modell übergebe ich zuerst alle Maße."},"uk":{"question":"Що далі з цим складом?","help":"Якщо нічого не змінюєте, досить «Продовжуємо в цьому складі». Інакше запишіть лише потрібну зміну.","example":"Продовжуємо. Перед наступною моделлю спершу передаю повний набір розмірів."},"es":{"question":"¿Qué hacéis con este equipo?","help":"Si no cambiáis nada, basta con «Seguimos con este equipo». Si no, anotad solo el cambio necesario.","example":"Seguimos. Antes del próximo modelo, primero paso todas las medidas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'result' and f.key = 'decision';
update public.stage_fields f set translations = '{"de":{"question":"Das Team ist bereit für die weitere Arbeit.","help":"Hake es ab, wenn ihr eine vereinbarte Besetzung habt. Ein Test muss nicht alles lösen.","config":{"confirm_label":"Team bereit"}},"uk":{"question":"Команда готова до подальшої роботи.","help":"Познач, коли у вас є погоджений склад. Одна спроба не мусить розв’язати всього.","config":{"confirm_label":"Команда готова"}},"es":{"question":"El equipo está listo para seguir trabajando.","help":"Márcalo cuando tengáis una composición acordada. Una prueba no tiene que resolverlo todo.","config":{"confirm_label":"Equipo listo"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'trial'
    and s.key = 'result' and f.key = 'ready';
update public.stage_points p set translations = '{"de":{"title":"Richte einen Arbeitsort ein","duration_hint":"Etwa 10 Minuten","guide_body":"Sammle die Materialien\nSammle in den Dateien die aktuellen Materialien, die weiter gebraucht werden: Beschreibung der Idee, nützliche Erkenntnisse aus Gesprächen und Ergebnisse bisheriger Aufgaben. Wähle Dokumente, zu denen du oder das Team zurückkehren werdet.\nBenenne sie so, dass klar ist, was sie enthalten. Beispiele: „Beschreibung der Idee“, „Erkenntnisse aus Gesprächen“, „Modell der Befestigung“. Wenn es mehrere Versionen gibt, kennzeichne die, an der ihr gerade arbeitet.\nTeile die Materialien mit den nötigen Personen und prüfe, ob sie sie öffnen können. Den Unterpunkt kannst du abhaken, wenn die Dokumente gesammelt und für die Personen zugänglich sind, die sie nutzen werden.\n§\nRegeln der Zusammenarbeit\nVereinbart Verfügbarkeit, Kontaktweg, Entscheidungsfindung und Bedingungen der Beteiligung. Nutzt frühere Vereinbarungen, wenn sie noch gelten.\nNotiert kurze, akzeptierte Regeln. Beispiele: „Jede von uns investiert etwa fünf Stunden pro Woche ins Projekt.“ „Informationen zu Aufgaben schicken wir im gemeinsamen Chat.“ „Ausgaben genehmigen wir gemeinsam.“ „Anna erledigt die bezahlte Aufgabe aus dem vereinbarten Angebot.“\nWählt die Einträge, die zu eurer Situation passen. Wenn ein Punkt nicht geklärt ist, markiert ihn als offen. Wer allein arbeitet, überspringt diesen Unterpunkt.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): Verfügbarkeit, Erwartungen und der Umgang mit Meinungsverschiedenheiten."]},"uk":{"title":"Запусти місце для роботи","duration_hint":"Близько 10 хвилин","guide_body":"Збери матеріали\nУ Файлах збери актуальні матеріали, потрібні далі: опис ідеї, корисні висновки з розмов і результати дотеперішніх завдань. Обери документи, до яких ти або команда повертатиметеся.\nНазви їх так, щоб було зрозуміло, що в них. Приклади: «Опис ідеї», «Висновки з розмов», «Модель кріплення». Коли є кілька версій, вкажи ту, над якою зараз працюєте.\nНадай матеріали потрібним людям і перевір, чи вони можуть їх відкрити. Підпункт можна зарахувати, коли документи зібрано й вони доступні людям, які ними користуватимуться.\n§\nПравила співпраці\nДомовтеся про доступність, спосіб контакту, ухвалення рішень і умови участі. Скористайтеся попередніми домовленостями, якщо вони й далі чинні.\nЗаписуйте короткі погоджені правила. Приклади: «Кожен із нас приділяє проєкту близько п’яти годин на тиждень». «Інформацію до завдання надсилаємо в спільному чаті». «Витрати затверджуємо разом». «Оля виконує платне завдання, описане в погодженій пропозиції».\nОберіть записи, що відповідають вашій ситуації. Якщо якесь питання лишається неузгодженим, позначте його як відкрите. При самостійній роботі пропусти цей підпункт.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): доступність, очікування і спосіб розв’язання непорозумінь."]},"es":{"title":"Pon en marcha el espacio de trabajo","duration_hint":"Unos 10 minutos","guide_body":"Reúne los materiales\nReúne en Archivos los materiales actuales que harán falta: la descripción de la idea, las conclusiones útiles de las conversaciones y los resultados de las tareas hechas. Elige los documentos a los que tú o el equipo volveréis.\nNómbralos de forma que se sepa qué contienen. Ejemplos: «Descripción de la idea», «Conclusiones de las conversaciones», «Modelo del anclaje». Si hay varias versiones, señala la que estáis usando ahora.\nComparte los materiales con quien los necesite y comprueba que pueden abrirlos. Puedes dar por hecho el subpunto cuando los documentos estén reunidos y accesibles para quienes los usarán.\n§\nNormas de colaboración\nAcordad disponibilidad, forma de contacto, toma de decisiones y condiciones de participación. Aprovechad acuerdos anteriores si siguen vigentes.\nAnotad normas breves y aceptadas. Ejemplos: «Cada uno dedica unas cinco horas a la semana al proyecto». «La información de cada tarea la enviamos por el chat común». «Los gastos los aprobamos juntos». «Lucía hace la tarea remunerada descrita en la oferta acordada».\nElegid las que encajen con vuestra situación. Si algo queda sin acordar, marcadlo como abierto. Si trabajas en solitario, omite este subpunto.","guide_sources":["Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): disponibilidad, expectativas y forma de resolver desacuerdos."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'workspace';
update public.stage_subpoints s set translations = '{"de":{"title":"Sammle die Materialien in den Dateien"},"uk":{"title":"Збери матеріали у Файлах"},"es":{"title":"Reúne los materiales en Archivos"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'workspace' and s.key = 'files';
update public.stage_fields f set translations = '{"de":{"question":"Lade die aktuellen Projektmaterialien in den Bereich Dateien hoch und teile sie mit den Personen, die sie nutzen werden.","help":"Hake es ab, wenn die Dokumente an einem Ort sind und sich öffnen lassen.","config":{"confirm_label":"Materialien sind gesammelt","label":"Zu den Dateien"}},"uk":{"question":"Завантаж актуальні матеріали проєкту в розділ Файли й надай їх людям, які ними користуватимуться.","help":"Познач, коли документи в одному місці й відкриваються.","config":{"confirm_label":"Матеріали зібрано","label":"Перейти до Файлів"}},"es":{"question":"Sube los materiales actuales del proyecto a Archivos y compártelos con quienes los vayan a usar.","help":"Márcalo cuando los documentos estén en un solo sitio y se puedan abrir.","config":{"confirm_label":"Los materiales están reunidos","label":"Ir a Archivos"}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'workspace'
    and s.key = 'files' and f.key = 'collected';
update public.stage_subpoints s set translations = '{"de":{"title":"Legt die Regeln der Zusammenarbeit fest"},"uk":{"title":"Домовтеся про правила співпраці"},"es":{"title":"Acordad las normas de colaboración"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'workspace' and s.key = 'rules';
update public.stage_fields f set translations = '{"de":{"question":"Akzeptierte Vereinbarungen, eine pro Eintrag.","help":"Verfügbarkeit, Kontaktweg, Entscheidungsfindung und Bedingungen der Beteiligung. Markiere einen ungeklärten Punkt als offen.","example":"Jede von uns investiert etwa fünf Stunden pro Woche ins Projekt.\nAusgaben genehmigen wir gemeinsam."},"uk":{"question":"Погоджені домовленості, по одній у кожному записі.","help":"Доступність, спосіб контакту, ухвалення рішень і умови участі. Неузгоджене питання познач як відкрите.","example":"Кожен із нас приділяє проєкту близько п’яти годин на тиждень.\nВитрати затверджуємо разом."},"es":{"question":"Acuerdos aceptados, uno por entrada.","help":"Disponibilidad, forma de contacto, toma de decisiones y condiciones de participación. Marca como abierto lo que no esté acordado.","example":"Cada uno dedica unas cinco horas a la semana al proyecto.\nLos gastos los aprobamos juntos."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'workspace'
    and s.key = 'rules' and f.key = 'agreements';
update public.stage_points p set translations = '{"de":{"title":"Sammle, was du für den Start brauchst","duration_hint":"Etwa 10 Minuten","guide_body":"Was zum Start fehlt\nSieh dir die ersten Aufgaben an und prüfe, ob dir etwas zu ihrer Erledigung fehlt. Füge nur hinzu, was du jetzt brauchst. Wenn du alles hast, um anzufangen, ergänze keine Einträge, nur um die Liste zu füllen.\nPrüfe bei einer fehlenden Sache, wie du sie bekommst. Du kannst Material kaufen, Ausrüstung leihen, eine Werkstatt nutzen oder ein Werkzeug verwenden, das jemand im Team schon hat. Trag eine konkrete Quelle ein, wenn du sie kennst.\nEs geht darum, die Dinge mit dem verfügbaren Budget zu bekommen. Kostenloser Zugang oder Leihen können die Startausgaben senken.\nBei den Kosten reicht ein ungefährer Betrag. Ergänze, ob du einmal, monatlich oder pro Nutzung zahlst. Einen unbekannten Preis trägst du als „zu prüfen“ ein. „Kostenlos“ schreibst du, wenn schon feststeht, dass keine Gebühr anfällt.\nBeispiel: Druck des ersten Befestigungsmodells. Werkstatt der Hochschule, nach Absprache über den Zugang. Etwa 15 € für das Material eines Drucks, Betrag noch zu bestätigen.","guide_sources":["Dominika Blackappl, Practical Design: MVP Spec (2016): die erste Version an Machbarkeit und Kosten anpassen.","Michael Seibel, How to Plan an MVP (Startup School, 2019): einfache Mittel für den Start."]},"uk":{"title":"Збери речі, потрібні на старт","duration_hint":"Близько 10 хвилин","guide_body":"Чого бракує на старт\nПоглянь на перші завдання й перевір, чи бракує чогось для їх виконання. Додавай лише те, що зараз потрібно. Якщо маєш усе, щоб почати, не дописуй позицій лише для заповнення списку.\nДля відсутньої речі перевір спосіб її здобути. Можна купити матеріал, позичити обладнання, скористатися майстернею або інструментом, який уже має хтось із команди. Впиши конкретне джерело, якщо його знаєш.\nІдеться про те, щоб здобути речі в межах доступного бюджету. Безплатний доступ або позика можуть зменшити витрати на старт.\nДля вартості досить орієнтовної суми. Допиши, чи платиш раз, щомісяця чи за використання. Невідому ціну впиши як «перевірити». «Безплатно» пиши тоді, коли вже відомо, що оплати не буде.\nПриклад: друк першої моделі кріплення. Майстерня університету, після погодження доступу. Близько 600 грн за матеріал на один друк, суму треба підтвердити.","guide_sources":["Dominika Blackappl, Practical Design: MVP Spec (2016): пристосування першої версії до можливостей виконання й витрат.","Michael Seibel, How to Plan an MVP (Startup School, 2019): прості засоби на старт."]},"es":{"title":"Reúne lo que necesitas para empezar","duration_hint":"Unos 10 minutos","guide_body":"Qué falta para empezar\nMira las primeras tareas y comprueba si te falta algo para hacerlas. Añade solo lo que necesites ahora. Si tienes todo lo necesario para empezar, no añadas elementos solo por rellenar la lista.\nEn cada cosa que falte, mira cómo conseguirla. Puedes comprar material, pedir prestado un equipo, usar un taller o una herramienta que ya tenga alguien del equipo. Escribe una fuente concreta si la conoces.\nSe trata de conseguir las cosas con el presupuesto disponible. El acceso gratuito o el préstamo pueden reducir el gasto inicial.\nPara el coste basta una cifra aproximada. Añade si pagas una vez, cada mes o por uso. Si no sabes el precio, escribe «por comprobar». Escribe «gratis» cuando ya se sepa que no habrá pago.\nEjemplo: impresión del primer modelo del anclaje. Taller de la universidad, tras acordar el acceso. Unos 15 € de material por impresión, cifra por confirmar.","guide_sources":["Dominika Blackappl, Practical Design: MVP Spec (2016): ajustar la primera versión a lo que se puede hacer y a los costes.","Michael Seibel, How to Plan an MVP (Startup School, 2019): medios sencillos para empezar."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'supplies';
update public.stage_subpoints s set translations = '{"de":{"title":"Was fehlt, um anzufangen?"},"uk":{"title":"Чого бракує, щоб почати?"},"es":{"title":"¿Qué falta para empezar?"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'general' and p.key = 'supplies' and s.key = 'missing';
update public.stage_fields f set translations = '{"de":{"question":"Füge nur fehlende Dinge hinzu.","help":"Name, woher du es bekommst und ungefähre Kosten. Eine leere Liste bedeutet, dass du mit dem beginnen kannst, was du schon hast.","example":"Druck des ersten Modells. Werkstatt der Hochschule. Etwa 15 € für das Material.","config":{"add_label":"Ding hinzufügen","columns":[{"key":"thing","label":"Benötigtes Ding","placeholder":"Name, du kannst einen Link ergänzen"},{"key":"source","label":"Woher du es bekommst","placeholder":"Kaufe ich, leihe ich, haben wir im Team"},{"key":"cost","label":"Kosten","placeholder":"Z. B. 50 € einmalig oder kostenlos"}]}},"uk":{"question":"Додай лише те, чого бракує.","help":"Назва, звідки візьмеш і орієнтовна вартість. Порожній список означає, що можна почати з того, що вже є.","example":"Друк першої моделі. Майстерня університету. Близько 600 грн за матеріал.","config":{"add_label":"Додати річ","columns":[{"key":"thing","label":"Потрібна річ","placeholder":"Назва, можна додати посилання"},{"key":"source","label":"Звідки візьмеш","placeholder":"Куплю, позичу, є в команді"},{"key":"cost","label":"Вартість","placeholder":"Напр. 2000 грн одноразово або безплатно"}]}},"es":{"question":"Añade solo lo que falta.","help":"Nombre, de dónde lo sacarás y coste aproximado. Una lista vacía significa que puedes empezar con lo que ya tienes.","example":"Impresión del primer modelo. Taller de la universidad. Unos 15 € de material.","config":{"add_label":"Añadir elemento","columns":[{"key":"thing","label":"Lo que hace falta","placeholder":"Nombre; puedes añadir un enlace"},{"key":"source","label":"De dónde lo sacarás","placeholder":"Lo compro, lo pido prestado, lo tiene el equipo"},{"key":"cost","label":"Coste","placeholder":"P. ej. 50 € una vez o gratis"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'general' and p.key = 'supplies'
    and s.key = 'missing' and f.key = 'items';
update public.stage_categories c set translations = '{"de":{"title":"SaaS","intro":"Ergänze die Zugriffsregeln, die Kosten der ersten Tests und — wenn die erste Version kostenpflichtig ist — was nach der Zahlung mit dem Konto passiert."},"uk":{"title":"SaaS","intro":"Допиши правила доступу, вартість перших тестів і — якщо перша версія платна — що відбувається з акаунтом після оплати."},"es":{"title":"SaaS","intro":"Añade las reglas de acceso, el coste de las primeras pruebas y, si la primera versión es de pago, qué pasa con la cuenta tras el pago."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'preparation' and t.version = 1 and c.key = 'saas';
update public.stage_points p set translations = '{"de":{"title":"Lege fest, wer worauf Zugriff hat","duration_hint":"Etwa 15 Minuten","guide_body":"Wem die Daten gehören\nStell dir vor, zwei verschiedene Kunden nutzen das Programm. Lege fest, welche Materialien jedem von ihnen gehören und ob sie etwas gemeinsam nutzen.\nIn einem Programm für private Notizen kann jede Person eigene Materialien haben. In einem Programm für Firmen können Beschäftigte einen gemeinsamen Bereich ihrer Firma nutzen. Jede Person kann sich dabei mit einem eigenen Konto anmelden.\nBeispiel: „Jede Firma hat einen eigenen Bereich mit Dokumenten. Ihre Beschäftigten nutzen individuelle Konten. Die Dokumente einer Firma sind für andere Firmen nicht zugänglich.“\n§\nWas jede Rolle darf\nLege fest, was die einzelnen Personen tun dürfen. Es reicht anzugeben, welche Materialien sie sehen, ändern und löschen dürfen und ob sie andere einladen können.\nBeispiel: Die Inhaberin des Bereichs kann die Dokumente der Firma sehen, ändern und löschen sowie Beschäftigte einladen und ihnen den Zugriff entziehen. Ein Mitarbeiter kann freigegebene Dokumente sehen und ändern, verwaltet aber nicht den Zugriff anderer.\nFüge nur die Nutzerarten hinzu, die du in der ersten Version brauchst. Wenn jede Person nur eigene Materialien nutzt und alle die gleichen Möglichkeiten haben, reicht ein Eintrag.\nBesprich die Notiz mit der Person, die das Programm baut. Ihr solltet die Frage beantworten können: „Darf diese Person dieses Dokument sehen oder ändern?“ Die Umsetzung dieser Regeln im Programm und die Prüfung der Sicherheit erfolgen beim Bau.","guide_sources":["Microsoft, Tenancy models for a multitenant solution: Aufteilung in Kunden, Nutzer und ihre Daten.","Alex Kracov, The First 90 Days of Building a SaaS Startup: die Funktionsweise des Produkts mit den Menschen abstimmen, die es bauen."]},"uk":{"title":"Визнач, хто має доступ до чого","duration_hint":"Близько 15 хвилин","guide_body":"Чиї дані\nУяви, що програмою користуються двоє різних клієнтів. Визнач, які матеріали належать кожному з них і чи мають вони щось спільне.\nУ програмі для приватних нотаток кожна людина може мати власні матеріали. У програмі для компаній працівники можуть користуватися спільним простором своєї компанії. Кожен працівник може при цьому входити через власний акаунт.\nПриклад: «Кожна компанія має власний простір із документами. Її працівники користуються індивідуальними акаунтами. Документи однієї компанії недоступні іншим компаніям».\n§\nЩо може кожна роль\nВизнач, що можуть робити окремі люди. Досить вказати, які матеріали вони можуть бачити, змінювати й видаляти і чи можуть запрошувати інших.\nПриклад: власник простору може бачити, змінювати й видаляти документи компанії, а також запрошувати працівників і забирати в них доступ. Співробітник може бачити й змінювати надані документи, але не керує доступом інших людей.\nДодавай лише ті типи користувачів, які потрібні в першій версії. Якщо кожен користується лише власними матеріалами і всі мають однакові можливості, досить одного запису.\nОбговори запис із людиною, яка створює програму. Ви маєте вміти відповісти на запитання: «Чи може ця людина побачити або змінити цей документ?». Запровадження цих правил у програмі й перевірка захисту відбудуться під час створення.","guide_sources":["Microsoft, Tenancy models for a multitenant solution: поділ на клієнтів, користувачів і їхні дані.","Alex Kracov, The First 90 Days of Building a SaaS Startup: узгодження того, як працює продукт, із людьми, які його створюють."]},"es":{"title":"Define quién tiene acceso a qué","duration_hint":"Unos 15 minutos","guide_body":"De quién son los datos\nImagina que dos clientes distintos usan el programa. Determina qué materiales pertenecen a cada uno y si deben compartir algo.\nEn un programa de notas personales, cada persona puede tener sus propios materiales. En un programa para empresas, los empleados pueden usar un espacio común de su empresa. Cada empleado puede entrar con su propia cuenta.\nEjemplo: «Cada empresa tiene su propio espacio con documentos. Sus empleados usan cuentas individuales. Los documentos de una empresa no son accesibles para las demás».\n§\nQué puede hacer cada rol\nDetermina qué puede hacer cada persona. Basta con indicar qué materiales pueden ver, cambiar y borrar y si pueden invitar a otros.\nEjemplo: el propietario del espacio puede ver, cambiar y borrar los documentos de la empresa, además de invitar a empleados y quitarles el acceso. Un colaborador puede ver y cambiar los documentos compartidos, pero no gestiona el acceso de otras personas.\nAñade solo los tipos de usuario que necesites en la primera versión. Si cada uno usa solo sus propios materiales y todos pueden hacer lo mismo, basta con una entrada.\nRevisa la nota con quien construye el programa. Deberíais poder responder a la pregunta: «¿Puede esta persona ver o cambiar este documento?». Aplicar estas reglas en el programa y comprobar la seguridad se hará durante la construcción.","guide_sources":["Microsoft, Tenancy models for a multitenant solution: división en clientes, usuarios y sus datos.","Alex Kracov, The First 90 Days of Building a SaaS Startup: acordar cómo funciona el producto con quienes lo construyen."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'access';
update public.stage_subpoints s set translations = '{"de":{"title":"Wem die Daten gehören"},"uk":{"title":"Чиї дані"},"es":{"title":"De quién son los datos"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'access' and s.key = 'space';
update public.stage_fields f set translations = '{"de":{"question":"Haben Nutzer eigene Daten oder teilen sie einen Bereich, etwa einer Firma oder eines Teams?","help":"Notiere die gewählte Variante in einem konkreten Satz.","example":"Jede Firma hat eigene Dokumente. Beschäftigte melden sich mit eigenen Konten an. Firma A sieht die Dokumente von Firma B nicht."},"uk":{"question":"Чи користувачі мають окремі дані, чи ділять простір, наприклад компанії або команди?","help":"Запиши обраний спосіб одним конкретним реченням.","example":"Кожна компанія має власні документи. Працівники входять через власні акаунти. Компанія A не бачить документів компанії B."},"es":{"question":"¿Los usuarios tienen datos separados o comparten un espacio, por ejemplo de una empresa o un equipo?","help":"Anota la opción elegida en una frase concreta.","example":"Cada empresa tiene sus documentos. Los empleados entran con sus propias cuentas. La empresa A no ve los documentos de la empresa B."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'access'
    and s.key = 'space' and f.key = 'model';
update public.stage_subpoints s set translations = '{"de":{"title":"Was jede Rolle darf"},"uk":{"title":"Що може кожна роль"},"es":{"title":"Qué puede hacer cada rol"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'access' and s.key = 'roles';
update public.stage_fields f set translations = '{"de":{"question":"Notiere die Berechtigungen jeder Nutzerart.","help":"Eine Zeile ist eine Rolle. Wenn alle das Gleiche dürfen, reicht ein Eintrag.","example":"Die Inhaberin sieht, ändert und löscht die Dokumente der Firma und lädt Leute ein. Ein Mitarbeiter sieht und ändert freigegebene Dokumente, verwaltet aber keinen Zugriff.","config":{"add_label":"Rolle hinzufügen","columns":[{"key":"role","label":"Rolle","placeholder":"Z. B. Inhaberin des Bereichs"},{"key":"see","label":"Was sie sehen darf","placeholder":"Z. B. Dokumente der eigenen Firma"},{"key":"change","label":"Was sie ändern oder löschen darf","placeholder":"Z. B. eigene Dokumente, keine fremden"},{"key":"invite","label":"Darf sie andere einladen","placeholder":"Ja, nein oder nur zum Lesen"}]}},"uk":{"question":"Запиши повноваження кожного типу користувача.","help":"Одна позиція — одна роль. Якщо всі можуть те саме, досить одного запису.","example":"Власник бачить, змінює й видаляє документи компанії та запрошує людей. Співробітник бачить і змінює надані документи, але не керує доступом.","config":{"add_label":"Додати роль","columns":[{"key":"role","label":"Роль","placeholder":"Напр. власник простору"},{"key":"see","label":"Що може бачити","placeholder":"Напр. документи своєї компанії"},{"key":"change","label":"Що може змінити чи видалити","placeholder":"Напр. власні документи, не чужі"},{"key":"invite","label":"Чи може запрошувати інших","placeholder":"Так, ні або лише для перегляду"}]}},"es":{"question":"Anota los permisos de cada tipo de usuario.","help":"Una línea es un rol. Si todos pueden lo mismo, basta con una entrada.","example":"El propietario ve, cambia y borra los documentos de la empresa e invita a gente. Un colaborador ve y cambia los documentos compartidos, pero no gestiona el acceso.","config":{"add_label":"Añadir rol","columns":[{"key":"role","label":"Rol","placeholder":"P. ej. propietario del espacio"},{"key":"see","label":"Qué puede ver","placeholder":"P. ej. documentos de su empresa"},{"key":"change","label":"Qué puede cambiar o borrar","placeholder":"P. ej. sus propios documentos, no los de otros"},{"key":"invite","label":"¿Puede invitar a otros?","placeholder":"Sí, no o solo de lectura"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'access'
    and s.key = 'roles' and f.key = 'permissions';
update public.stage_points p set translations = '{"de":{"title":"Prüfe, was die ersten Tests kosten","duration_hint":"Etwa 20 Minuten","guide_body":"Berechne die Kosten der Tests\nBeginne mit der Zahl der Personen, die du zu Tests einladen willst. Schätze auch, wie viel sie das Programm nutzen werden. Am Anfang ist das eine Näherung, die du nach den ersten Tests korrigierst.\nDie Zahl der Konten allein reicht womöglich nicht. In einem Programm, das Aufnahmen verarbeitet, zählt ihre Länge. In einem Programm, das Dateien speichert, zählt auch der belegte Speicherplatz.\nBeispiel: „Wir laden 10 Testpersonen ein. Jede verarbeitet etwa 5 Stunden Aufnahmen pro Monat. Zusammen sind das 50 Stunden, also 3000 Minuten Aufnahmen.“\nNutze die im allgemeinen Teil notierten Beträge und prüfe fehlende Preise. Die frühere Liste umfasste vielleicht nur Dinge für den Start. Hier interessieren dich die Kosten der Dienste, die das Programm während der Tests braucht.\nTrenne Fixgebühr und nutzungsabhängige Gebühr. Eine Fixgebühr ist ein fester Betrag pro Zeitraum, zum Beispiel ein Monat Serverbetrieb. Eine nutzungsabhängige Gebühr hängt von der genutzten Menge ab, zum Beispiel von Minuten Aufnahme oder Datenmenge. Ein Dienst kann beide Arten von Gebühren haben.\nBeispiel mit ausgedachten Beträgen: Server 15 € pro Monat, Verarbeitung von Aufnahmen 0,01 € pro Minute. Bei 3000 Minuten kostet die Verarbeitung 30 €. Zusammen etwa 45 € pro Monat.\nNotiere den Betrag und die Annahmen, aus denen er sich ergibt. Wenn du etwas noch nicht weißt, markiere es als „zu prüfen“. Unbekannte Kosten trägst du nicht als null ein.\n§\nLimit und Budget\nPrüfe, was der Anbieter bei Überschreitung eines Limits tut: Er berechnet einen Aufschlag, stoppt den Betrieb oder verlangt den Wechsel in ein teureres Paket. Achte darauf, ob das Limit für das ganze Programm oder pro Nutzer gilt.\nVergleiche die geschätzten Kosten mit dem Betrag, den du für Tests ausgeben kannst. Berücksichtige deine eigenen Tests des Programms und eine stärkere Nutzung als ursprünglich angenommen.\nWenn die Kosten zu hoch sind, begrenze, was sie erhöht: die Zahl der Testpersonen, die Länge der verarbeiteten Aufnahmen oder die Menge gespeicherter Dateien.\nBeispiel: „Für den Anfang laden wir 10 Personen ein. Jede kann bis zu 5 Stunden Aufnahmen pro Monat verarbeiten. Nach Ausschöpfen des Limits warten weitere Aufnahmen bis zum nächsten Monat.“\nStimme mit der Person, die das Programm baut, ab, wie dieses Limit funktionieren soll. Das bloße Notieren in Vairo stoppt die Abrechnung durch den Anbieter nicht.\nWenn eine zusätzliche Begrenzung unnötig ist, reicht eine kurze Begründung, zum Beispiel: „Das gewählte Paket hat einen Festpreis und blockiert Uploads, sobald der verfügbare Speicher belegt ist, ohne automatische Aufschläge.“","guide_sources":["Stripe, How to start a SaaS business: Kosten für Infrastruktur und Dienste.","Microsoft, Pricing models for a multitenant solution: Kosten an die Nutzung koppeln und die Bedeutung von Limits.","Userpilot, How to build a product launch plan for SaaS: Start mit einer begrenzten Gruppe und kleinem Umfang."]},"uk":{"title":"Перевір, скільки коштуватимуть перші тести","duration_hint":"Близько 20 хвилин","guide_body":"Порахуй вартість тестів\nПочни з кількості людей, яких хочеш запросити до тестів. Оціни також, скільки вони користуватимуться програмою. На початку це буде наближення, яке виправиш після перших тестів.\nСамої кількості акаунтів може не вистачити. У програмі, що обробляє записи, має значення їхня тривалість. У програмі, що зберігає файли, важить також зайняте місце.\nПриклад: «Запрошуємо 10 тестувальників. Кожен оброблятиме близько 5 годин записів на місяць. Разом це 50 годин, тобто 3000 хвилин записів».\nСкористайся сумами, записаними в загальній частині, і перевір відсутні ціни. Попередній список міг охоплювати лише речі на старт. Тут тебе цікавить вартість послуг, потрібних для роботи програми під час тестів.\nРозділи фіксовану оплату й оплату за використання. Фіксована оплата — це певна сума за період, наприклад місяць утримання програми на сервері. Оплата за використання залежить від використаного обсягу, наприклад хвилин запису чи обсягу даних. Одна послуга може мати обидва види оплат.\nПриклад із вигаданими сумами: сервер 600 грн на місяць, обробка записів 0,4 грн за хвилину. За 3000 хвилин обробка коштує 1200 грн. Разом близько 1800 грн на місяць.\nЗапиши суму й припущення, з яких вона випливає. Якщо чогось ще не знаєш, познач як «перевірити». Невідому вартість не вписуй як нуль.\n§\nЛіміт і бюджет\nПеревір, що зробить постачальник після перевищення ліміту: нарахує доплату, зупинить роботу чи вимагатиме переходу на дорожчий пакет. Зверни увагу, чи ліміт стосується всієї програми чи окремого користувача.\nПорівняй оцінену вартість із сумою, яку можеш виділити на тести. Врахуй власну перевірку програми й можливість більшого використання, ніж спершу припускаєш.\nЯкщо вартість зависока, обмеж те, що її збільшує: кількість тестувальників, тривалість оброблюваних записів або обсяг збережених файлів.\nПриклад: «На початок запрошуємо 10 людей. Кожна може обробити до 5 годин записів на місяць. Після вичерпання ліміту наступні записи чекають до наступного місяця».\nДомовся з людиною, яка створює програму, як працюватиме такий ліміт. Сам запис у Vairo не зупинить нарахування оплат постачальником.\nЯкщо додаткове обмеження зайве, досить короткого обґрунтування, наприклад: «Обраний пакет має фіксовану ціну і блокує завантаження файлів після вичерпання доступного місця, без автоматичних доплат».","guide_sources":["Stripe, How to start a SaaS business: витрати на інфраструктуру й послуги.","Microsoft, Pricing models for a multitenant solution: зв’язок витрат із використанням і значення лімітів.","Userpilot, How to build a product launch plan for SaaS: старт з обмеженої групи й невеликого обсягу."]},"es":{"title":"Comprueba cuánto costarán las primeras pruebas","duration_hint":"Unos 20 minutos","guide_body":"Calcula el coste de las pruebas\nEmpieza por el número de personas que quieres invitar a las pruebas. Estima también cuánto usarán el programa. Al principio será una aproximación que corregirás tras las primeras pruebas.\nEl número de cuentas puede no bastar. En un programa que procesa grabaciones importa su duración. En uno que guarda archivos cuenta también el espacio ocupado.\nEjemplo: «Invitamos a 10 testers. Cada uno procesará unas 5 horas de grabaciones al mes. En total, 50 horas, es decir, 3000 minutos de grabaciones».\nUsa las cifras anotadas en la parte general y comprueba los precios que faltan. La lista anterior quizá solo incluía lo necesario para empezar. Aquí te interesan los costes de los servicios necesarios para que el programa funcione durante las pruebas.\nSepara la tarifa fija de la tarifa por uso. La tarifa fija es una cantidad determinada por periodo, por ejemplo un mes de servidor. La tarifa por uso depende de la cantidad utilizada, por ejemplo minutos de grabación o volumen de datos. Un mismo servicio puede tener ambos tipos.\nEjemplo con cifras inventadas: servidor 15 € al mes, procesamiento de grabaciones 0,01 € por minuto. Con 3000 minutos, el procesamiento cuesta 30 €. En total, unos 45 € al mes.\nAnota la cifra y las suposiciones de las que sale. Si aún no sabes algo, márcalo como «por comprobar». No escribas cero en un coste desconocido.\n§\nLímite y presupuesto\nComprueba qué hará el proveedor al superar el límite: cobrar un recargo, detener el servicio o exigir pasar a un plan más caro. Fíjate en si el límite es para todo el programa o por usuario.\nCompara el coste estimado con la cantidad que puedes destinar a las pruebas. Ten en cuenta tus propias comprobaciones del programa y la posibilidad de un uso mayor del previsto.\nSi el coste es demasiado alto, limita lo que lo aumenta: el número de testers, la duración de las grabaciones procesadas o la cantidad de archivos guardados.\nEjemplo: «Para empezar invitamos a 10 personas. Cada una puede procesar hasta 5 horas de grabaciones al mes. Agotado el límite, las siguientes grabaciones esperan al mes siguiente».\nAcuerda con quien construye el programa cómo funcionará ese límite. Anotarlo en Vairo no detiene los cobros del proveedor.\nSi no hace falta un límite adicional, basta una justificación breve, por ejemplo: «El plan elegido tiene precio fijo y bloquea la subida de archivos al agotar el espacio, sin recargos automáticos».","guide_sources":["Stripe, How to start a SaaS business: costes de infraestructura y servicios.","Microsoft, Pricing models for a multitenant solution: vincular costes al uso e importancia de los límites.","Userpilot, How to build a product launch plan for SaaS: empezar con un grupo limitado y un alcance pequeño."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'test-cost';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie viele Testpersonen und wie viel sie verbrauchen"},"uk":{"title":"Скільки тестувальників і скільки вони використають"},"es":{"title":"Cuántos testers y cuánto consumirán"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'test-cost' and s.key = 'usage';
update public.stage_fields f set translations = '{"de":{"question":"Wie viele Testpersonen lädst du ein und wie viel verbraucht jede?","help":"Nenne die Zahl der Personen und die Einheit, die wirklich Kosten verursacht: Zeit, Speicherplatz oder Zahl der Vorgänge.","example":"10 Personen, jede verarbeitet etwa 5 Stunden Aufnahmen pro Monat. Zusammen 50 Stunden."},"uk":{"question":"Скільки тестувальників запросиш і скільки кожен використає?","help":"Вкажи кількість людей і одиницю, яка справді породжує витрати: час, місце або кількість операцій.","example":"10 людей, кожна обробить близько 5 годин записів на місяць. Разом 50 годин."},"es":{"question":"¿Cuántos testers invitarás y cuánto consumirá cada uno?","help":"Indica el número de personas y la unidad que de verdad genera coste: tiempo, espacio o número de operaciones.","example":"10 personas; cada una procesará unas 5 horas de grabaciones al mes. En total, 50 horas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'test-cost'
    and s.key = 'usage' and f.key = 'plan';
update public.stage_fields f set translations = '{"de":{"question":"Wie hoch sind die geschätzten monatlichen Kosten der Dienste für diese Gruppe?","help":"Geh von den Preisen aus der Fehlliste im Allgemeinen Teil aus. Rechne Fixgebühr und nutzungsabhängige Gebühr dazu. Bei unbekanntem Preis schreib „zu prüfen“, nicht null.","example":"Server 15 € pro Monat plus 0,01 € pro Minute Aufnahme. Bei 3000 Minuten ergibt das etwa 45 € pro Monat."},"uk":{"question":"Яка орієнтовна місячна вартість послуг для цієї групи?","help":"Відштовхуйся від цін зі списку прогалин у Загальному. Додай фіксовану оплату й оплату за використання. За невідомої ціни напиши «перевірити», а не нуль.","example":"Сервер 600 грн на місяць плюс 0,4 грн за хвилину запису. За 3000 хвилин виходить близько 1800 грн на місяць."},"es":{"question":"¿Cuál es el coste mensual estimado de los servicios para este grupo?","help":"Parte de los precios de la lista de pendientes de General. Suma la tarifa fija y la tarifa por uso. Si no conoces un precio, escribe «por comprobar», no cero.","example":"Servidor 15 € al mes más 0,01 € por minuto de grabación. Con 3000 minutos salen unos 45 € al mes."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'test-cost'
    and s.key = 'usage' and f.key = 'monthly';
update public.stage_subpoints s set translations = '{"de":{"title":"Was nach Überschreiten des Limits passiert"},"uk":{"title":"Що після перевищення ліміту"},"es":{"title":"Qué pasa al superar el límite"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'test-cost' and s.key = 'limits';
update public.stage_fields f set translations = '{"de":{"question":"Was passiert, wenn die Limits der gewählten Dienste überschritten werden?","help":"Schreib bei jedem Dienst: Aufschlag, Betriebsstopp oder nötiger Paketwechsel. Vermerke, ob das Limit für das ganze Programm oder pro Nutzer gilt.","example":"Ist der Speicher voll, blockiert der Anbieter neue Dateien und berechnet keinen Aufschlag.\nVerarbeitung von Aufnahmen über das Paket hinaus kostet mehr pro Minute."},"uk":{"question":"Що станеться після перевищення лімітів обраних послуг?","help":"Біля кожної послуги напиши: доплата, зупинка роботи або потреба змінити пакет. Познач, чи ліміт на всю програму, чи на одного користувача.","example":"Після вичерпання місця постачальник блокує нові файли й не нараховує доплати.\nОбробка записів понад пакет коштує дорожче за хвилину."},"es":{"question":"¿Qué pasará al superar los límites de los servicios elegidos?","help":"En cada servicio escribe: recargo, detención del servicio o cambio obligado de plan. Indica si el límite es para todo el programa o por usuario.","example":"Agotado el espacio, el proveedor bloquea nuevos archivos y no cobra recargo.\nProcesar grabaciones por encima del plan cuesta más por minuto."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'test-cost'
    and s.key = 'limits' and f.key = 'overage';
update public.stage_fields f set translations = '{"de":{"question":"Welches Limit legst du für die Tests fest, um im Budget zu bleiben?","help":"Zahl der Testpersonen, Stunden oder Speicherplatz. Wenn ein zusätzliches Limit unnötig ist, schreib kurz warum.","example":"10 Personen, bis zu 5 Stunden Aufnahmen pro Person und Monat. Nach dem Limit warten weitere Aufnahmen bis zum nächsten Monat."},"uk":{"question":"Який ліміт накладаєш на тести, щоб умістися в бюджет?","help":"Кількість тестувальників, години або місце. Якщо додатковий ліміт зайвий, коротко напиши чому.","example":"10 людей, до 5 годин записів на людину щомісяця. Після ліміту наступні записи чекають до наступного місяця."},"es":{"question":"¿Qué límite pones a las pruebas para no salirte del presupuesto?","help":"Número de testers, horas o espacio. Si no hace falta un límite adicional, explica brevemente por qué.","example":"10 personas, hasta 5 horas de grabaciones al mes por persona. Superado el límite, las siguientes esperan al mes siguiente."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'test-cost'
    and s.key = 'limits' and f.key = 'cap';
update public.stage_points p set translations = '{"de":{"title":"Lege die Regeln für den kostenpflichtigen Zugang fest","duration_hint":"Etwa 15 Minuten","guide_body":"Wie Kunden zahlen und Zugang bekommen\nNutze die in der Idea Stage gewählte Abrechnungsart. Lege fest, wie die erste Person zahlt und was passieren muss, damit sie die bezahlte Version nutzen kann.\nBei einem einfachen Angebot kannst du einen fertigen Zahlungslink verwenden. Wenn du anfangs nur wenige Personen betreust, kannst du den Zugang von Hand freischalten, nachdem du die Zahlung im Dashboard des Zahlungsanbieters geprüft hast.\nBeispiel: „Kunden zahlen über den Link zum gewählten Angebot. Nach Bestätigung der Zahlung im Dashboard des Zahlungsanbieters schalten wir das Konto frei und teilen mit, dass die Nutzung beginnen kann.“\nVereinbare bei manueller Abwicklung, wer Zahlungen prüft und wie lange Kunden auf den Zugang warten. Außerdem müssen Folgezahlungen und das Ende des bezahlten Zeitraums im Blick behalten werden.\nWenn der Zugang automatisch freigeschaltet werden soll, muss die Person, die das Programm baut, es mit den Informationen des Zahlungsanbieters verbinden. Ein Zahlungslink allein bedeutet nicht, dass das Konto automatisch freigeschaltet wird.\nBei nutzungsabhängiger Abrechnung legst du außerdem fest, woher ihr die Information über die genutzte Menge bekommt, etwa die Zahl erledigter Aufgaben.\n§\nWas in typischen Situationen passiert\nGeh die Situationen aus der Aufgabe durch. Notiere bei jeder, was Nutzer tun können und ab wann sich ihre Möglichkeiten ändern.\nBeginne mit einer erfolgreichen Zahlung. Lege fest, wann Kunden Zugang bekommen und für wie lange. Wenn du einen kostenlosen Test anbietest, entscheide, was nach seinem Ende passiert: welche Möglichkeiten bleiben und was Nutzer tun müssen, um weiterzumachen. Gibt es keinen solchen Test, trag „Entfällt“ ein.\nUnterscheide bei einer fehlgeschlagenen Zahlung zwischen Erstkauf und Verlängerung. Wer gerade ein Konto anlegt, ist in einer anderen Lage als jemand, der das Programm seit Monaten nutzt und plötzlich ein Problem mit der Karte hat. Lege fest, ob Bestandskunden zusätzliche Zeit bekommen und wann die Nutzung eingeschränkt wird.\nBetrachte die Kündigung der Verlängerung gesondert. Notiere, bis wann Kunden die bereits bezahlten Möglichkeiten nutzen können und wann keine weiteren Gebühren mehr abgebucht werden. Lege dann fest, was nach Ende des bezahlten Zeitraums passiert. Berücksichtige die Möglichkeit, gespeicherte Materialien anzusehen und herunterzuladen.\nBeispiel: „Nach der Kündigung der Verlängerung nutzt der Kunde das Programm bis zum Ende des bezahlten Zeitraums. Danach kann er gespeicherte Dokumente ansehen und herunterladen, aber keine neuen hinzufügen oder bestehende bearbeiten.“\nPasse die Regeln an dein Angebot an. Das Ende des bezahlten Zugangs, das Löschen des Kontos und das Löschen gespeicherter Materialien sind getrennte Entscheidungen.\nPrüfe zum Schluss mit der Person, die das Programm baut, ob die gewählte Zahlungsabwicklung eure Vereinbarungen umsetzen kann. Dieselben Regeln sollten den Kunden klar erklärt werden.","guide_sources":["Stripe, Create subscriptions: Abos über fertige Werkzeuge und Zahlungslinks abwickeln.","Stripe, Using webhooks with subscriptions: Zahlungsinformationen und Zugriffsverwaltung.","Stripe, Cancel subscriptions: Kündigung der Verlängerung und Ende nach dem bezahlten Zeitraum."]},"uk":{"title":"Визнач правила платного доступу","duration_hint":"Близько 15 хвилин","guide_body":"Як клієнт платить і отримує доступ\nСкористайся способом розрахунку, обраним в Idea Stage. Визнач, як заплатить перша людина і що має статися, щоб вона могла користуватися оплаченою версією.\nДля простої пропозиції можна скористатися готовим посиланням на оплату. Якщо спочатку обслуговуєш небагато людей, доступ можна надавати вручну після перевірки платежу в панелі платіжного оператора.\nПриклад: «Клієнт платить через посилання, прив’язане до обраної пропозиції. Після підтвердження оплати в панелі оператора ми розблоковуємо його акаунт і повідомляємо, що він може почати користуватися».\nЗа ручного обслуговування домовся, хто перевіряє платежі і скільки клієнт чекатиме на доступ. Також треба стежити за наступними платежами й кінцем оплаченого періоду.\nЯкщо доступ має вмикатися автоматично, людина, яка створює програму, мусить пов’язати її з інформацією від платіжного оператора. Саме посилання на оплату не означає, що акаунт автоматично розблокується.\nЗа оплати залежно від використання визнач також, звідки ви візьмете інформацію про використаний обсяг, наприклад про кількість виконаних завдань.\n§\nЩо відбувається в типових ситуаціях\nПройди ситуації із завдання. Для кожної запиши, що користувач може зробити і з якого моменту змінюються його можливості.\nПочни з успішної оплати. Визнач, коли клієнт отримує доступ і на який час. Якщо пропонуєш безплатний тест, виріши, що відбувається після його завершення: які можливості залишаються і що користувач має зробити, щоб користуватися далі. Якщо такого тесту немає, впиши «Не стосується».\nЗа невдалої оплати розрізняй першу покупку й поновлення. Людина, яка лише створює акаунт, у іншій ситуації, ніж клієнт, що кілька місяців користується програмою і раптом має проблему з карткою. Визнач, чи наявний клієнт отримує додатковий час і коли настане обмеження користування.\nОкремо розглянь відмову від поновлення. Запиши, до якого моменту клієнт може користуватися вже оплаченими можливостями і коли припиняється стягнення наступних оплат. Далі визнач, що відбувається після завершення оплаченого періоду. Врахуй можливість переглядати й завантажувати збережені матеріали.\nПриклад: «Після відмови від поновлення клієнт користується до кінця оплаченого періоду. Потім може переглядати й завантажувати збережені документи, але не може додавати нових чи редагувати наявні».\nДобери правила до своєї пропозиції. Завершення платного доступу, видалення акаунта й видалення збережених матеріалів — це окремі рішення.\nНасамкінець перевір із людиною, яка створює програму, чи обраний спосіб обробки платежів дає змогу застосувати ваші домовленості. Ті самі правила треба чітко пояснити клієнтові.","guide_sources":["Stripe, Create subscriptions: обслуговування підписок через готові інструменти й посилання на оплату.","Stripe, Using webhooks with subscriptions: інформація про платежі та керування доступом.","Stripe, Cancel subscriptions: відмова від поновлення й завершення після оплаченого періоду."]},"es":{"title":"Define las reglas del acceso de pago","duration_hint":"Unos 15 minutos","guide_body":"Cómo paga el cliente y obtiene acceso\nUsa la forma de cobro elegida en la Idea Stage. Determina cómo pagará la primera persona y qué tiene que pasar para que pueda usar la versión de pago.\nCon una oferta sencilla puedes usar un enlace de pago ya hecho. Si al principio atiendes a pocas personas, puedes dar acceso a mano tras comprobar el pago en el panel del proveedor de pagos.\nEjemplo: «El cliente paga con el enlace de la oferta elegida. Cuando el panel del proveedor confirma el pago, desbloqueamos su cuenta y le avisamos de que puede empezar».\nSi lo gestionas a mano, acuerda quién comprueba los pagos y cuánto esperará el cliente para tener acceso. También hay que vigilar los pagos siguientes y el fin del periodo pagado.\nSi el acceso debe activarse automáticamente, quien construye el programa tiene que conectarlo con la información del proveedor de pagos. Un enlace de pago, por sí solo, no desbloquea la cuenta automáticamente.\nSi cobras por uso, determina también de dónde sacaréis la cantidad utilizada, por ejemplo el número de tareas realizadas.\n§\nQué pasa en situaciones típicas\nRepasa las situaciones de la tarea. En cada una anota qué puede hacer el usuario y desde cuándo cambian sus posibilidades.\nEmpieza por un pago correcto. Determina cuándo obtiene acceso el cliente y por cuánto tiempo. Si ofreces una prueba gratuita, decide qué pasa al terminar: qué posibilidades se mantienen y qué tiene que hacer el usuario para seguir. Si no hay prueba, escribe «No aplica».\nSi falla un pago, distingue la primera compra de la renovación. Quien acaba de crear la cuenta está en otra situación que un cliente que lleva meses usando el programa y de repente tiene un problema con la tarjeta. Determina si el cliente actual tiene tiempo adicional y cuándo se limitará el uso.\nTrata aparte la cancelación de la renovación. Anota hasta cuándo puede usar el cliente lo ya pagado y cuándo dejan de cobrarse nuevos pagos. Después determina qué pasa al terminar el periodo pagado. Ten en cuenta la posibilidad de ver y descargar los materiales guardados.\nEjemplo: «Tras cancelar la renovación, el cliente lo usa hasta el final del periodo pagado. Después puede ver y descargar los documentos guardados, pero no añadir nuevos ni editar los existentes».\nAjusta las reglas a tu oferta. Terminar el acceso de pago, borrar la cuenta y borrar los materiales guardados son decisiones distintas.\nPor último, comprueba con quien construye el programa si la forma elegida de gestionar pagos permite aplicar lo acordado. Las mismas reglas deben explicarse con claridad al cliente.","guide_sources":["Stripe, Create subscriptions: gestionar suscripciones con herramientas ya hechas y enlaces de pago.","Stripe, Using webhooks with subscriptions: información de pagos y gestión del acceso.","Stripe, Cancel subscriptions: cancelar la renovación y finalizar tras el periodo pagado."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'paid';
update public.stage_subpoints s set translations = '{"de":{"title":"Ist die erste Version kostenpflichtig?"},"uk":{"title":"Чи перша версія платна?"},"es":{"title":"¿La primera versión es de pago?"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'paid' and s.key = 'choice';
update public.stage_fields f set translations = '{"de":{"question":"Wird in der ersten Version jemand für den Zugang zahlen?","help":"Wenn nicht, entfällt der Rest dieses Punkts. Du kommst darauf zurück, wenn du die Antwort änderst.","config":{"options":[{"value":"yes","label":"Ja, der Zugang wird kostenpflichtig"},{"value":"no","label":"Nein, die erste Version ist kostenlos"}]}},"uk":{"question":"Чи в першій версії хтось платитиме за доступ?","help":"Якщо ні, решта цього пункту відпадає. Повернешся до неї, коли зміниш відповідь.","config":{"options":[{"value":"yes","label":"Так, доступ буде платним"},{"value":"no","label":"Ні, перша версія безплатна"}]}},"es":{"question":"¿Alguien pagará por el acceso en la primera versión?","help":"Si no, el resto de este punto no aplica. Volverás a él si cambias la respuesta.","config":{"options":[{"value":"yes","label":"Sí, el acceso será de pago"},{"value":"no","label":"No, la primera versión es gratuita"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'choice' and f.key = 'answer';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie Kunden zahlen und Zugang bekommen"},"uk":{"title":"Як клієнт платить і отримує доступ"},"es":{"title":"Cómo paga el cliente y obtiene acceso"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'paid' and s.key = 'how';
update public.stage_fields f set translations = '{"de":{"question":"Wie zahlen Kunden und wie bekommen sie Zugang?","help":"Schreib, wer die Zahlung prüft und ob das Konto von Hand oder automatisch freigeschaltet wird.","example":"Kunden zahlen über den Link zum Angebot. Nach Zahlungseingang im Dashboard des Zahlungsanbieters schalten wir das Konto von Hand frei und schreiben, dass es losgehen kann."},"uk":{"question":"Як клієнт заплатить і як отримає доступ?","help":"Напиши, хто перевіряє оплату і чи акаунт вмикається вручну, чи сам.","example":"Клієнт платить через посилання на пропозицію. Після оплати в панелі оператора вручну розблоковуємо акаунт і пишемо, що можна починати."},"es":{"question":"¿Cómo pagará el cliente y cómo obtendrá acceso?","help":"Escribe quién comprueba el pago y si la cuenta se activa a mano o sola.","example":"El cliente paga con el enlace de la oferta. Cuando llega el pago al panel del proveedor, desbloqueamos la cuenta a mano y le escribimos que ya puede empezar."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'how' and f.key = 'flow';
update public.stage_subpoints s set translations = '{"de":{"title":"Wann der Zugang beginnt und endet"},"uk":{"title":"Коли доступ починається і закінчується"},"es":{"title":"Cuándo empieza y termina el acceso"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'saas' and p.key = 'paid' and s.key = 'cases';
update public.stage_fields f set translations = '{"de":{"question":"Ein Kunde hat den Zugang bezahlt. Ab wann kann er ihn nutzen und wie lange?","help":"Ein Satz. Bei nutzungsabhängiger Abrechnung ergänze, woher ihr die Verbrauchsdaten bekommt.","example":"Der Zugang wird am selben Tag freigeschaltet und gilt bis zum Ende des bezahlten Monats."},"uk":{"question":"Клієнт оплатив доступ. З якого моменту може користуватися і як довго?","help":"Одне речення. За оплати за використання допиши, звідки берете інформацію про використання.","example":"Доступ вмикається того ж дня й триває до кінця оплаченого місяця."},"es":{"question":"Un cliente ha pagado el acceso. ¿Desde cuándo puede usarlo y durante cuánto tiempo?","help":"Una frase. Si cobras por uso, añade de dónde sacáis la información del consumo.","example":"El acceso se activa el mismo día y dura hasta el final del mes pagado."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'paid_ok';
update public.stage_fields f set translations = '{"de":{"question":"Der kostenlose Test ist zu Ende. Was bleibt und was erfordert eine Zahlung?","help":"Wenn es keinen kostenlosen Test gibt, schreib „Entfällt“.","example":"Nach 14 Tagen kann er gespeicherte Daten nur noch ansehen, bis er den Zugang bezahlt."},"uk":{"question":"Безплатний тест закінчився. Що залишається, а що вимагає оплати?","help":"Якщо безплатного тесту немає, напиши «Не стосується».","example":"Після 14 днів може лише переглядати збережені дані, доки не оплатить доступ."},"es":{"question":"Ha terminado la prueba gratuita. ¿Qué se mantiene y qué requiere pago?","help":"Si no hay prueba gratuita, escribe «No aplica».","example":"Pasados 14 días solo puede ver los datos guardados hasta que pague el acceso."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'trial';
update public.stage_fields f set translations = '{"de":{"question":"Die Zahlung ist fehlgeschlagen. Was passiert mit einem neuen Konto und was mit einem Kunden, der es schon nutzt?","help":"Trenne Erstkauf und Verlängerung. Schreib, ob Bestandskunden zusätzliche Tage bekommen.","example":"Ein neues Konto wird deaktiviert. Bestandskunden haben 7 Tage, um die Karte zu aktualisieren, danach wird das Hinzufügen neuer Inhalte gesperrt."},"uk":{"question":"Оплата не вдалася. Що з новим акаунтом, а що з клієнтом, який уже користується?","help":"Розрізняй першу покупку й поновлення. Напиши, чи наявний клієнт отримує додаткові дні.","example":"Новий акаунт вимикається. Наявний клієнт має 7 днів, щоб виправити картку, потім можливість додавати нове закривається."},"es":{"question":"El pago ha fallado. ¿Qué pasa con una cuenta nueva y qué con un cliente que ya lo usa?","help":"Separa la primera compra de la renovación. Escribe si el cliente actual tiene días adicionales.","example":"La cuenta nueva se desactiva. El cliente actual tiene 7 días para corregir la tarjeta; después se bloquea añadir cosas nuevas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'failed';
update public.stage_fields f set translations = '{"de":{"question":"Ein Kunde hat die Verlängerung gekündigt, aber der bezahlte Zeitraum läuft noch. Bis wann nutzt er das Programm?","help":"Schreib, bis wann das bereits Bezahlte gilt und dass keine weitere Gebühr abgebucht wird.","example":"Er nutzt es bis zum Ende des bezahlten Monats. Die nächste Zahlung wird nicht abgebucht."},"uk":{"question":"Клієнт відмовився від поновлення, але оплачений період ще триває. До якого моменту він користується?","help":"Напиши, до якого моменту діє вже оплачене і що наступна оплата не стягується.","example":"Користується до кінця оплаченого місяця. Наступний платіж не списується."},"es":{"question":"Un cliente ha cancelado la renovación, pero el periodo pagado sigue en curso. ¿Hasta cuándo lo usa?","help":"Escribe hasta cuándo vale lo ya pagado y que no se cobra el siguiente pago.","example":"Lo usa hasta el final del mes pagado. No se cobra el siguiente pago."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'cancel';
update public.stage_fields f set translations = '{"de":{"question":"Der bezahlte Zeitraum ist vorbei. Kann er gespeicherte Materialien noch ansehen oder herunterladen?","help":"Ende des Zugangs, Löschen des Kontos und Löschen der Materialien sind getrennte Entscheidungen.","example":"Er kann gespeicherte Dokumente ansehen und herunterladen. Er kann keine neuen hinzufügen oder sie ändern."},"uk":{"question":"Оплачений період закінчився. Чи може він ще переглядати або завантажити збережені матеріали?","help":"Завершення доступу, видалення акаунта й видалення матеріалів — окремі рішення.","example":"Може переглядати й завантажувати збережені документи. Не може додавати нових чи їх змінювати."},"es":{"question":"Ha terminado el periodo pagado. ¿Puede todavía ver o descargar los materiales guardados?","help":"Terminar el acceso, borrar la cuenta y borrar los materiales son decisiones distintas.","example":"Puede ver y descargar los documentos guardados. No puede añadir nuevos ni cambiarlos."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'saas' and p.key = 'paid'
    and s.key = 'cases' and f.key = 'ended';
update public.stage_categories c set translations = '{"de":{"title":"Hardware","intro":"Mach aus den ersten Schätzungen aus Idea Zahlen, Lieferanten, Tests und eine Liste dessen, was den Bau noch blockiert."},"uk":{"title":"Hardware","intro":"Перетвори попередні оцінки з Idea на числа, постачальників, тести і список того, що ще блокує створення."},"es":{"title":"Hardware","intro":"Convierte las estimaciones iniciales de Idea en cifras, proveedores, pruebas y una lista de lo que aún bloquea la construcción."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'preparation' and t.version = 1 and c.key = 'hardware';
update public.stage_points p set translations = '{"de":{"title":"Formalisiere die Anforderungen der ersten Version","duration_hint":"Etwa 25 Minuten","guide_body":"Von der Schätzung zur Spezifikation\nPreparation bedeutet bei einem physischen Produkt den Schritt vom Wissen „Ist das machbar?“ zum Dokument „Wie genau bauen wir es?“. Idea hat die Fragen nach Machbarkeit, Kosten, Zeit, Nachfrage und Konformität beantwortet — als erste Schätzungen. Aufgabe dieser Etappe ist nicht, Tests zu wiederholen, sondern die Ergebnisse in eine messbare Spezifikation zu übersetzen, die sich ohne Rätselraten umsetzen lässt.\nJede Einschränkung aus früheren Tests — Haltbarkeit, Gewicht, Energieverbrauch, Genauigkeit — bekommt jetzt einen Zahlenwert und einen Status: verpflichtend oder wünschenswert.\nListet auf dieser Grundlage die wichtigsten Baugruppen auf, trennt kritische von Hilfskomponenten und ordnet jedes Modul einer Kategorie zu: muss, sollte, kann, nicht jetzt. Prüft zum Schluss, ob der Umfang alle verpflichtenden Anforderungen abdeckt. Wenn nicht, muss die Lücke geschlossen werden, bevor jemand mit dem Entwurf beginnt.\n§\nMessbare Anforderungen\nMach aus losen Ideen Zahlen. Statt zu schreiben, das Gerät solle „leicht sein und lange halten“, notiere konkrete Parameter: maximales Gewicht, Abmessungen und die erforderliche Akkulaufzeit.\nGenaue Zahlen vom ersten Tag an verringern Missverständnisse zwischen der Person, die für das Produkt verantwortlich ist, und der Person, die es baut, und erlauben es, den Fortschritt zu prüfen.\n§\nMinimum und Ziel\nLegt für jeden Parameter zwei Werte fest: die absolute Mindestschwelle, die für eine funktionierende erste Version nötig ist, und den Zielwert, den ihr später anstrebt.\nDie Trennung dieser Werte schützt davor, ständig Verbesserungen hinzuzufügen, und lässt euch eine stabile erste Version veröffentlichen, ohne den Start endlos zu verschieben.\n§\nVerpflichtend und wünschenswert\nTeilt die Funktionen in kritische und zusätzliche. Beschreibt den erwarteten Effekt, zum Beispiel „das Gerät überträgt alle 5 Sekunden drahtlos Daten“, und nicht eine konkrete Schaltungslösung wie „wir verwenden Modul X“.\nFasst das in einer Notiz zusammen, auf die das ganze Team Zugriff hat. Sonst entstehen leicht zwei widersprüchliche Versionen der Annahmen."},"uk":{"title":"Формалізуй вимоги першої версії","duration_hint":"Близько 25 хвилин","guide_body":"Від оцінки до специфікації\nPreparation для фізичного продукту — це перехід від знання «чи це здійсненно» до документа «як саме ми це збудуємо». Idea відповіла на запитання про здійсненність, витрати, час, попит і відповідність — у формі попередніх оцінок. Завдання цього етапу — не повторювати тести, а перекласти результати в вимірювану специфікацію, яку можна реалізувати без здогадок.\nКожне обмеження з попередніх тестів — довговічність, маса, енергоспоживання, точність — тепер отримує числове значення і статус: обов’язкове чи бажане.\nНа цій основі випишіть ключові вузли, відокремте критичні елементи від допоміжних і віднесіть кожен модуль до категорії: має бути, бажано, може бути, не зараз. Насамкінець перевірте, чи обсяг покриває всі обов’язкові вимоги. Якщо ні, прогалину треба закрити, перш ніж хтось почне проєктувати.\n§\nВимірювані вимоги\nПеретвори розмиті ідеї на числа. Замість писати, що пристрій має бути «легким і довго працювати», запиши конкретні параметри: максимальну масу, розміри і потрібний час роботи від батареї.\nТочні числа з першого дня зменшують непорозуміння між людиною, відповідальною за продукт, і людиною, яка його створює, і дають змогу перевіряти поступ.\n§\nМінімум і мета\nДля кожного параметра визначте два значення: абсолютно мінімальний поріг, потрібний для робочої першої версії, і цільове значення, до якого прагнете пізніше.\nРозділення цих значень захищає від постійного додавання поліпшень і дає змогу випустити стабільну першу версію, не відкладаючи старт без кінця.\n§\nОбов’язкове і бажане\nПоділіть функції на критичні й додаткові. Описуйте очікуваний ефект, наприклад «пристрій бездротово передає дані кожні 5 секунд», а не конкретне схемне рішення, наприклад «використовуємо модуль X».\nЗберіть це в одному записі, доступному всій команді. Інакше легко отримати дві суперечливі версії припущень."},"es":{"title":"Formaliza los requisitos de la primera versión","duration_hint":"Unos 25 minutos","guide_body":"De la estimación a la especificación\nPara un producto físico, Preparation supone pasar del saber «¿es viable?» al documento «¿cómo exactamente lo construiremos?». Idea respondió a las preguntas sobre viabilidad, costes, plazos, demanda y conformidad en forma de estimaciones iniciales. La tarea de esta etapa no es repetir pruebas, sino traducir los resultados a una especificación medible que se pueda llevar a cabo sin conjeturas.\nCada limitación de las pruebas anteriores —durabilidad, peso, consumo de energía, precisión— recibe ahora un valor numérico y un estado: obligatorio o deseable.\nA partir de ahí, enumerad los subconjuntos clave, separad los elementos críticos de los auxiliares y asignad cada módulo a una categoría: debe estar, debería estar, puede estar, ahora no. Al final, comprobad si el alcance cubre todos los requisitos obligatorios. Si no, hay que cerrar el hueco antes de que nadie empiece a diseñar.\n§\nRequisitos medibles\nConvierte las ideas vagas en cifras. En lugar de escribir que el dispositivo debe ser «ligero y durar mucho», anota parámetros concretos: peso máximo, dimensiones y autonomía de batería necesaria.\nTener cifras precisas desde el primer día reduce los malentendidos entre quien lleva el producto y quien lo construye, y permite comprobar el avance.\n§\nMínimo y objetivo\nPara cada parámetro fijad dos valores: el umbral mínimo imprescindible para tener una primera versión que funcione y el valor objetivo al que aspiráis después.\nSeparar estos valores protege de añadir mejoras sin parar y permite lanzar una primera versión estable sin aplazar el inicio indefinidamente.\n§\nObligatorio y deseable\nDividid las funciones en críticas y adicionales. Describid el efecto esperado, por ejemplo «el dispositivo envía datos de forma inalámbrica cada 5 segundos», y no una solución de circuito concreta, como «usamos el módulo X».\nReunidlo en un único registro accesible para todo el equipo. Si no, es fácil acabar con dos versiones contradictorias de los supuestos."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'spec';
update public.stage_subpoints s set translations = '{"de":{"title":"Messbare Parameter"},"uk":{"title":"Параметри, які можна виміряти"},"es":{"title":"Parámetros medibles"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'spec' and s.key = 'numbers';
update public.stage_fields f set translations = '{"de":{"question":"Notiere Funktionen und Einschränkungen als messbare Anforderungen.","help":"Eine Zeile ist ein Parameter. Das Minimum muss in der ersten Version erfüllt sein. Das Ziel hebt ihr euch für später auf. Priorität: verpflichtend oder wünschenswert.","example":"Laufzeit. Minimum 8 Stunden, Ziel 12 Stunden, verpflichtend. Gewicht. Minimum bis 300 g, Ziel bis 250 g, wünschenswert.","config":{"add_label":"Anforderung hinzufügen","columns":[{"key":"name","label":"Parameter oder Effekt","placeholder":"Z. B. Laufzeit mit einer Ladung"},{"key":"minimum","label":"Minimum der ersten Version","placeholder":"Z. B. 8 Stunden"},{"key":"target","label":"Ziel für später","placeholder":"Z. B. 12 Stunden"},{"key":"priority","label":"Verpflichtend oder wünschenswert","placeholder":"Verpflichtend oder wünschenswert"}]}},"uk":{"question":"Запиши функції й обмеження як вимірювані вимоги.","help":"Одна позиція — один параметр. Мінімум має бути виконано в першій версії. Мету залишаєте на потім. Пріоритет: обов’язкове чи бажане.","example":"Час роботи. Мінімум 8 годин, мета 12 годин, обов’язкове. Маса. Мінімум до 300 г, мета до 250 г, бажане.","config":{"add_label":"Додати вимогу","columns":[{"key":"name","label":"Параметр або ефект","placeholder":"Напр. час роботи на одному заряді"},{"key":"minimum","label":"Мінімум першої версії","placeholder":"Напр. 8 годин"},{"key":"target","label":"Мета на потім","placeholder":"Напр. 12 годин"},{"key":"priority","label":"Обов’язкове чи бажане","placeholder":"Обов’язкове або бажане"}]}},"es":{"question":"Anota las funciones y limitaciones como requisitos medibles.","help":"Una línea es un parámetro. El mínimo debe cumplirse en la primera versión. El objetivo queda para después. Prioridad: obligatorio o deseable.","example":"Autonomía. Mínimo 8 horas, objetivo 12 horas, obligatorio. Peso. Mínimo hasta 300 g, objetivo hasta 250 g, deseable.","config":{"add_label":"Añadir requisito","columns":[{"key":"name","label":"Parámetro o efecto","placeholder":"P. ej. autonomía con una carga"},{"key":"minimum","label":"Mínimo de la primera versión","placeholder":"P. ej. 8 horas"},{"key":"target","label":"Objetivo para después","placeholder":"P. ej. 12 horas"},{"key":"priority","label":"Obligatorio o deseable","placeholder":"Obligatorio o deseable"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'spec'
    and s.key = 'numbers' and f.key = 'requirements';
update public.stage_points p set translations = '{"de":{"title":"Formalisiere Lieferanten und Produktion","duration_hint":"Etwa 30 Minuten","guide_body":"Warum Lieferanten so viel wiegen wie die Spezifikation\nErgänze die ersten Preisangaben und Lieferantenlisten aus Idea um harte Daten: Mindestbestellmengen, Verfügbarkeit, Ersatzteile für kritische Komponenten, maximale Lieferzeit, nötige Werkzeuge und Maschinen sowie geografische, rechtliche und kommerzielle Einschränkungen.\nHier zeigen sich am häufigsten die Risiken, die später die Produktion am stärksten verzögern.\n§\nPreise, Mengen und Verfügbarkeit\nMach aus der ersten Stückliste eine Datei für die erste Serie. Sammle Stückpreise, Verfügbarkeit und Mindestbestellmengen.\nEine häufige Falle: Der Hersteller verlangt den Kauf von Tausenden Stück eines Bauteils, während ihr eine Kleinserie fertigt. Diese Zahlen früh zu prüfen schützt davor, Geld in überzähligen Teilen zu binden.\n§\nErsatzteile\nNenne die Baugruppen, die am stärksten von Preisschwankungen oder Engpässen bedroht sind, und finde für sie ein Ersatzteil oder einen zweiten Lieferanten.\nDas Fehlen eines kleinen Bauteils kann die Produktion lange stoppen. Ein freigegebenes Ersatzteil ist eine Absicherung, keine Zierde der Liste.\n§\nLieferzeit und Werkzeuge\nLege die maximale Wartezeit für Schlüsselteile fest sowie die Maschinen, Formen und Prüfwerkzeuge, die für die Produktion nötig sind.\nEine eigene Spritzgussform für das Gehäuse kann 8–12 Wochen dauern. Trag diesen Termin sofort in den Plan ein, damit die Montage der Serie nicht stockt.\n§\nZoll und Transport\nNimm Zoll, Einfuhr- und Ausfuhrvorschriften und die realistische Transportzeit in die Kalkulation auf.\nDie Kosten pro Stück sind nicht nur der Großhandelspreis. Fracht, Steuern und Zollabwicklung verändern die Endmarge und den Termin."},"uk":{"title":"Формалізуй постачальників і виробництво","duration_hint":"Близько 30 хвилин","guide_body":"Чому постачальники важать стільки ж, скільки специфікація\nДоповни попередні ціни й списки постачальників з Idea твердими даними: мінімальні обсяги замовлень, доступність, замінники для критичних елементів, максимальний час виконання, потрібні інструменти й машини, а також географічні, правові й торговельні обмеження.\nСаме тут найчастіше виходять ризики, які пізніше найбільше затримують виробництво.\n§\nЦіни, кількості й доступність\nПеретвори попередній список деталей на один файл першої серії. Збери ціни за одиницю, доступність і мінімальні обсяги замовлень.\nЧаста пастка: виробник вимагає купити тисячі штук мікросхеми, а ви складаєте коротку серію. Рання перевірка цих чисел захищає від заморожування грошей у надлишкових деталях.\n§\nЗамінники\nВкажи вузли, найбільше вразливі до коливань цін чи дефіциту, і знайди для них замінник або другого постачальника.\nВідсутність однієї дрібної мікросхеми може надовго зупинити виробництво. Затверджений замінник — це страховка, а не прикраса списку.\n§\nЧас доставки й інструменти\nВизнач максимальний час очікування на ключові деталі, а також машини, форми й тестові інструменти, потрібні для виробництва.\nСпеціальна ливарна форма для корпусу може зайняти 8–12 тижнів. Одразу впиши цей термін у план, щоб не зупинити складання серії.\n§\nМито й транспорт\nДо розрахунку впиши мито, вимоги ввезення й вивезення та реальний час транспортування.\nВартість одиниці — це не лише ціна з оптового складу. Фрахт, податки й митне оформлення змінюють кінцеву маржу й термін."},"es":{"title":"Formaliza proveedores y producción","duration_hint":"Unos 30 minutos","guide_body":"Por qué los proveedores pesan tanto como la especificación\nCompleta los precios y listas de proveedores iniciales de Idea con datos firmes: cantidades mínimas de pedido, disponibilidad, sustitutos para los elementos críticos, plazo máximo de entrega, herramientas y máquinas necesarias y limitaciones geográficas, legales y comerciales.\nAquí suelen aparecer los riesgos que más retrasan después la producción.\n§\nPrecios, cantidades y disponibilidad\nConvierte la lista inicial de piezas en un archivo de la primera serie. Reúne precios unitarios, disponibilidad y cantidades mínimas de pedido.\nUna trampa frecuente: el fabricante exige comprar miles de unidades de un chip y vosotros montáis una serie corta. Comprobar pronto estas cifras evita inmovilizar dinero en piezas sobrantes.\n§\nSustitutos\nSeñala los subconjuntos más expuestos a cambios de precio o escasez y busca para ellos un sustituto o un segundo proveedor.\nLa falta de un pequeño chip puede parar la producción mucho tiempo. Un sustituto aprobado es una protección, no un adorno de la lista.\n§\nPlazo de entrega y herramientas\nFija el plazo máximo de espera de las piezas clave y las máquinas, moldes y herramientas de prueba necesarios para producir.\nUn molde de inyección propio para la carcasa puede llevar 8–12 semanas. Mete ese plazo en el plan desde ya para no frenar el montaje de la serie.\n§\nAduanas y transporte\nIncluye en el cálculo los aranceles, los requisitos de importación y exportación y el tiempo real de transporte.\nEl coste por unidad no es solo el precio del distribuidor. El flete, los impuestos y los trámites aduaneros cambian el margen final y el plazo."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'supply';
update public.stage_subpoints s set translations = '{"de":{"title":"Teile der ersten Serie"},"uk":{"title":"Деталі першої серії"},"es":{"title":"Piezas de la primera serie"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'supply' and s.key = 'bom';
update public.stage_fields f set translations = '{"de":{"question":"Sammle Preise, Mindestbestellmenge und Verfügbarkeit der Teile.","help":"Eine Zeile ist ein Teil oder Material. Unbekannten Preis als „zu prüfen“ eintragen, nicht als null.","example":"Gehäuse. 4,50 € pro Stück bei einer Mindestbestellung von 200. Verfügbar, Lieferung 6 Wochen.","config":{"add_label":"Teil hinzufügen","columns":[{"key":"part","label":"Teil","placeholder":"Name und ggf. Lieferant"},{"key":"price","label":"Preis pro Stück","placeholder":"Z. B. 4,50 € oder zu prüfen"},{"key":"moq","label":"Mindestbestellung","placeholder":"Z. B. 200 Stück"},{"key":"lead","label":"Verfügbarkeit und Lieferzeit","placeholder":"Z. B. vorrätig, 6 Wochen"}]}},"uk":{"question":"Збери ціни, мінімальне замовлення й доступність деталей.","help":"Одна позиція — одна деталь або матеріал. Невідому ціну впиши як «перевірити», а не як нуль.","example":"Корпус. 180 грн за штуку при замовленні від 200. Доступний, доставка 6 тижнів.","config":{"add_label":"Додати деталь","columns":[{"key":"part","label":"Деталь","placeholder":"Назва й можливий постачальник"},{"key":"price","label":"Ціна за штуку","placeholder":"Напр. 180 грн або перевірити"},{"key":"moq","label":"Мінімальне замовлення","placeholder":"Напр. 200 штук"},{"key":"lead","label":"Доступність і час доставки","placeholder":"Напр. є, 6 тижнів"}]}},"es":{"question":"Reúne precios, pedido mínimo y disponibilidad de las piezas.","help":"Una línea es una pieza o material. Si no conoces el precio, escribe «por comprobar», no cero.","example":"Carcasa. 4,50 € la unidad con pedido mínimo de 200. Disponible, entrega en 6 semanas.","config":{"add_label":"Añadir pieza","columns":[{"key":"part","label":"Pieza","placeholder":"Nombre y, si lo hay, proveedor"},{"key":"price","label":"Precio por unidad","placeholder":"P. ej. 4,50 € o por comprobar"},{"key":"moq","label":"Pedido mínimo","placeholder":"P. ej. 200 unidades"},{"key":"lead","label":"Disponibilidad y plazo de entrega","placeholder":"P. ej. disponible, 6 semanas"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'supply'
    and s.key = 'bom' and f.key = 'parts';
update public.stage_subpoints s set translations = '{"de":{"title":"Ersatzteile und Werkzeuge"},"uk":{"title":"Замінники й інструменти"},"es":{"title":"Sustitutos y herramientas"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'supply' and s.key = 'backup';
update public.stage_fields f set translations = '{"de":{"question":"Welche Teile sind riskant und welchen Ersatz gibt es?","help":"Trag Teile ein, deren Fehlen oder Preissprung die Serie stoppen würde. Wenn es keine gibt, lass die Liste leer und speichere.","example":"Mikrocontroller A. Ersatz: Baustein B, schon an einem Muster getestet.","config":{"add_label":"Kritisches Teil hinzufügen","columns":[{"key":"part","label":"Kritisches Teil","placeholder":"Was die Produktion stoppen kann"},{"key":"alt","label":"Ersatz oder zweiter Lieferant","placeholder":"Name oder „suche noch“"}]}},"uk":{"question":"Які деталі ризиковані і який у них замінник?","help":"Впиши деталі, відсутність чи стрибок ціни яких зупинили б серію. Якщо таких немає, залиш список порожнім і збережи.","example":"Мікроконтролер A. Замінник: мікросхема B, уже перевірена на зразку.","config":{"add_label":"Додати критичну деталь","columns":[{"key":"part","label":"Критична деталь","placeholder":"Що може зупинити виробництво"},{"key":"alt","label":"Замінник або другий постачальник","placeholder":"Назва або «ще шукаю»"}]}},"es":{"question":"¿Qué piezas son arriesgadas y qué sustituto tienen?","help":"Escribe las piezas cuya falta o subida de precio pararía la serie. Si no hay, deja la lista vacía y guarda.","example":"Microcontrolador A. Sustituto: chip B, ya probado en una muestra.","config":{"add_label":"Añadir pieza crítica","columns":[{"key":"part","label":"Pieza crítica","placeholder":"Qué puede parar la producción"},{"key":"alt","label":"Sustituto o segundo proveedor","placeholder":"Nombre o «todavía buscando»"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'supply'
    and s.key = 'backup' and f.key = 'seconds';
update public.stage_fields f set translations = '{"de":{"question":"Welche Werkzeuge, Maschinen oder Formen braucht die erste Serie?","help":"Ergänze bei jeder Zeile die ungefähre Vorbereitungszeit, wenn du sie kennst.","example":"Spritzgussform für das Gehäuse. Vorbereitung etwa 10 Wochen.\nPrüfstand für die Dichtheit."},"uk":{"question":"Які інструменти, машини чи форми потрібні для першої серії?","help":"Біля кожної позиції допиши орієнтовний час її підготовки, якщо знаєш.","example":"Ливарна форма корпусу. Підготовка близько 10 тижнів.\nСтенд для перевірки герметичності."},"es":{"question":"¿Qué herramientas, máquinas o moldes hacen falta para la primera serie?","help":"En cada línea añade el tiempo aproximado de preparación, si lo conoces.","example":"Molde de inyección de la carcasa. Preparación unas 10 semanas.\nBanco de prueba de estanqueidad."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'supply'
    and s.key = 'backup' and f.key = 'tools';
update public.stage_fields f set translations = '{"de":{"question":"Welche Zölle, Ein- und Ausfuhrvorschriften und Transportzeiten fließen in Kosten und Termin ein?","help":"Wenn du in einem Land verkaufst und produzierst und keine solchen Kosten siehst, schreib das direkt.","example":"Teile aus Asien: Fracht und Zoll etwa 12 % des Werts. Transport 4 Wochen. Das fließt in den Stückpreis ein."},"uk":{"question":"Яке мито, правила ввезення й вивезення та час транспортування входять у вартість і термін?","help":"Якщо продаєш і виробляєш в одній країні й не бачиш таких витрат, напиши це прямо.","example":"Деталі з Азії: фрахт і мито близько 12% вартості. Транспорт 4 тижні. Це входить у ціну одиниці."},"es":{"question":"¿Qué aranceles, normas de importación y exportación y tiempos de transporte entran en el coste y el plazo?","help":"Si vendes y fabricas en un mismo país y no ves estos costes, dilo directamente.","example":"Piezas de Asia: flete y aranceles, en torno al 12 % del valor. Transporte de 4 semanas. Entra en el precio unitario."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'supply'
    and s.key = 'backup' and f.key = 'logistics';
update public.stage_points p set translations = '{"de":{"title":"Lege Qualität, Sicherheit und Zuverlässigkeit fest","duration_hint":"Etwa 20 Minuten","guide_body":"Qualität, bevor das Produkt auf den Markt kommt\nÜbersetze die Probleme aus den Prototyptests in Bedingungen, deren Erfüllung sich messen lässt. Sicherheitsanforderungen sind nicht verhandelbar, unabhängig von Zeit- oder Budgetdruck.\n§\nSichere Nutzung\nMach aus technologischen Risiken und Nutzungsszenarien Vorgaben, die einen Ausfall verhindern sollen.\nLege die Bedingungen für sicheren Betrieb bei normaler Nutzung und bei vorhersehbarer Fehlbedienung fest: Sturz, falsches Ladegerät, Feuchtigkeit. Wer Nutzerfehler mitdenkt, verringert spätere Rücksendungen.\n§\nHaltbarkeit und Fehlerschwelle\nLege die geplante Lebensdauer unter realen Bedingungen fest sowie den akzeptablen Anteil an Ausschuss in der Produktion und an Ausfällen bei Kunden.\nKein Gerät ist ausfallfrei. Ein Limit, zum Beispiel unter 1 % Ausfälle pro Jahr, erlaubt es, Austausch und Kontrolle zu planen, statt null anzunehmen.\n§\nEs lässt sich prüfen\nFormuliere jede Anforderung so, dass sie sich durch Messung, Test oder Verfahren prüfen lässt.\nStatt „das Gehäuse muss robust sein“ schreib: „Das Gehäuse übersteht einen Sturz aus 1,2 m Höhe auf Beton ohne Risse.“"},"uk":{"title":"Визнач якість, безпеку й надійність","duration_hint":"Близько 20 хвилин","guide_body":"Якість, перш ніж продукт вийде на ринок\nПерекладай проблеми з тестів прототипу в умови, виконання яких можна виміряти. Вимоги безпеки вважай такими, що не обговорюються, незалежно від тиску часу чи бюджету.\n§\nБезпечне використання\nПеретвори технологічні ризики й сценарії користування на настанови, які мають запобігти аварії.\nВизнач умови безпечної роботи за звичайного використання і за передбачувано неправильного: падіння, не той зарядний пристрій, вологість. Проєктування з урахуванням помилки користувача зменшує пізніші повернення.\n§\nДовговічність і поріг помилок\nВизнач запланований строк служби в реальних умовах і прийнятну частку браку на виробництві та відмов у клієнтів.\nЖоден пристрій не безвідмовний. Ліміт, наприклад менше 1% відмов на рік, дає змогу планувати заміни й контроль, а не закладати нуль.\n§\nЦе можна перевірити\nКожну вимогу сформулюй так, щоб її можна було перевірити вимірюванням, тестом чи процедурою.\nЗамість «корпус має бути міцним» запиши: «корпус витримує падіння з висоти 1,2 м на бетон без тріщин»."},"es":{"title":"Define calidad, seguridad y fiabilidad","duration_hint":"Unos 20 minutos","guide_body":"Calidad antes de que el producto llegue al mercado\nTraduce los problemas de las pruebas del prototipo a condiciones cuyo cumplimiento se pueda medir. Trata los requisitos de seguridad como innegociables, sea cual sea la presión de tiempo o de presupuesto.\n§\nUso seguro\nConvierte los riesgos tecnológicos y los escenarios de uso en pautas que eviten fallos.\nDefine las condiciones de funcionamiento seguro con un uso normal y con un mal uso previsible: caída, cargador equivocado, humedad. Diseñar pensando en el error del usuario reduce las devoluciones posteriores.\n§\nDurabilidad y umbral de fallos\nDefine la vida útil prevista en condiciones reales y el porcentaje aceptable de rechazos en producción y de averías en clientes.\nNingún dispositivo está libre de fallos. Un límite, por ejemplo menos del 1 % de averías al año, permite planificar sustituciones y controles en lugar de suponer cero.\n§\nSe puede comprobar\nFormula cada requisito de forma que pueda comprobarse con una medición, una prueba o un procedimiento.\nEn lugar de «la carcasa tiene que ser resistente», escribe: «la carcasa aguanta una caída de 1,2 m sobre hormigón sin agrietarse»."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'quality';
update public.stage_subpoints s set translations = '{"de":{"title":"Sichere Nutzung und Fehlerschwelle"},"uk":{"title":"Безпечне використання і поріг помилок"},"es":{"title":"Uso seguro y umbral de fallos"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'quality' and s.key = 'safe';
update public.stage_fields f set translations = '{"de":{"question":"Wie soll sich das Produkt bei normaler Nutzung und bei vorhersehbaren Nutzerfehlern verhalten?","help":"Sturz, falsche Stromversorgung, Feuchtigkeit, ein Kind in der Nähe — nur, was dieses Gerät wirklich betrifft.","example":"Bei einem Sturz vom Schreibtisch bricht das Gehäuse nicht. Ein falsches Ladegerät darf den Akku nicht beschädigen oder das Gehäuse erhitzen."},"uk":{"question":"Як продукт має поводитися за звичайного використання і за передбачуваної помилки користувача?","help":"Падіння, неправильне живлення, вологість, дитина поруч — лише те, що справді стосується цього пристрою.","example":"При падінні зі столу корпус не тріскає. Неправильний зарядний пристрій не може пошкодити батарею чи нагріти корпус."},"es":{"question":"¿Cómo debe comportarse el producto con un uso normal y ante un error previsible del usuario?","help":"Caída, alimentación incorrecta, humedad, un niño cerca: solo lo que de verdad afecta a este dispositivo.","example":"Si cae de la mesa, la carcasa no se rompe. Un cargador equivocado no puede dañar la batería ni calentar la carcasa."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'quality'
    and s.key = 'safe' and f.key = 'use';
update public.stage_fields f set translations = '{"de":{"question":"Wie lange soll es funktionieren und welchen Anteil an Defekten oder Ausschuss akzeptierst du?","help":"Nenne einen Zeitraum und eine Zahl. „Wenige Ausfälle“ lässt sich nicht prüfen.","example":"Ein Jahr tägliche Nutzung. Unter 2 % Ausschuss bei der Kontrolle und unter 1 % Ausfälle im ersten Jahr."},"uk":{"question":"Як довго має працювати і яку частку несправностей чи браку ти приймаєш?","help":"Вкажи період і число. «Мало відмов» перевірити неможливо.","example":"Рік щоденного використання. Менше 2% штук відбраковано на контролі й менше 1% відмов у перший рік."},"es":{"question":"¿Cuánto tiempo debe funcionar y qué porcentaje de defectos o rechazos aceptas?","help":"Indica un periodo y una cifra. «Pocas averías» no se puede comprobar.","example":"Un año de uso diario. Menos del 2 % de unidades rechazadas en control y menos del 1 % de averías el primer año."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'quality'
    and s.key = 'safe' and f.key = 'life';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie ihr das prüft"},"uk":{"title":"Як ви це перевірите"},"es":{"title":"Cómo lo comprobaréis"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'quality' and s.key = 'tests';
update public.stage_fields f set translations = '{"de":{"question":"Formuliere die Anforderungen so, dass sie sich messen lassen.","help":"Eine Zeile ist ein Test oder eine Messung.","example":"Dichtheit. 30 Minuten in 1 m Tiefe eingetaucht, kein Wasser im Inneren.","config":{"add_label":"Test hinzufügen","columns":[{"key":"need","label":"Anforderung","placeholder":"Was zutreffen soll"},{"key":"test","label":"Test oder Messung","placeholder":"Wie ihr das prüft"}]}},"uk":{"question":"Запиши вимоги так, щоб їх можна було виміряти.","help":"Одна позиція — один тест або вимірювання.","example":"Герметичність. Занурення на 30 хвилин на глибину 1 м, без води всередині.","config":{"add_label":"Додати тест","columns":[{"key":"need","label":"Вимога","placeholder":"Що має бути правдою"},{"key":"test","label":"Тест або вимірювання","placeholder":"Як ви це перевірите"}]}},"es":{"question":"Escribe los requisitos de forma que se puedan medir.","help":"Una línea es una prueba o una medición.","example":"Estanqueidad. Inmersión de 30 minutos a 1 m de profundidad, sin agua en el interior.","config":{"add_label":"Añadir prueba","columns":[{"key":"need","label":"Requisito","placeholder":"Qué tiene que cumplirse"},{"key":"test","label":"Prueba o medición","placeholder":"Cómo lo comprobaréis"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'quality'
    and s.key = 'tests' and f.key = 'checks';
update public.stage_points p set translations = '{"de":{"title":"Übersetze Vorschriften in Produkteigenschaften","duration_hint":"Etwa 25 Minuten","guide_body":"Vorschriften als Eigenschaften, nicht als Schlagworte\nOrdne die Regulierungen und Zertifikate aus Idea konkreten Produkteigenschaften, nötiger Dokumentation, Prüfumfang und Kennzeichnungen zu. Prüfe, ob eine rechtliche Anforderung einer technischen Annahme widerspricht, solange noch Zeit für eine Änderung ist.\n§\nWas eine Vorschrift am Entwurf ändert\nVerknüpfe Anforderungen mit konkreten Lösungen: Materialwahl, Erdung, Platinenlayout.\nElektromagnetische Verträglichkeit und elektrische Sicherheit, die schon beim Schaltplan berücksichtigt werden, vermeiden teure Korrekturen nach nicht bestandenen Prüfungen.\n§\nDokumente und Prüfungen\nErstelle eine Liste von Dokumenten, Berichten und Normen auf den gewählten Märkten, zum Beispiel CE oder FCC, und ordne sie der Phase zu, in der sie gebraucht werden.\nEine Zertifizierung erfordert vollständige technische Unterlagen. Wer sie laufend sammelt, vermeidet Stillstand kurz vor dem Verkauf.\n§\nEtiketten und Anleitung\nLege Inhalt, Symbole und Format der Typenschilder, Warnaufkleber und Anleitungen fest, die auf dem Startmarkt vorgeschrieben sind.\nEin fehlendes Pflichtsymbol, zum Beispiel die durchgestrichene Mülltonne, kann eine Lieferung stoppen oder den Verkauf unmöglich machen.\n§\nWiderspricht eine Vorschrift dem Rest\nPrüfe, ob eine rechtliche Anforderung den Abmessungen, dem Gewicht oder der Nutzungsweise widerspricht. Löse das vor dem Bau.\nBeispiel: Ein dickeres isolierendes Gehäuse ändert die Abmessungen noch auf der Zeichnung, bevor ihr Formen bestellt."},"uk":{"title":"Перетвори правила на властивості продукту","duration_hint":"Близько 25 хвилин","guide_body":"Правила як властивості, а не гасла\nЗістав регуляції й сертифікати з Idea з конкретними властивостями продукту, потрібною документацією, обсягом випробувань і позначеннями. Перевір, чи правова вимога не суперечить технічному припущенню, поки ще є час на зміну.\n§\nЩо правило змінює в проєкті\nПов’яжи вимоги з конкретними рішеннями: вибір матеріалу, заземлення, розведення плати.\nЕлектромагнітна сумісність і електробезпека, враховані ще на схемі, зменшують дорогі виправлення після невдалих випробувань.\n§\nДокументи й випробування\nСклади перелік документів, звітів і норм на обраних ринках, наприклад CE чи FCC, і прив’яжи їх до етапу, на якому вони потрібні.\nСертифікація вимагає повної технічної документації. Збирання її поточно зменшує простій перед самим продажем.\n§\nЕтикетки й інструкція\nВизнач зміст, символи й формат табличок, попереджувальних наліпок та інструкцій, вимаганих на ринку, з якого починаєш.\nВідсутність обов’язкового символу, наприклад перекресленого кошика, може зупинити поставку або унеможливити продаж.\n§\nЧи правило суперечить решті\nПеревір, чи правова вимога не суперечить розмірам, масі чи способу використання. Розв’яжи це до створення.\nПриклад: товстіший ізоляційний корпус змінює розміри ще на кресленні, до того як ви замовите форми."},"es":{"title":"Traduce la normativa en características del producto","duration_hint":"Unos 25 minutos","guide_body":"La normativa como características, no como lemas\nRelaciona las normas y certificados de Idea con características concretas del producto, la documentación necesaria, el alcance de los ensayos y el marcado. Comprueba si algún requisito legal choca con un supuesto técnico mientras aún hay tiempo para cambiarlo.\n§\nQué cambia una norma en el diseño\nVincula los requisitos con soluciones concretas: elección de material, toma de tierra, diseño de la placa.\nTener en cuenta la compatibilidad electromagnética y la seguridad eléctrica ya en el esquema evita correcciones caras tras suspender los ensayos.\n§\nDocumentos y ensayos\nHaz una lista de documentos, informes y normas de los mercados elegidos, por ejemplo CE o FCC, y asígnalos a la fase en que se necesitan.\nLa certificación exige la documentación técnica completa. Reunirla sobre la marcha evita parones justo antes de vender.\n§\nEtiquetas e instrucciones\nDefine el contenido, los símbolos y el formato de placas, adhesivos de advertencia e instrucciones obligatorios en el mercado por el que empiezas.\nQue falte un símbolo obligatorio, como el contenedor tachado, puede frenar una entrega o impedir la venta.\n§\n¿Choca una norma con el resto?\nComprueba si algún requisito legal contradice las dimensiones, el peso o la forma de uso. Resuélvelo antes de construir.\nEjemplo: una carcasa aislante más gruesa cambia las dimensiones todavía en el plano, antes de encargar los moldes."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'rules';
update public.stage_subpoints s set translations = '{"de":{"title":"Vorschriften und Kennzeichnungen"},"uk":{"title":"Правила й позначення"},"es":{"title":"Normativa y marcado"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'rules' and s.key = 'map';
update public.stage_fields f set translations = '{"de":{"question":"Welche Vorschrift oder welches Zertifikat ändert eine konkrete Produkteigenschaft?","help":"Eine Zeile ist eine Norm, ein Zeichen oder eine Pflicht. Ergänze, welchen Teil des Produkts sie betrifft.","example":"Elektrische Sicherheit. Gehäuse aus einem Material, das keine Flammen unterhält. Prüfung vor dem Verkauf in der EU.","config":{"add_label":"Anforderung hinzufügen","columns":[{"key":"rule","label":"Vorschrift, Norm oder Zertifikat","placeholder":"Z. B. CE-Kennzeichnung, Batteriesicherheit"},{"key":"effect","label":"Was es am Produkt ändert","placeholder":"Material, Schaltung, Dokument"},{"key":"when","label":"Wann es nötig ist","placeholder":"Z. B. vor dem ersten Verkauf in der EU"}]}},"uk":{"question":"Яке правило чи сертифікат змінює конкретну властивість продукту?","help":"Одна позиція — одна норма, знак чи обов’язок. Допиши, якої частини продукту стосується.","example":"Електробезпека. Корпус із матеріалу, що не підтримує горіння. Випробування перед продажем у ЄС.","config":{"add_label":"Додати вимогу","columns":[{"key":"rule","label":"Правило, норма або сертифікат","placeholder":"Напр. маркування CE, безпека батарей"},{"key":"effect","label":"Що змінює в продукті","placeholder":"Матеріал, схема, документ"},{"key":"when","label":"Коли це потрібно","placeholder":"Напр. перед першим продажем у ЄС"}]}},"es":{"question":"¿Qué norma o certificado cambia una característica concreta del producto?","help":"Una línea es una norma, un marcado o una obligación. Añade a qué parte del producto afecta.","example":"Seguridad eléctrica. Carcasa de un material que no propaga la llama. Ensayo antes de vender en la UE.","config":{"add_label":"Añadir requisito","columns":[{"key":"rule","label":"Norma, estándar o certificado","placeholder":"P. ej. marcado CE, seguridad de baterías"},{"key":"effect","label":"Qué cambia en el producto","placeholder":"Material, circuito, documento"},{"key":"when","label":"Cuándo hace falta","placeholder":"P. ej. antes de la primera venta en la UE"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'rules'
    and s.key = 'map' and f.key = 'links';
update public.stage_fields f set translations = '{"de":{"question":"Was muss auf dem Startmarkt auf dem Etikett und in der Anleitung stehen?","help":"Inhalt, Zeichen und Sprache. Wenn du es noch nicht weißt, schreib „zu prüfen“ beim konkreten Zeichen, lass den Markt nicht weg.","example":"Produktname, Herstellerangaben, Symbol der durchgestrichenen Mülltonne und ein kurzer Warnhinweis auf Deutsch."},"uk":{"question":"Що має бути на етикетці й в інструкції на ринку, з якого починаєш?","help":"Зміст, знаки й мова. Якщо ще не знаєш, напиши «перевірити» біля конкретного знака, не пропускай ринку.","example":"Назва продукту, дані виробника, знак перекресленого кошика і коротке попередження українською."},"es":{"question":"¿Qué debe figurar en la etiqueta y en las instrucciones en el mercado por el que empiezas?","help":"Contenido, símbolos e idioma. Si aún no lo sabes, escribe «por comprobar» junto al símbolo concreto; no omitas el mercado.","example":"Nombre del producto, datos del fabricante, símbolo del contenedor tachado y una breve advertencia en español."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'rules'
    and s.key = 'map' and f.key = 'labels';
update public.stage_fields f set translations = '{"de":{"question":"Widerspricht eine Vorschrift früheren Anforderungen? Wie entscheidet ihr das?","help":"Wenn es keinen Widerspruch gibt, schreib „Kein Widerspruch“ und in einem Satz, was geprüft wurde.","example":"Die Isolierung erzwingt ein dickeres Gehäuse. Wir erhöhen das zulässige Maß von 80 mm auf 92 mm. Das Gewicht liegt weiter im Minimum."},"uk":{"question":"Чи якесь правило суперечить попереднім вимогам? Як ви це вирішуєте?","help":"Якщо суперечності немає, напиши «Суперечності немає» і одним реченням — що перевірено.","example":"Ізоляція вимагає товстішого корпусу. Підвищуємо допустимий розмір з 80 мм до 92 мм. Маса й далі в межах мінімуму."},"es":{"question":"¿Alguna norma contradice requisitos anteriores? ¿Cómo lo resolvéis?","help":"Si no hay contradicción, escribe «Sin contradicción» y, en una frase, qué se comprobó.","example":"El aislamiento obliga a una carcasa más gruesa. Subimos la medida admisible de 80 mm a 92 mm. El peso sigue dentro del mínimo."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'rules'
    and s.key = 'map' and f.key = 'clash';
update public.stage_points p set translations = '{"de":{"title":"Kläre Ressourcen und offene Probleme vor dem Bau","duration_hint":"Etwa 20 Minuten","guide_body":"Eine offene Liste dessen, was noch offen ist\nDas Ergebnis dieser Etappe ist kein fertiges Produkt. Das Ergebnis sind eine Spezifikation, Lieferantendaten, Qualitäts- und Vorschriftsanforderungen und eine Liste offener Risiken, mit der sich der Bau beginnen lässt, ohne zu raten, was entstehen soll.\nBeurteile bei jedem offenen Risiko aus Idea, ob ihr trotzdem starten könnt oder ob seine Lösung Bedingung für den Start ist. Nicht jedes Problem muss das Projekt stoppen. Jedes muss bewusst zurückgestellt sein, nicht übersehen.\n§\nWer und was fehlt\nListe Fachleute, Labore, Auftragnehmer und Maschinen auf, die für den Bau nötig sind. Markiere, was ihr schon habt und was beschafft werden muss.\nEin eigener Maschinenpark oder eine feste Stelle für eine Spezialistin ist in dieser Phase meist nicht nötig. Ein externes Labor oder ein Ingenieur für eine konkrete Prüfung ist oft schneller.\n§\nBudget mit Reserve\nReserviere einen Betrag für Werkzeuge, Prototypen, Prüfungen und Beratung auf Grundlage der vorigen Punkte.\nRechne etwa 15–20 % Reserve für eine Platinenkorrektur oder eine zusätzliche Laborsitzung ein. Bei Hardware klappt selten alles beim ersten Mal.\n§\nWas den Baustart blockiert\nNotiere die aktuellen technischen, kostenbezogenen, produktionsbezogenen und regulatorischen Risiken.\nTrenne die, die vor dem Bau gelöst werden müssen, von denen, die warten können. Die Kräfte gehen in das Risiko, das das Projekt stoppen kann, nicht in eine Kleinigkeit, die warten kann."},"uk":{"title":"Визнач ресурси й відкриті проблеми перед створенням","duration_hint":"Близько 20 хвилин","guide_body":"Відкритий список того, що ще не вирішено\nРезультатом цього етапу не є готовий продукт. Результат — специфікація, дані постачальників, вимоги якості й правил та список відкритих ризиків, з яким можна почати створення, не вгадуючи, що має з’явитися.\nДля кожного відкритого ризику з Idea оціни, чи можна рушати попри нього, чи його розв’язання — умова старту. Не кожна проблема мусить зупиняти проєкт. Кожна має бути свідомо відкладена, а не проґавлена.\n§\nКого й чого бракує\nВипиши фахівців, лабораторії, виконавців і машини, потрібні для створення. Познач, що вже маєте, а що треба здобути.\nВласний парк машин чи штатний вузький фахівець на цьому етапі зазвичай не потрібні. Зовнішня лабораторія чи інженер під конкретне випробування буває швидшим.\n§\nБюджет із запасом\nЗарезервуй суму на інструменти, прототипи, випробування й консультації на основі попередніх пунктів.\nДодай запас близько 15–20% на виправлення плати чи додаткову сесію в лабораторії. У залізі рідко все виходить з першого разу.\n§\nЩо блокує початок створення\nЗапиши поточні технічні, кошторисні, виробничі й регуляторні ризики.\nВідокрем ті, які треба розв’язати перед створенням, від тих, що можуть зачекати. Сили йдуть на ризик, що може зупинити проєкт, а не на дрібницю, яка може зачекати."},"es":{"title":"Define recursos y problemas abiertos antes de construir","duration_hint":"Unos 20 minutos","guide_body":"Una lista explícita de lo que sigue abierto\nEl resultado de esta etapa no es un producto terminado. Es una especificación, datos de proveedores, requisitos de calidad y normativa y una lista de riesgos abiertos con la que se puede empezar a construir sin adivinar qué hay que hacer.\nEn cada riesgo abierto de Idea, valora si podéis arrancar a pesar de él o si resolverlo es condición para empezar. No todos los problemas tienen que parar el proyecto. Todos tienen que aplazarse a conciencia, no pasarse por alto.\n§\nA quién y qué falta\nEnumera los especialistas, laboratorios, proveedores y máquinas necesarios para construir. Marca lo que ya tenéis y lo que hay que conseguir.\nEn esta fase no suele hacer falta un parque de máquinas propio ni contratar a un especialista muy concreto. Un laboratorio externo o un ingeniero para un ensayo concreto suele ser más rápido.\n§\nPresupuesto con margen\nReserva una cantidad para herramientas, prototipos, ensayos y consultas a partir de los puntos anteriores.\nAñade un margen del 15–20 % para corregir la placa o una sesión extra de laboratorio. En hardware rara vez sale todo a la primera.\n§\nQué bloquea el inicio de la construcción\nAnota los riesgos técnicos, de coste, de producción y normativos actuales.\nSepara los que hay que resolver antes de construir de los que pueden esperar. El esfuerzo va al riesgo que puede parar el proyecto, no a un detalle que puede esperar."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'readiness';
update public.stage_subpoints s set translations = '{"de":{"title":"Menschen, Werkzeuge und Budget"},"uk":{"title":"Люди, інструменти й бюджет"},"es":{"title":"Personas, herramientas y presupuesto"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'readiness' and s.key = 'resources';
update public.stage_fields f set translations = '{"de":{"question":"Was braucht ihr für den Bau und habt ihr es schon?","help":"Fachperson, Labor, Hersteller oder Maschine. Wenn es fehlt, schreib, woher ihr es bekommt.","example":"Dichtheitslabor. Haben wir nicht. Wir mieten eine Prüfung vor der Form.","config":{"add_label":"Ressource hinzufügen","columns":[{"key":"what","label":"Kompetenz oder Ressource","placeholder":"Wer oder was"},{"key":"status","label":"Haben wir oder müssen wir beschaffen","placeholder":"Haben wir, mieten wir, suchen wir"}]}},"uk":{"question":"Що вам потрібно для створення і чи вже це маєте?","help":"Фахівець, лабораторія, виробник або машина. За відсутності напиши, звідки візьмете.","example":"Лабораторія герметичності. Не маємо. Орендуємо одне випробування перед формою.","config":{"add_label":"Додати ресурс","columns":[{"key":"what","label":"Компетенція або ресурс","placeholder":"Хто або що"},{"key":"status","label":"Маємо чи треба здобути","placeholder":"Маємо, орендуємо, шукаємо"}]}},"es":{"question":"¿Qué necesitáis para construir y lo tenéis ya?","help":"Especialista, laboratorio, fabricante o máquina. Si falta, escribe de dónde lo sacaréis.","example":"Laboratorio de estanqueidad. No lo tenemos. Contrataremos un ensayo antes del molde.","config":{"add_label":"Añadir recurso","columns":[{"key":"what","label":"Competencia o recurso","placeholder":"Quién o qué"},{"key":"status","label":"Lo tenemos o hay que conseguirlo","placeholder":"Lo tenemos, lo alquilamos, lo buscamos"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'readiness'
    and s.key = 'resources' and f.key = 'needs';
update public.stage_fields f set translations = '{"de":{"question":"Welches Budget reservierst du für Werkzeuge, Prototypen, Tests und Beratung?","help":"Stütze den Betrag auf die vorigen Punkte und rechne etwa 15–20 % Reserve für die Korrektur ein, die beim ersten Anlauf auftaucht.","example":"Form, zwei Platineniterationen und eine Prüfung: 7.000 € plus 20 % Reserve, zusammen etwa 8.400 €."},"uk":{"question":"Який бюджет резервуєш на інструменти, прототипи, тести й консультації?","help":"Спирай суму на попередні пункти й додай запас близько 15–20% на виправлення, яке вийде з першої спроби.","example":"Форма, дві ітерації плати й одне випробування: 280 тис. грн плюс 20% запасу, разом близько 336 тис. грн."},"es":{"question":"¿Qué presupuesto reservas para herramientas, prototipos, pruebas y consultas?","help":"Basa la cifra en los puntos anteriores y añade un margen del 15–20 % para la corrección que saldrá en el primer intento.","example":"Molde, dos iteraciones de placa y un ensayo: 7.000 € más un 20 % de margen, unos 8.400 € en total."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'readiness'
    and s.key = 'resources' and f.key = 'budget';
update public.stage_subpoints s set translations = '{"de":{"title":"Was noch offen ist"},"uk":{"title":"Що ще відкрите"},"es":{"title":"Qué sigue abierto"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'hardware' and p.key = 'readiness' and s.key = 'risks';
update public.stage_fields f set translations = '{"de":{"question":"Welche technischen, kostenbezogenen, produktionsbezogenen oder regulatorischen Risiken sind noch offen?","help":"Schreib bei jedem, ob es den Baustart blockiert oder warten kann. Wenn die Liste leer ist, lass sie leer und speichere — das heißt, du siehst kein offenes Risiko.","example":"Unbekannter Preis des Funkmoduls. Muss vor der Serienbestellung bekannt sein. Die Gehäusefarbe kann warten.","config":{"add_label":"Risiko hinzufügen","columns":[{"key":"risk","label":"Offenes Problem","placeholder":"Was noch nicht entschieden ist"},{"key":"gate","label":"Blockiert den Bau oder kann warten","placeholder":"Blockiert oder kann warten"}]}},"uk":{"question":"Які технічні, кошторисні, виробничі чи регуляторні ризики ще відкриті?","help":"Біля кожного напиши, чи блокує початок створення, чи може зачекати. Якщо список порожній, залиш його й збережи — це означає, що відкритого ризику ти не бачиш.","example":"Невідома ціна радіомодуля. Треба знати її перед замовленням серії. Колір корпусу може зачекати.","config":{"add_label":"Додати ризик","columns":[{"key":"risk","label":"Відкрита проблема","placeholder":"Що досі не вирішено"},{"key":"gate","label":"Блокує створення чи може зачекати","placeholder":"Блокує або може зачекати"}]}},"es":{"question":"¿Qué riesgos técnicos, de coste, de producción o normativos siguen abiertos?","help":"En cada uno escribe si bloquea el inicio de la construcción o puede esperar. Si la lista está vacía, déjala así y guarda: significa que no ves riesgos abiertos.","example":"Precio desconocido del módulo de radio. Hay que saberlo antes de encargar la serie. El color de la carcasa puede esperar.","config":{"add_label":"Añadir riesgo","columns":[{"key":"risk","label":"Problema abierto","placeholder":"Qué sigue sin resolver"},{"key":"gate","label":"Bloquea la construcción o puede esperar","placeholder":"Bloquea o puede esperar"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'hardware' and p.key = 'readiness'
    and s.key = 'risks' and f.key = 'open';
update public.stage_categories c set translations = '{"de":{"title":"B2B","intro":"Bereite den Weg vom ersten Kontakt mit einer Firma bis zu dem Tag vor, an dem sie mit der Nutzung beginnen kann."},"uk":{"title":"B2B","intro":"Підготуй шлях від першого контакту з компанією до дня, коли вона зможе почати користуватися."},"es":{"title":"B2B","intro":"Prepara el camino desde el primer contacto con una empresa hasta el día en que puede empezar a usarlo."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'preparation' and t.version = 1 and c.key = 'b2b';
update public.stage_points p set translations = '{"de":{"title":"Bereite den Verkaufsprozess vor","duration_hint":"Etwa 20 Minuten","guide_body":"Ein kurzer Weg, kein langes Verfahren\nSchreib den Weg vom ersten Kontakt bis zum Beginn der Zusammenarbeit auf. Entferne Schritte, die die Entscheidung verlängern oder dein Gegenüber verwirren. Je einfacher der Weg, desto leichter kommt eine Firma zum Kauf.\nIm Verkauf an Firmen reichen meist drei oder vier Schritte: Gespräch und Bedarf verstehen, kurze Vorführung der passenden Lösung, Angebot, Abschluss.\n§\nWas eine Firma wirklich weiterbringt\nNotiere bei jeder Phase das Ereignis, nach dem die Firma weitergehen kann: Vorführung, Zustimmung der Person mit Budget, Bitte um ein Angebot.\nBring eine Sache nicht weiter, nur weil das Gespräch nett war. Stütze dich auf ein Signal: eine zurückgeschickte Bedarfsbeschreibung, die Anwesenheit der Person, die über das Budget verfügt.\n§\nEine Firmenliste statt eines eigenen Systems\nFührt die Firmen, mit denen ihr sprecht oder an die ihr euch wenden wollt: aktuelle Phase, nächster Schritt und die zuständige Person aus eurem Team.\nAnfangs reicht diese Liste. Ihr braucht kein eigenes Vertriebsprogramm. Wichtig ist, dass das ganze Team den nächsten Schritt sieht und weiß, wann er passieren soll."},"uk":{"title":"Підготуй процес продажу","duration_hint":"Близько 20 хвилин","guide_body":"Короткий шлях, а не довга процедура\nРозпиши шлях від першого контакту до початку співпраці. Прибери кроки, які подовжують рішення або плутають співрозмовника. Що простіший шлях, то легше компанії дійти до покупки.\nУ продажах компаніям зазвичай досить трьох-чотирьох кроків: розмова й пізнання потреби, короткий показ підібраного рішення, пропозиція, завершення.\n§\nЩо справді просуває компанію далі\nДля кожного етапу запиши подію, після якої компанія може перейти далі: демонстрація, згода людини з бюджетом, прохання про пропозицію.\nНе просувай справу лише тому, що розмова була приємною. Спирайся на сигнал: надісланий опис потреб, присутність людини, яка розпоряджається бюджетом.\n§\nСписок компаній замість окремої системи\nВедіть компанії, з якими розмовляєте або до яких хочете звернутися: поточний етап, наступний крок і людина з вашої команди.\nНа початку цього списку досить. Окрема програма для продажів не потрібна. Важливо, щоб уся команда бачила наступний крок і коли він має відбутися."},"es":{"title":"Prepara el proceso de venta","duration_hint":"Unos 20 minutos","guide_body":"Un camino corto, no un procedimiento largo\nDescribe el camino desde el primer contacto hasta el inicio de la colaboración. Quita los pasos que alargan la decisión o confunden a tu interlocutor. Cuanto más sencillo el camino, más fácil le resulta a la empresa llegar a comprar.\nEn la venta a empresas suelen bastar tres o cuatro pasos: conversación y conocer la necesidad, breve demostración de la solución ajustada, oferta y cierre.\n§\nQué hace avanzar de verdad a una empresa\nEn cada fase anota el hecho tras el cual la empresa puede avanzar: una demostración, el visto bueno de quien tiene el presupuesto, una petición de oferta.\nNo hagas avanzar el caso solo porque la conversación fue agradable. Básate en una señal: una descripción de necesidades devuelta, la presencia de quien maneja el presupuesto.\n§\nUna lista de empresas en lugar de un sistema aparte\nLlevad las empresas con las que habláis o a las que queréis dirigiros: fase actual, siguiente paso y persona de vuestro equipo.\nAl principio basta esta lista. No necesitáis un programa de ventas aparte. Lo importante es que todo el equipo vea el siguiente paso y cuándo debe ocurrir."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'sales';
update public.stage_subpoints s set translations = '{"de":{"title":"Der Weg vom Kontakt zur Zusammenarbeit"},"uk":{"title":"Шлях від контакту до співпраці"},"es":{"title":"Del contacto a la colaboración"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'sales' and s.key = 'steps';
update public.stage_fields f set translations = '{"de":{"question":"Ordne die Phasen und schreib, was die Firma weiterbringt.","help":"Eine Zeile ist eine Phase. Behalte nur Schritte, die es bei euch wirklich gibt.","example":"Gespräch. Weiter, wenn die andere Seite ein konkretes Problem beschreibt und einer Vorführung zustimmt. Vorführung. Weiter, wenn um ein Angebot gebeten wird.","config":{"add_label":"Phase hinzufügen","columns":[{"key":"stage","label":"Phase","placeholder":"Z. B. erstes Gespräch"},{"key":"forward","label":"Was passieren muss, um weiterzugehen","placeholder":"Ein konkretes Ereignis, nicht „gutes Gespräch“"}]}},"uk":{"question":"Розклади етапи й напиши, що просуває компанію далі.","help":"Одна позиція — один етап. Залиш лише кроки, які у вас справді є.","example":"Розмова. Далі, коли інша сторона опише конкретну проблему й погодиться на показ. Показ. Далі, коли попросять пропозицію.","config":{"add_label":"Додати етап","columns":[{"key":"stage","label":"Етап","placeholder":"Напр. перша розмова"},{"key":"forward","label":"Що має статися, щоб іти далі","placeholder":"Конкретна подія, а не «добра розмова»"}]}},"es":{"question":"Ordena las fases y escribe qué hace avanzar a la empresa.","help":"Una línea es una fase. Deja solo los pasos que de verdad tenéis.","example":"Conversación. Avanza cuando la otra parte describe un problema concreto y acepta una demostración. Demostración. Avanza cuando piden una oferta.","config":{"add_label":"Añadir fase","columns":[{"key":"stage","label":"Fase","placeholder":"P. ej. primera conversación"},{"key":"forward","label":"Qué tiene que pasar para avanzar","placeholder":"Un hecho concreto, no «buena conversación»"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'sales'
    and s.key = 'steps' and f.key = 'path';
update public.stage_subpoints s set translations = '{"de":{"title":"Firmen, mit denen ihr sprecht"},"uk":{"title":"Компанії, з якими ви розмовляєте"},"es":{"title":"Empresas con las que habláis"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'sales' and s.key = 'accounts';
update public.stage_fields f set translations = '{"de":{"question":"Trag Firmen ein, mit denen ihr schon sprecht oder an die ihr euch wenden wollt.","help":"Bei jeder: aktuelle Phase, nächste Aktion und wer in eurem Team dafür verantwortlich ist. Wenn du allein arbeitest, trag deinen Namen ein.","example":"Studio Nord. Nach dem ersten Gespräch. Angebot am Donnerstag schicken. Kuba.","config":{"add_label":"Firma hinzufügen","columns":[{"key":"company","label":"Firma","placeholder":"Name"},{"key":"stage","label":"Aktuelle Phase","placeholder":"Z. B. noch kein Kontakt"},{"key":"next","label":"Nächste Aktion","placeholder":"Was und wann"},{"key":"owner","label":"Wer aus eurem Team","placeholder":"Name"}]}},"uk":{"question":"Впиши компанії, з якими вже розмовляєте або до яких хочете звернутися.","help":"Для кожної: поточний етап, наступна дія і хто з вашої команди за це відповідає. Якщо працюєш сам, впиши своє ім’я.","example":"Studio Nord. Після першої розмови. Надіслати пропозицію в четвер. Kuba.","config":{"add_label":"Додати компанію","columns":[{"key":"company","label":"Компанія","placeholder":"Назва"},{"key":"stage","label":"Поточний етап","placeholder":"Напр. ще без контакту"},{"key":"next","label":"Наступна дія","placeholder":"Що й коли"},{"key":"owner","label":"Хто з вашої команди","placeholder":"Ім’я"}]}},"es":{"question":"Escribe las empresas con las que ya habláis o a las que queréis dirigiros.","help":"En cada una: fase actual, siguiente acción y quién de vuestro equipo se encarga. Si trabajas en solitario, escribe tu nombre.","example":"Studio Nord. Tras la primera conversación. Enviar la oferta el jueves. Kuba.","config":{"add_label":"Añadir empresa","columns":[{"key":"company","label":"Empresa","placeholder":"Nombre"},{"key":"stage","label":"Fase actual","placeholder":"P. ej. aún sin contacto"},{"key":"next","label":"Siguiente acción","placeholder":"Qué y cuándo"},{"key":"owner","label":"Quién de vuestro equipo","placeholder":"Nombre"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'sales'
    and s.key = 'accounts' and f.key = 'companies';
update public.stage_points p set translations = '{"de":{"title":"Bereite das erste Angebot vor","duration_hint":"Etwa 20 Minuten","guide_body":"Was genau ihr verkauft\nBeschreibe den Umfang der ersten Version in der Sprache des Nutzens, nicht als Technologieliste. Stütze dich auf das, was als erste Version entstehen soll.\nHaltet einen festen Kern des Angebots. Vermeidet es, für jeden Kunden alles von Grund auf zu entwerfen.\n§\nPreis und Zeit\nNenne den Preis oder die Art seiner Berechnung, wofür genau der Kunde zahlt und wie lange Zusammenarbeit oder Umsetzung dauern.\nEine kostenlose Testphase schafft selten Engagement bei einer Firma. Wenn ihr einen Test braucht, erwägt einen bezahlten Pilot zu niedrigeren Kosten oder eine klare Rückgabebedingung. Ein Kunde, der auch nur einen kleinen Betrag bezahlt, nimmt den Test ernster.\n§\nEin Pilot hat ein Ende\nWenn es einen Test gibt, legt vorher fest, was der Kunde bekommt und woran ihr ihn als abgeschlossen erkennt. Gibt es keinen Test, schreib „Entfällt“.\nEin Pilot ohne Ziel kann sich ohne Entscheidung hinziehen. Legt eine Kennzahl fest, zum Beispiel: „Wenn das Team in 14 Tagen 5 Stunden spart, gehen wir zum Vertrag über.“"},"uk":{"title":"Підготуй першу пропозицію","duration_hint":"Близько 20 хвилин","guide_body":"Що саме ви продаєте\nОпиши обсяг першої версії мовою користі, а не списком технологій. Спирайся на те, що має з’явитися як перша версія.\nТримайте сталий кістяк пропозиції. Уникайте проєктування всього з нуля для кожного клієнта.\n§\nЦіна й час\nВкажи ціну або спосіб її розрахунку, за що саме платить клієнт і як довго триває співпраця чи реалізація.\nБезплатний пробний період рідко будує залученість компанії. Якщо потрібна спроба, розгляньте платний пілот за нижчу ціну або чітку умову повернення коштів. Клієнт, який вкладає хоч невелику суму, ставиться до тесту серйозніше.\n§\nПілот має кінець\nЯкщо є тест, заздалегідь визнач, що клієнт отримує і за чим ви вважаєте його завершеним. Якщо тесту немає, напиши «Не стосується».\nПілот без мети може тягнутися без рішення. Визначте один показник, наприклад: «Якщо за 14 днів команда заощадить 5 годин, переходимо до договору»."},"es":{"title":"Prepara la primera oferta","duration_hint":"Unos 20 minutos","guide_body":"Qué vendéis exactamente\nDescribe el alcance de la primera versión en términos de beneficio, no como una lista de tecnologías. Básate en lo que va a ser la primera versión.\nMantened un núcleo fijo de la oferta. Evitad diseñarlo todo desde cero para cada cliente.\n§\nPrecio y plazo\nIndica el precio o cómo se calcula, por qué paga exactamente el cliente y cuánto dura la colaboración o la implantación.\nUn periodo de prueba gratuito rara vez genera compromiso en una empresa. Si necesitáis una prueba, plantead un piloto de pago a menor coste o una condición clara de devolución. Un cliente que pone aunque sea una cantidad pequeña se toma la prueba más en serio.\n§\nEl piloto tiene final\nSi hay prueba, fija de antemano qué recibe el cliente y cuándo la dais por terminada. Si no hay prueba, escribe «No aplica».\nUn piloto sin objetivo puede alargarse sin decisión. Fijad un indicador, por ejemplo: «Si en 14 días el equipo ahorra 5 horas, pasamos al contrato»."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'offer';
update public.stage_subpoints s set translations = '{"de":{"title":"Was ihr verkauft und zu welchem Preis"},"uk":{"title":"Що ви продаєте і за скільки"},"es":{"title":"Qué vendéis y a qué precio"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'offer' and s.key = 'scope';
update public.stage_fields f set translations = '{"de":{"question":"Welchen Umfang der ersten Version könnt ihr einer Firma anbieten?","help":"Stütze dich darauf, was im Allgemeinen Teil für die erste Version entstehen soll. Schreib, was Kunden bekommen, nicht wie es gebaut ist.","example":"Ein Meldeformular für den Empfang und eine wöchentliche Übersicht, wie viele Meldungen abgeschlossen wurden."},"uk":{"question":"Який обсяг першої версії можете запропонувати компанії?","help":"Спирайся на те, що має з’явитися до першої версії в Загальному. Напиши, що отримує клієнт, а не як це збудовано.","example":"Форма заявок для рецепції й щотижневий звіт, скільки заявок закрито."},"es":{"question":"¿Qué alcance de la primera versión podéis ofrecer a una empresa?","help":"Básate en lo que debe estar listo para la primera versión en General. Escribe qué recibe el cliente, no cómo está construido.","example":"Un formulario de incidencias para recepción y un resumen semanal de cuántas se han cerrado."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'offer'
    and s.key = 'scope' and f.key = 'what';
update public.stage_fields f set translations = '{"de":{"question":"Wie hoch ist der Preis oder wie berechnet ihr ihn, und wofür genau zahlen Kunden?","help":"Betrag, Satz oder Formel. Ergänze, ob es ein Abo, eine Einführung oder beides ist.","example":"600 € für die Einführung und 200 € pro Monat für die Nutzung durch bis zu 5 Personen."},"uk":{"question":"Яка ціна або як ви її рахуєте і за що саме платить клієнт?","help":"Сума, ставка чи формула. Допиши, чи це підписка, впровадження чи і те, і те.","example":"24 000 грн за впровадження й 8 000 грн на місяць за користування до 5 осіб."},"es":{"question":"¿Cuál es el precio o cómo lo calculáis, y por qué paga exactamente el cliente?","help":"Cantidad, tarifa o fórmula. Añade si es una suscripción, una implantación o ambas.","example":"600 € por la implantación y 200 € al mes por el uso de hasta 5 personas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'offer'
    and s.key = 'scope' and f.key = 'price';
update public.stage_fields f set translations = '{"de":{"question":"Wie lange dauert die Zusammenarbeit oder Umsetzung?","help":"Wenn die Dauer keine Rolle spielt, schreib „Ohne festes Ende“ und was die Zusammenarbeit dann beendet.","example":"Einführung 3 Wochen. Unbefristetes Abo mit monatlicher Kündigung."},"uk":{"question":"Як довго триває співпраця чи реалізація?","help":"Якщо час не має значення, напиши «Без визначеного кінця» і що тоді завершує співпрацю.","example":"Впровадження 3 тижні. Підписка безстрокова, з місячним повідомленням про розірвання."},"es":{"question":"¿Cuánto dura la colaboración o la implantación?","help":"Si el plazo no importa, escribe «Sin fin definido» y qué pone fin entonces a la colaboración.","example":"Implantación de 3 semanas. Suscripción indefinida con preaviso de un mes."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'offer'
    and s.key = 'scope' and f.key = 'term';
update public.stage_subpoints s set translations = '{"de":{"title":"Test, falls nötig"},"uk":{"title":"Тест, якщо потрібен"},"es":{"title":"Prueba, si hace falta"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'offer' and s.key = 'pilot';
update public.stage_fields f set translations = '{"de":{"question":"Was bekommen Kunden im Test und woran erkennt ihr, dass er beendet ist?","help":"Wenn es keinen Test gibt, schreib „Entfällt“.","example":"14 Tage mit einem Team. Ende, wenn wir die gesparten Stunden gezählt haben und der Kunde über das Abo entscheidet."},"uk":{"question":"Що клієнт отримує в тесті і за чим ви вважаєте його завершеним?","help":"Якщо тесту немає, напиши «Не стосується».","example":"14 днів на одній команді. Кінець, коли порахуємо заощаджені години і клієнт вирішить, чи бере підписку."},"es":{"question":"¿Qué recibe el cliente en la prueba y cuándo la dais por terminada?","help":"Si no hay prueba, escribe «No aplica».","example":"14 días con un equipo. Termina cuando contemos las horas ahorradas y el cliente decida si contrata la suscripción."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'offer'
    and s.key = 'pilot' and f.key = 'deal';
update public.stage_points p set translations = '{"de":{"title":"Bereite den Beginn der Zusammenarbeit vor","duration_hint":"Etwa 20 Minuten","guide_body":"Den Umfang klären, bevor ihr für Kunden baut\nGeht zu den Vereinbarungen aus der Ideenphase zurück und listet die Funktionen auf, die für den versprochenen Nutzen unverzichtbar sind. Legt erst dann die Kontenstruktur, Rollen, Berechtigungen und Integrationen fest sowie das, was ihr auf später verschiebt.\nAuf dieser Grundlage lässt sich der Umfang der ersten Version abschließen und festhalten, woran ihr ein Element als fertig erkennt.\n§\nDaten einer Firma dürfen nicht zu einer anderen gelangen\nLegt fest, wie ihr die Daten einzelner Firmen trennt, welchen Zugriff Nutzer haben und welche Integrationen nötig sind.\nNotiert technische Einschränkungen, die den Bau beeinflussen. Vor allem die Situation, in der eine falsche Zugriffskonfiguration die Daten eines Kunden einem anderen zeigen würde.\n§\nSicherheit und Papiere\nLegt fest, welche Geschäfts- und personenbezogenen Daten ihr verarbeitet, wer Zugriff darauf hat, wie sie geschützt sind und wann sie gelöscht werden sollen.\nListet typische Anforderungen von Firmen auf, zum Beispiel Single Sign-On, sowie Dokumente: Nutzungsbedingungen, Datenschutzerklärung, Auftragsverarbeitungsvertrag, wenn ihr personenbezogene Daten verarbeitet.\nMacht daraus eine Checkliste und bestätigt sie, bevor ihr das Produkt einem Kunden zur Verfügung stellt.\n§\nTeam und Budget für den Umsetzungsstart\nLegt Rollen und Kompetenzen fest, verteilt Verantwortung und benennt Lücken: Macht ihr es selbst, vergebt ihr es extern oder sucht ihr jemanden?\nBereitet Werkzeuge, Budget und Zeitrahmen vor. Prüft, ob das für den vereinbarten Umfang reicht. Vor dem Bau soll das Team wissen, dass es Kompetenzen, Mittel und Zeit hat, statt den Mangel unterwegs zu entdecken.\n§\nVom Kauf zur ersten Nutzung\nBeschreibt den Weg der Kunden vom Kauf zur Nutzung: welche Informationen, Zugänge und Konfigurationen nötig sind und wer dafür verantwortlich ist.\nLegt fest, wie ihr Anfragen bearbeitet und wie ihr Kunden zwischen Vertrieb, Einführung und Support übergebt, damit keine Informationen verloren gehen.\n§\nWas ihr vom Kunden braucht\nListet Materialien, Daten, Zugänge und Zustimmungen auf, die Kunden vor dem Start übergeben müssen. Wenn ihr nichts braucht, schreibt das direkt.\nJe weniger Aufgaben ganz am Anfang, desto schneller kommen Kunden zur ersten Nutzung. Eine einfache Liste für sie reicht.\n§\nArbeitsteilung\nListet auf, was vor dem Start euer Team und was der Kunde erledigt. Benennt Personen auf beiden Seiten.\nDie häufigste Verzögerung ist eine fehlende verantwortliche Person auf Kundenseite. Stellt sicher, dass sie vom ersten Tag an benannt ist.\n§\nFormalitäten auf diesem Weg\nSchreibt die Schritte von der Kaufzusage bis zu dem Moment auf, in dem Kunden die Lösung selbstständig nutzen. Berücksichtigt Vertrag, NDA, Bestellung oder Rechnung, wenn es das bei euch gibt.\nEine Vorlage und eine elektronische Signatur verkürzen die Zeit von der Entscheidung bis zum ersten echten Nutzen. Das ist das Ziel dieses Punkts."},"uk":{"title":"Підготуй початок співпраці","duration_hint":"Близько 20 хвилин","guide_body":"Обсяг, перш ніж почнете будувати під клієнта\nПоверніться до домовленостей з етапу ідеї й випишіть функції, необхідні для обіцяної користі. Лише потім визначте структуру акаунтів, ролі, повноваження й інтеграції, а також те, що відкладаєте на потім.\nНа цій основі можна закрити обсяг першої версії й записати, за чим ви вважаєте елемент готовим.\n§\nДані однієї компанії не можуть потрапити до іншої\nВизначте, як відокремлюєте дані окремих компаній, який обсяг доступу користувачів і які інтеграції потрібні.\nЗапишіть технічні обмеження, що впливають на створення. Особливо ситуацію, у якій неправильне налаштування доступу показало б дані одного клієнта іншому.\n§\nБезпека й документи\nВизначте, які бізнесові та персональні дані ви оброблятимете, хто має до них доступ, як вони захищені і коли їх слід видалити.\nВипишіть вимоги, типові для компаній, наприклад єдиний вхід (SSO), а також документи: правила користування, політику, договір доручення обробки, якщо обробляєте персональні дані.\nЗробіть із цього чек-лист і підтвердьте його, перш ніж надати продукт клієнтові.\n§\nКоманда й бюджет на старт реалізації\nВизначте ролі й компетенції, призначте відповідальність і вкажіть прогалини: робите самі, замовите ззовні чи шукаєте людину.\nПідготуйте інструменти, бюджет і часові рамки. Перевірте, чи цього досить на погоджений обсяг. Перед створенням команда має знати, що в неї є компетенції, кошти й час, а не виявляти брак у процесі.\n§\nВід покупки до першого використання\nОпишіть шлях клієнта від покупки до користування: яка інформація, доступи й налаштування потрібні і хто за них відповідає.\nВизначте, як обробляєте звернення і як передаєте клієнта між продажами, впровадженням і підтримкою, щоб інформація не губилася дорогою.\n§\nЩо вам потрібно від клієнта\nВипишіть матеріали, дані, доступи й згоди, які клієнт має передати до старту. Якщо нічого не потрібно, напишіть це прямо.\nЩо менше завдань на самому початку, то швидше клієнт дійде до першого використання. Простого списку для нього досить.\n§\nРозподіл роботи\nВипишіть, що до старту робить ваша команда, а що клієнт. Призначте людей з обох боків.\nНайчастіша затримка — відсутність відповідальної людини з боку клієнта. Переконайтеся, що її визначено з першого дня.\n§\nФормальності на цьому шляху\nРозпишіть кроки від згоди на покупку до моменту, коли клієнт самостійно користується рішенням. Врахуйте договір, NDA, замовлення чи рахунок, якщо вони у вас є.\nШаблон і електронний підпис скорочують час від рішення до першої реальної користі. Це і є мета цього пункту."},"es":{"title":"Prepara el inicio de la colaboración","duration_hint":"Unos 20 minutos","guide_body":"El alcance, antes de construir para el cliente\nVolved a lo acordado en la fase de idea y enumerad las funciones imprescindibles para el beneficio prometido. Solo después definid la estructura de cuentas, los roles, los permisos y las integraciones, y lo que dejáis para más adelante.\nCon esto se puede cerrar el alcance de la primera versión y anotar cuándo dais un elemento por terminado.\n§\nLos datos de una empresa no pueden llegar a otra\nDefinid cómo separáis los datos de cada empresa, qué acceso tienen los usuarios y qué integraciones hacen falta.\nAnotad las limitaciones técnicas que afectan a la construcción. Sobre todo la situación en la que una mala configuración del acceso mostraría los datos de un cliente a otro.\n§\nSeguridad y documentación\nDefinid qué datos empresariales y personales vais a tratar, quién tiene acceso, cómo se protegen y cuándo deben borrarse.\nEnumerad requisitos habituales en empresas, como el inicio de sesión único, y los documentos: condiciones de uso, política de privacidad y contrato de encargado del tratamiento si tratáis datos personales.\nConvertidlo en una lista de comprobación y confirmadla antes de poner el producto a disposición del cliente.\n§\nEquipo y presupuesto para arrancar\nDefinid roles y competencias, asignad responsabilidades y señalad carencias: lo hacéis vosotros, lo externalizáis o buscáis a alguien.\nPreparad herramientas, presupuesto y plazos. Comprobad si bastan para el alcance acordado. Antes de construir, el equipo tiene que saber que tiene las competencias, los medios y el tiempo, y no descubrir la carencia por el camino.\n§\nDe la compra al primer uso\nDescribid el camino del cliente desde la compra hasta el uso: qué información, accesos y configuraciones hacen falta y quién se encarga.\nDefinid cómo gestionáis las solicitudes y cómo pasa el cliente de ventas a implantación y a soporte sin que se pierda información.\n§\nQué necesitáis del cliente\nEnumerad los materiales, datos, accesos y consentimientos que el cliente debe entregar antes de empezar. Si no necesitáis nada, decidlo claramente.\nCuantas menos tareas al principio, antes llegará el cliente al primer uso. Una lista sencilla para él es suficiente.\n§\nReparto del trabajo\nEnumerad qué hace vuestro equipo antes del inicio y qué hace el cliente. Asignad personas en ambos lados.\nEl retraso más habitual es que falte una persona responsable del lado del cliente. Aseguraos de que está designada desde el primer día.\n§\nTrámites en este camino\nDescribid los pasos desde la aprobación de la compra hasta que el cliente usa la solución por su cuenta. Incluid contrato, NDA, pedido o factura, si los tenéis.\nUna plantilla y la firma electrónica acortan el tiempo entre la decisión y el primer beneficio real. Ese es el objetivo de este punto."}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'kickoff';
update public.stage_subpoints s set translations = '{"de":{"title":"Was vor dem Start passieren muss"},"uk":{"title":"Що має статися до старту"},"es":{"title":"Qué tiene que pasar antes de empezar"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'kickoff' and s.key = 'needs';
update public.stage_fields f set translations = '{"de":{"question":"Was braucht ihr vom Kunden, bevor er mit der Nutzung beginnt?","help":"Daten, Zugänge, Zustimmungen, Materialien. Wenn ihr nichts braucht, trag „Nichts“ ein.","example":"Liste der Personen, die Zugang bekommen.\nAnsprechperson beim Kunden, die Fragen entgegennimmt."},"uk":{"question":"Що вам потрібно від клієнта, перш ніж він почне користуватися?","help":"Дані, доступи, згоди, матеріали. Якщо нічого не потрібно, впиши «Нічого».","example":"Список людей, які отримають доступ.\nЛюдина з боку клієнта, яка приймає запитання."},"es":{"question":"¿Qué necesitáis del cliente antes de que empiece a usarlo?","help":"Datos, accesos, consentimientos, materiales. Si no necesitáis nada, escribe «Nada».","example":"Lista de personas que recibirán acceso.\nPersona del cliente que atiende las preguntas."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'needs' and f.key = 'from_client';
update public.stage_fields f set translations = '{"de":{"question":"Was muss euer Team vor dem Start erledigen?","help":"Eine Aktion pro Zeile.","example":"Den Bereich der Firma anlegen.\nDen Vertrag zur Unterschrift schicken."},"uk":{"question":"Що до старту має зробити ваша команда?","help":"Одна дія на позицію.","example":"Створити простір компанії.\nНадіслати договір на підпис."},"es":{"question":"¿Qué tiene que hacer vuestro equipo antes de empezar?","help":"Una acción por línea.","example":"Crear el espacio de la empresa.\nEnviar el contrato para firmar."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'needs' and f.key = 'ours';
update public.stage_fields f set translations = '{"de":{"question":"Was muss der Kunde vor dem Start erledigen?","help":"Eine Aktion pro Zeile. Wenn die Liste nur „Nichts“ enthält, trag es als einen Eintrag ein.","example":"Den Vertrag unterschreiben.\nEine verantwortliche Person auf eigener Seite benennen."},"uk":{"question":"Що до старту має зробити клієнт?","help":"Одна дія на позицію. Якщо список — лише «Нічого», впиши це одним записом.","example":"Підписати договір.\nВказати відповідальну людину зі свого боку."},"es":{"question":"¿Qué tiene que hacer el cliente antes de empezar?","help":"Una acción por línea. Si la lista es solo «Nada», escríbelo en una única entrada.","example":"Firmar el contrato.\nDesignar una persona responsable por su parte."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'needs' and f.key = 'theirs';
update public.stage_subpoints s set translations = '{"de":{"title":"Von der Zusage zur ersten Nutzung"},"uk":{"title":"Від згоди до першого використання"},"es":{"title":"De la aprobación al primer uso"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2b' and p.key = 'kickoff' and s.key = 'start';
update public.stage_fields f set translations = '{"de":{"question":"Welche Schritte folgen von der Kaufbestätigung bis zu dem Moment, in dem Kunden die Lösung nutzen können?","help":"Ergänze die Formalitäten, die es bei euch gibt: Vertrag, NDA, Bestellung, Rechnung, Materialien.","example":"Wir unterschreiben den Vertrag.\nWir stellen die Rechnung für die Einführung.\nWir richten Zugänge ein und vereinbaren einen Termin für die erste Nutzung."},"uk":{"question":"Які наступні дії від підтвердження покупки до моменту, коли клієнт може користуватися?","help":"Допиши формальності, які у вас є: договір, NDA, замовлення, рахунок, матеріали.","example":"Підписуємо договір.\nВиставляємо рахунок за впровадження.\nСтворюємо доступи й домовляємося про час першого використання."},"es":{"question":"¿Qué pasos siguen desde la confirmación de la compra hasta que el cliente puede usarlo?","help":"Añade los trámites que tengáis: contrato, NDA, pedido, factura, materiales.","example":"Firmamos el contrato.\nEmitimos la factura de la implantación.\nCreamos los accesos y fijamos la hora del primer uso."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'start' and f.key = 'path';
update public.stage_fields f set translations = '{"de":{"question":"Welche Kundendaten werdet ihr haben und wer außerhalb dieser Firma kann sie sehen?","help":"Personenbezogene Daten, Firmendaten, Dateien. Wenn zwei Kunden die Materialien des anderen nicht sehen dürfen, schreib das direkt. Wenn ihr keine Kundendaten verarbeitet, schreib „Wir verarbeiten keine Kundendaten“.","example":"Wir haben Vornamen der Beschäftigten und den Inhalt der Meldungen. Sie sieht nur diese Firma und die Person aus unserem Team, die die Einführung leitet. Andere Kunden sehen sie nicht."},"uk":{"question":"Які дані клієнта ви матимете і хто поза цією компанією може їх бачити?","help":"Персональні дані, дані компанії, файли. Якщо два клієнти не можуть бачити матеріалів одне одного, напиши це прямо. Коли даних клієнта не обробляєте, напиши «Не обробляємо даних клієнта».","example":"Маємо імена працівників і зміст заявок. Їх бачить лише ця компанія і людина з нашої команди, яка веде впровадження. Інший клієнт цього не бачить."},"es":{"question":"¿Qué datos del cliente tendréis y quién fuera de esa empresa puede verlos?","help":"Datos personales, datos de la empresa, archivos. Si dos clientes no pueden ver los materiales del otro, dilo claramente. Si no tratáis datos del cliente, escribe «No tratamos datos del cliente».","example":"Tenemos los nombres de los empleados y el contenido de las incidencias. Solo los ve esa empresa y la persona de nuestro equipo que lleva la implantación. Otros clientes no los ven."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2b' and p.key = 'kickoff'
    and s.key = 'start' and f.key = 'data';
update public.stage_categories c set translations = '{"de":{"title":"B2C","intro":"Lege fest, wie Käufer zurücktreten oder melden können, dass ein Kauf nicht funktioniert, und wie ihr das in der ersten Version bearbeitet."},"uk":{"title":"B2C","intro":"Визнач, як покупець може відмовитися або повідомити, що покупка не працює, і як ви це обробите в першій версії."},"es":{"title":"B2C","intro":"Define cómo puede desistir el comprador o avisar de que la compra no funciona, y cómo lo gestionaréis en la primera versión."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'preparation' and t.version = 1 and c.key = 'b2c';
update public.stage_points p set translations = '{"de":{"title":"Bereite Rückgaben und Reklamationen vor","duration_hint":"Etwa 20 Minuten","guide_body":"Wovon Rückgaben abhängen\nDie Regeln hängen vom Land ab, in dem du zu verkaufen beginnst, und davon, ob du online oder vor Ort verkaufst. Notiere zuerst Kanal, Zahlung und Übergabe. Ohne das lässt sich ein Rücktritt vom Kauf nicht sinnvoll beschreiben.\nNotiere, wann Kunden zurücktreten können und was du tun musst, wenn der Kauf nicht wie versprochen funktioniert. Wenn eine Frist noch nicht geprüft ist, schreib „zu prüfen“ bei der konkreten Regel. Rate keine Zahl.\n§\nWas das Produkt macht und was ihr von Hand erledigt\nNotiere für die Rückgabe und gesondert für die Reklamation, wie Kunden sich melden.\nAuf Seiten des Produkts oder Verkaufsorts reicht für den Start, was es erlaubt, einen Kontakt zu finden und anzugeben, welchen Kauf die Meldung betrifft.\nDen Rest könnt ihr von Hand erledigen: Meldung prüfen, antworten und die Rückerstattung veranlassen. Stimme diese Aufteilung mit der Person ab, die die erste Version baut.","guide_sources":["Regeln zu Widerruf und Reklamation für das Land und die Art des ersten Verkaufs."]},"uk":{"title":"Підготуй повернення й рекламації","duration_hint":"Близько 20 хвилин","guide_body":"Від чого залежать повернення\nПравила залежать від країни, де ти починаєш продажі, і від того, чи продаєш через інтернет, чи на місці. Спершу запиши канал, оплату й отримання. Без цього не вдасться осмислено описати відмову від покупки.\nЗапиши, коли клієнт може відмовитися і що ти маєш зробити, якщо покупка не працює так, як обіцяно. Якщо термін ще не перевірено, напиши «перевірити» біля конкретного правила. Не вгадуй числа.\n§\nЩо робить продукт, а що ви робите вручну\nДля повернення й окремо для рекламації запиши, як клієнт звертається.\nЗ боку продукту чи місця продажу на старт досить того, що дає змогу знайти контакт і вказати, якої покупки стосується звернення.\nРешту можна зробити вручну: перевірити звернення, відповісти й доручити повернення грошей. Узгодь цей розподіл із людиною, яка створює першу версію.","guide_sources":["Правила відмови й рекламації, властиві для країни та способу першого продажу."]},"es":{"title":"Prepara devoluciones y reclamaciones","duration_hint":"Unos 20 minutos","guide_body":"De qué dependen las devoluciones\nLas reglas dependen del país donde empiezas a vender y de si vendes por internet o en persona. Anota primero el canal, el pago y la entrega. Sin eso no se puede describir con sentido el desistimiento de la compra.\nAnota cuándo puede desistir el cliente y qué tienes que hacer si la compra no funciona como se prometió. Si un plazo aún no está comprobado, escribe «por comprobar» junto a la regla concreta. No adivines cifras.\n§\nQué hace el producto y qué hacéis a mano\nPara la devolución y, por separado, para la reclamación, anota cómo avisa el cliente.\nPor parte del producto o del punto de venta basta, para empezar, con que permita encontrar el contacto e indicar a qué compra se refiere el aviso.\nEl resto podéis hacerlo a mano: revisar el aviso, responder y ordenar el reembolso. Acuerda este reparto con quien construye la primera versión.","guide_sources":["Normas de desistimiento y reclamación propias del país y de la forma de la primera venta."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2c' and p.key = 'returns';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie der erste Kauf aussieht"},"uk":{"title":"Як виглядає перша покупка"},"es":{"title":"Cómo es la primera compra"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2c' and p.key = 'returns' and s.key = 'channel';
update public.stage_fields f set translations = '{"de":{"question":"Wo findet der erste Verkauf statt und wie zahlen Käufer und erhalten den Kauf?","help":"Online oder stationär, Zahlungsart und Übergabeart. Davon hängen Rückgaben ab.","example":"Onlineshop. Zahlung bei der Bestellung. Paket per Kurier oder Selbstabholung."},"uk":{"question":"Де відбувається перший продаж і як покупець платить та отримує покупку?","help":"Інтернет чи стаціонарне місце, спосіб оплати й спосіб отримання. Від цього залежать повернення.","example":"Інтернет-магазин. Оплата при замовленні. Посилка кур’єром або самовивіз."},"es":{"question":"¿Dónde se hace la primera venta y cómo paga y recibe la compra el comprador?","help":"Online o en tienda física, forma de pago y forma de entrega. De esto dependen las devoluciones.","example":"Tienda online. Pago al hacer el pedido. Paquete por mensajería o recogida en persona."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2c' and p.key = 'returns'
    and s.key = 'channel' and f.key = 'where';
update public.stage_subpoints s set translations = '{"de":{"title":"Wann Käufer zurücktreten können"},"uk":{"title":"Коли покупець може відмовитися"},"es":{"title":"Cuándo puede desistir el comprador"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2c' and p.key = 'returns' and s.key = 'rights';
update public.stage_fields f set translations = '{"de":{"question":"Wann können Kunden vom Kauf zurücktreten und was musst du tun, wenn der Kauf nicht wie versprochen funktioniert?","help":"Berücksichtige das Land, in dem du beginnst, und die Verkaufsart. Wenn eine Frist noch nicht geprüft ist, schreib „zu prüfen“ bei der konkreten Regel, rate keine Zahl.","example":"Onlineverkauf in Deutschland: Kunden können innerhalb von 14 Tagen nach Erhalt widerrufen. Wenn das Produkt nicht funktioniert, nehmen wir die Reklamation an und erstatten das Geld oder tauschen das Stück aus."},"uk":{"question":"Коли клієнт може відмовитися від покупки і що ти маєш зробити, якщо покупка не працює так, як обіцяно?","help":"Врахуй країну, з якої починаєш, і спосіб продажу. Якщо термін ще не перевірено, напиши «перевірити» біля конкретного правила, не вгадуй числа.","example":"Продаж через інтернет в Україні: клієнт може відмовитися протягом 14 днів від отримання. Коли продукт не працює, приймаємо рекламацію й повертаємо гроші або замінюємо одиницю."},"es":{"question":"¿Cuándo puede el cliente desistir de la compra y qué tienes que hacer si no funciona como se prometió?","help":"Ten en cuenta el país por el que empiezas y la forma de venta. Si un plazo no está comprobado, escribe «por comprobar» junto a la regla concreta; no adivines cifras.","example":"Venta online en España: el cliente puede desistir en 14 días desde la recepción. Si el producto no funciona, aceptamos la reclamación y devolvemos el dinero o cambiamos la unidad."}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2c' and p.key = 'returns'
    and s.key = 'rights' and f.key = 'rule';
update public.stage_subpoints s set translations = '{"de":{"title":"Wie ihr Rückgabe und Reklamation bearbeitet"},"uk":{"title":"Як ви обробите повернення й рекламацію"},"es":{"title":"Cómo gestionaréis devolución y reclamación"}}'::jsonb
  from public.stage_points p, public.stage_categories c, public.stage_templates t
  where s.point_id = p.id and p.category_id = c.id and c.template_id = t.id and t.key = 'preparation' and t.version = 1
    and c.key = 'b2c' and p.key = 'returns' and s.key = 'handling';
update public.stage_fields f set translations = '{"de":{"question":"Notiere für Rückgabe und Reklamation, wie Kunden sich melden und was ihr tut.","help":"Rückgabe und Reklamation getrennt. Schreib, was das Produkt oder der Verkaufsort können muss und was ihr von Hand erledigt.","example":"Rückgabe. Kunden schreiben an die Adresse aus der Bestellbestätigung und nennen die Nummer. Wir prüfen die Frist, bestätigen den Paketeingang und veranlassen die Rückerstattung.","config":{"add_label":"Ablauf hinzufügen","columns":[{"key":"kind","label":"Rückgabe oder Reklamation","placeholder":"Rückgabe oder Reklamation"},{"key":"report","label":"Wie Kunden sich melden","placeholder":"E-Mail, Formular, im Laden"},{"key":"product","label":"Was Produkt oder Verkauf ermöglichen muss","placeholder":"Z. B. Kontakt und Kaufnummer finden"},{"key":"manual","label":"Was ihr von Hand erledigt","placeholder":"Prüfung, Antwort, Rückerstattung"}]}},"uk":{"question":"Для повернення й рекламації запиши, як клієнт звернеться і що ви зробите.","help":"Окремо повернення, окремо рекламація. Напиши, що має вміти продукт чи місце продажу, а що ви зробите вручну.","example":"Повернення. Клієнт пише на адресу з підтвердження замовлення й вказує номер. Ми перевіряємо термін, підтверджуємо отримання посилки й доручаємо повернення грошей.","config":{"add_label":"Додати шлях","columns":[{"key":"kind","label":"Повернення чи рекламація","placeholder":"Повернення або рекламація"},{"key":"report","label":"Як клієнт звертається","placeholder":"Пошта, форма, у магазині"},{"key":"product","label":"Що має уможливлювати продукт чи продаж","placeholder":"Напр. знайти контакт і номер покупки"},{"key":"manual","label":"Що ви зробите вручну","placeholder":"Перевірка, відповідь, повернення грошей"}]}},"es":{"question":"Para la devolución y la reclamación, anota cómo avisará el cliente y qué haréis.","help":"Devolución y reclamación por separado. Escribe qué debe permitir el producto o el punto de venta y qué haréis a mano.","example":"Devolución. El cliente escribe a la dirección de la confirmación del pedido e indica el número. Comprobamos el plazo, confirmamos la recepción del paquete y ordenamos el reembolso.","config":{"add_label":"Añadir proceso","columns":[{"key":"kind","label":"Devolución o reclamación","placeholder":"Devolución o reclamación"},{"key":"report","label":"Cómo avisa el cliente","placeholder":"Correo, formulario, en la tienda"},{"key":"product","label":"Qué debe permitir el producto o la venta","placeholder":"P. ej. encontrar el contacto y el número de compra"},{"key":"manual","label":"Qué haréis a mano","placeholder":"Revisión, respuesta, reembolso"}]}}}'::jsonb
  from public.stage_subpoints s, public.stage_points p, public.stage_categories c, public.stage_templates t
  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'preparation' and t.version = 1 and c.key = 'b2c' and p.key = 'returns'
    and s.key = 'handling' and f.key = 'flow';

-- ═══ execution v1 ═══
update public.stage_templates t set translations = '{"de":{"title":"Execution","subtitle":"Baue die erste Version","intro":"Du steuerst den Bau im Ziel-Tracker. Die Punkte des Programms sagen, welches Ergebnis verlangt ist. Zusätzliche Ziele blockieren den Übergang nicht.","finish_label":"Ich gehe zum MVP über"},"uk":{"title":"Execution","subtitle":"Збудуй першу версію","intro":"Ти ведеш створення в трекері цілей. Пункти програми кажуть, який результат потрібен. Додаткові цілі не блокують переходу.","finish_label":"Переходжу до MVP"},"es":{"title":"Execution","subtitle":"Construye la primera versión","intro":"Llevas la construcción en el tracker de objetivos. Los puntos del programa dicen qué resultado se exige. Los objetivos adicionales no bloquean el paso.","finish_label":"Paso al MVP"}}'::jsonb
  where t.key = 'execution' and t.version = 1;
update public.stage_categories c set translations = '{"de":{"title":"Allgemein","intro":"Diese Punkte betreffen jeden Bau. Die Kategorien ergänzen eigene Ergebnisse."},"uk":{"title":"Загальне","intro":"Ці пункти стосуються кожного створення. Категорії додають власні результати."},"es":{"title":"General","intro":"Estos puntos se aplican a cualquier construcción. Las categorías añaden sus propios resultados."}}'::jsonb
  from public.stage_templates t where c.template_id = t.id and t.key = 'execution' and t.version = 1 and c.key = 'general';
update public.stage_points p set translations = '{"de":{"title":"Wähle das nächste Ergebnis und verteile die Arbeit","duration_hint":"Etwa 15 Minuten","guide_body":"1.1. Lege fest, was fertig sein soll\nBeginne mit der Arbeit, deren Ergebnis den nächsten Schritt im Bau ermöglicht. Greif auf frühere Vereinbarungen und die Anforderungen deiner Kategorie zurück. Wenn du schon ein passendes Goal hast, also ein notiertes Ziel, öffne seine Karte. Ergänze nur fehlende Informationen.\nBenenne das Ziel so, dass sich nach der Erledigung prüfen lässt, was entstanden ist. Ein bloßes „Am Produkt arbeiten“ sagt wenig. Hilfreich ist das Muster: „Fertiges [Element], mit dem man [eine konkrete Handlung ausführen] kann“. Wenn sich unter einem Namen mehrere unabhängige Ergebnisse verbergen, wähle das als Nächstes benötigte oder teile die Arbeit in kleinere Ziele.\nLege schon jetzt den Proof fest, also den Nachweis der Erledigung. Das kann eine konkrete Datei sein, ein Foto, eine Aufnahme der Funktion oder ein festgehaltenes Testergebnis. Passe ihn an das Ziel und die Anforderungen des Programmpunkts an. Ein Foto kann zeigen, wie ein Gegenstand aussieht, aber um seine Funktion zu bestätigen, braucht es vielleicht eine Aufnahme oder ein Prüfergebnis. Am Anfang legst du fest, was du zeigen wirst; den fertigen Nachweis fügst du nach der Arbeit hinzu.\n1.2. Verteile die Arbeit und lege einen Termin fest\nWähle eine Person, die dafür sorgt, dass das ganze Ziel erreicht wird. Sie kann sich von anderen helfen lassen, ist aber dafür verantwortlich, die nötigen Teile zusammenzubringen und die Arbeit abzuschließen. Nutze die in Preparation vereinbarte Aufteilung der Verantwortung. Wenn du allein arbeitest, bist du Eigentümerin oder Eigentümer des Ziels.\nVereinbare den Termin mit der ausführenden Person. Berücksichtige ihre Verfügbarkeit und ob sie zuerst das Ergebnis einer anderen Person braucht. Wenn das Ganze für den gewählten Termin zu groß ist, trenne ein kleineres Ergebnis ab, das sich in dieser Zeit erreichen lässt. Behalte die übrige Arbeit für später.\nFüge Aufgaben hinzu, wenn sie helfen, die Arbeit auf Personen zu verteilen oder ihre Reihenfolge festzulegen. Jede sollte klar sagen, was zu tun ist. Vermeide es, einzelne Klicks und offensichtliche Handgriffe aufzuschreiben. Wenn jemand auf das Ergebnis einer anderen Person wartet, legt einen Termin für die Übergabe dieses Teils fest.\nHänge Materialien an, ohne die die ausführende Person Informationen suchen oder nachfragen müsste. Wähle das aktuelle Dokument oder eine schon in Vairo gespeicherte Datei. Materialien zu anderen Arbeiten können an ihrem Ort bleiben.","guide_sources":["Geoff Ralston, YC’s Essential Startup Advice (2017): Konzentration auf die wichtigste Arbeit und Vereinfachung des Umfangs. Die Beschreibung von Goals und Proof ist eine Ausarbeitung für Vairo.","Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): Aufteilung der Verantwortung, Verfügbarkeit und Reihenfolge der Arbeiten. Die Zuweisungen in Goal- und Aufgabenkarten wenden diese Hinweise in Vairo an."]},"uk":{"title":"Обери найближчий результат і розподіли роботу","duration_hint":"Близько 15 хвилин","guide_body":"1.1. Визнач, що має бути готове\nПочни з роботи, результат якої дасть змогу зробити наступний крок у створенні. Звернися до попередніх домовленостей і вимог своєї категорії. Якщо вже маєш відповідний Goal, тобто записану ціль, відкрий її картку. Доповни лише відсутню інформацію.\nНазви ціль так, щоб після виконання можна було перевірити, що з’явилося. Саме «Попрацювати над продуктом» мало що каже. Корисний шаблон: «Готовий [елемент], який дає змогу [виконати конкретну дію]». Якщо під однією назвою ховається кілька незалежних результатів, обери найближче потрібний або поділи роботу на менші цілі.\nВже зараз визнач proof, тобто доказ виконання. Це може бути конкретний файл, фото, запис роботи або запис результату спроби. Добери його до цілі й вимог пункту програми. Фото може показати вигляд предмета, але для підтвердження його роботи може знадобитися запис чи результат перевірки. На початку ти визначаєш, що покажеш; готовий доказ додаси після виконання роботи.\n1.2. Розподіли роботу й визнач термін\nОбери одну людину, яка подбає про досягнення всієї цілі. Вона може користуватися допомогою інших, але відповідає за збирання потрібних частин і доведення роботи до кінця. Використай розподіл відповідальності, погоджений у Preparation. Коли працюєш сам, власник цілі — ти.\nПогодь термін із виконавцем. Врахуй його доступність і те, чи спершу йому потрібен результат роботи іншої людини. Якщо все разом завелике для обраного терміну, виокрем менший результат, якого можна досягти за цей час. Решту роботи збережи на потім.\nДодавай завдання тоді, коли вони допомагають розподілити роботу між людьми або визначити її порядок. Кожне має чітко вказувати, що треба зробити. Уникай розписування окремих кліків і очевидних дій. Якщо хтось чекає на результат іншої людини, домовтеся про термін передачі цієї частини.\nПрикріпи матеріали, без яких виконавцеві доведеться шукати інформацію чи перепитувати. Обери актуальний документ або файл, уже збережений у Vairo. Матеріали щодо інших робіт можуть залишитися на своїх місцях.","guide_sources":["Geoff Ralston, YC’s Essential Startup Advice (2017): зосередження на найважливішій роботі й спрощення обсягу. Опис Goals і proof — розробка для Vairo.","Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): розподіл відповідальності, доступність і визначення порядку робіт. Призначення в картках Goals і завдань — застосування цих порад у Vairo."]},"es":{"title":"Elige el próximo resultado y reparte el trabajo","duration_hint":"Unos 15 minutos","guide_body":"1.1. Define qué tiene que estar listo\nEmpieza por el trabajo cuyo resultado permita dar el siguiente paso en la construcción. Recurre a lo acordado antes y a los requisitos de tu categoría. Si ya tienes un Goal adecuado, es decir, un objetivo anotado, abre su tarjeta. Completa solo la información que falte.\nNombra el objetivo de forma que, al terminar, se pueda comprobar qué se ha hecho. Un simple «Trabajar en el producto» dice poco. Un patrón útil es: «[Elemento] listo que permite [hacer una acción concreta]». Si bajo un mismo nombre hay varios resultados independientes, elige el que hace falta antes o divide el trabajo en objetivos más pequeños.\nDefine ya el proof, es decir, la prueba de que está hecho. Puede ser un archivo concreto, una foto, una grabación del funcionamiento o el registro del resultado de una prueba. Ajústalo al objetivo y a los requisitos del punto del programa. Una foto puede mostrar el aspecto de un objeto, pero para confirmar que funciona quizá haga falta una grabación o el resultado de una comprobación. Al principio decides qué mostrarás; la prueba en sí la añadirás al terminar el trabajo.\n1.2. Reparte el trabajo y fija una fecha\nElige a una persona que se asegure de que se cumple todo el objetivo. Puede contar con ayuda de otros, pero es responsable de reunir las partes necesarias y terminar el trabajo. Usa el reparto de responsabilidades acordado en Preparation. Si trabajas en solitario, el responsable del objetivo eres tú.\nAcuerda la fecha con quien hace el trabajo. Ten en cuenta su disponibilidad y si antes necesita el resultado del trabajo de otra persona. Si el conjunto es demasiado grande para la fecha elegida, separa un resultado más pequeño que se pueda conseguir en ese tiempo. Guarda el resto del trabajo para después.\nAñade tareas cuando ayuden a repartir el trabajo entre personas o a fijar su orden. Cada una debe indicar claramente qué hay que hacer. Evita detallar clics sueltos y acciones obvias. Si alguien espera el resultado de otra persona, acordad la fecha de entrega de esa parte.\nAdjunta los materiales sin los cuales quien hace el trabajo tendría que buscar información o preguntar. Elige el documento actual o un archivo ya guardado en Vairo. Los materiales de otros trabajos pueden quedarse donde están.","guide_sources":["Geoff Ralston, YC’s Essential Startup Advice (2017): centrarse en el trabajo más importante y simplificar el alcance. La descripción de Goals y proof es una elaboración para Vairo.","Y Combinator, 10 Questions to Discuss with a Potential Co-founder (2023): reparto de responsabilidades, disponibilidad y orden de los trabajos. Las asignaciones en las tarjetas de Goals y tareas aplican estas pautas en Vairo."]}}'::jsonb
  from public.stage_categories c, public.stage_templates t
  where p.category_id = c.id and c.template_id = t.id and t.key = 'execution' and t.version = 1
    and c.key = 'general' and p.key = 'next';
