    and c.key = 'general' and p.key = 'next' and s.key = 'setup';
update public.stage_fields f set translations = '{"de":{"question":"Öffne ein bestehendes Ziel oder lege eines für die nächste Arbeit an.","help":"Ein Klick allein schließt den Punkt nicht ab. Es zählt ein Ziel mit benanntem Ergebnis, Eigentümer, Termin und festgelegtem Nachweis.","config":{"label":"Ziel aus der Preparation-Liste anlegen"}},"uk":{"question":"Відкрий наявну ціль або створи її для найближчої роботи.","help":"Саме клацання не зараховує пункт. Важить ціль із названим результатом, власником, терміном і визначеним доказом.","config":{"label":"Створити ціль зі списку Preparation"}},"es":{"question":"Abre un objetivo existente o crea uno para el próximo trabajo.","help":"Un clic no da el punto por hecho. Cuenta un objetivo con resultado nombrado, responsable, fecha y prueba definida.","config":{"label":"Crear objetivo de la lista de Preparation"}}}'::jsonb
