  where f.subpoint_id = s.id and s.point_id = p.id and p.category_id = c.id and c.template_id = t.id
    and t.key = 'execution' and t.version = 1 and c.key = 'general' and p.key = 'next'
    and s.key = 'setup' and f.key = 'open';
